def _five_optimizer_state_for_parameter(optimizer: object, parameter: object):
    """Read FiveAdam state without invoking Tensor/Parameter equality.

    FiveAdam currently keys its state by ``id(parameter)``.  Older in-memory
    or unpickled checkpoints may still contain the Parameter object itself as
    the key.  A normal ``dict.get(parameter)`` is unsafe when the dictionary
    contains an integer ``id(parameter)`` key: Python can call
    ``Parameter.__eq__`` during collision handling, producing a multi-element
    Tensor whose truth value is ambiguous.  Resolve keys by integer identity
    or object identity only; never use equality on a Tensor-like key.
    """
    state = getattr(optimizer, "state", None)
    if not isinstance(state, Mapping):
        return None
    parameter_id = id(parameter)
    # Do not call ``state.get(parameter_id)`` here.  A legacy Parameter key
    # can have the same hash as this integer and Python would then evaluate
    # the two keys for equality, recreating the ambiguous Tensor error.
    # ``is`` is the only safe way to match a Tensor/Parameter object; numeric
    # keys are compared only after an explicit scalar type check.
    for key, value in state.items():
        if isinstance(key, (int, np.integer)) and int(key) == parameter_id:
            return value
        if key is parameter:
            return value
    return None


def _five_optimizer_state_remove_for_parameter(optimizer: object, parameter: object):
    """Remove one FiveAdam state entry without comparing Tensor-like keys.

    A checkpoint written by an older optimizer may use the Parameter object as
    its dictionary key.  ``state.pop(id(parameter))`` is not safe in that case:
    the object hash is the same as its id, so dict lookup falls through to
    ``Parameter.__eq__`` and asks for the truth value of a multi-element
    tensor.  Rebuild the small state dictionary from identity-tested entries
    instead of invoking mapping lookup on the target key.
    """
    state = getattr(optimizer, "state", None)
    if not isinstance(state, MutableMapping):
        return None
    parameter_id = id(parameter)
    removed = None
    found = False
    retained: list[tuple[object, object]] = []
    for key, value in list(state.items()):
        matches = key is parameter or (
            isinstance(key, (int, np.integer)) and int(key) == parameter_id
        )
        if matches:
            if not found:
                removed = value
                found = True
            continue
        retained.append((key, value))
    if found:
        state.clear()
        state.update(retained)
    return removed


def _five_optimizer_state_set_for_parameter(
    optimizer: object,
    parameter: object,
    value: object,
) -> None:
    """Restore one FiveAdam state entry using the canonical integer key."""
    _five_optimizer_state_remove_for_parameter(optimizer, parameter)
    state = getattr(optimizer, "state", None)
    if not isinstance(state, MutableMapping):
        raise TypeError("FiveAdam optimizer state must be mutable")
    state[id(parameter)] = value

