def _policy_curriculum_permissions(policy: object):
    enabled = bool(getattr(policy, "curriculum_enabled", False))
    stage = normalize_curriculum_stage(getattr(policy, "curriculum_stage", "representation"))
    if isinstance(getattr(policy, "curriculum_state", None), CurriculumState):
        state = policy.curriculum_state
        state.ensure_compatible()
        state.enabled = enabled
        state.stage = stage
    return curriculum_permissions(
        stage,
        lifecycle_actor_scale=float(getattr(policy, "curriculum_lifecycle_actor_scale", 0.05) or 0.0),
        tensor_rule_authority=str(getattr(
            policy, "curriculum_tensor_rule_authority", "residual"
        ) or "residual"),
    ) if enabled else None
