def bounded_entry_behavior_policy(
    target_probabilities: np.ndarray,
    action_mask: np.ndarray,
    greedy_action: int,
    *,
    exploration_rate: float,
    min_action_probability: float,
    exploration_draw: float,
    action_draw: float,
) -> tuple[int, np.ndarray, bool]:
    """Sample a bounded behavior action without touching management rows.

    The exploit arm is the existing deterministic decision.  The exploration
    arm samples only a *different* legal HOLD/entry action, using the actor
    probabilities with a small non-zero floor.  The returned behavior
    distribution is exact and is retained in ``StepTrace`` for off-policy
    importance correction when the lifecycle settles.
    """

    target = np.asarray(target_probabilities, dtype=float).reshape(-1)
    legal = np.asarray(action_mask, dtype=bool).reshape(-1)
    if target.size != legal.size or target.size <= 0:
        raise ValueError("entry behavior target and mask must have the same non-zero width")
    legal = legal.copy()
    # This helper is deliberately limited to HOLD plus six entry commands.
    if legal.size > len(ENTRY_PREFERENCE_ACTIONS):
        legal[len(ENTRY_PREFERENCE_ACTIONS):] = False
    if not np.any(legal):
        legal[HOLD_ACTION] = True
    safe_target = np.where(legal & np.isfinite(target), np.maximum(target, 0.0), 0.0)
    if float(np.sum(safe_target)) <= 1e-12:
        safe_target = legal.astype(float)
    safe_target /= max(float(np.sum(safe_target)), 1e-12)
    greedy = int(greedy_action)
    if not (0 <= greedy < legal.size and bool(legal[greedy])):
        greedy = int(np.argmax(safe_target))

    behavior = np.zeros(target.size, dtype=float)
    alternatives = legal.copy()
    alternatives[greedy] = False
    rate = float(np.clip(exploration_rate, 0.0, 1.0))
    if not np.any(alternatives) or rate <= 0.0:
        behavior[greedy] = 1.0
        return greedy, behavior, False

    floor = float(np.clip(min_action_probability, 0.0, 1.0))
    alternative_weights = np.where(alternatives, np.maximum(safe_target, floor), 0.0)
    alternative_weights /= max(float(np.sum(alternative_weights)), 1e-12)
    behavior[greedy] = 1.0 - rate
    behavior += rate * alternative_weights
    behavior /= max(float(np.sum(behavior)), 1e-12)

    explore = float(np.clip(exploration_draw, 0.0, np.nextafter(1.0, 0.0))) < rate
    if not explore:
        return greedy, behavior, False
    cumulative = np.cumsum(alternative_weights)
    draw = float(np.clip(action_draw, 0.0, np.nextafter(1.0, 0.0)))
    sampled = int(np.searchsorted(cumulative, draw, side="right"))
    if sampled >= target.size or not bool(alternatives[sampled]):
        sampled = int(np.flatnonzero(alternatives)[-1])
    return sampled, behavior, sampled != greedy
# The quality auxiliary is deliberately keyed by immutable decision
# provenance. ``action`` and ``side`` remain separate so a MARKET_BUY bucket
# can learn a different setup from a generic long-side pattern.  Legacy seeds
# keep it auxiliary-only; an explicitly enabled Full-RL candidate can consume
# its calibrated value as a bounded learned residual, never as a mask/gate.
CONDITIONED_REPRESENTATION_CONTEXTS = (
    "TANG_MANH", "TANG_YEU", "GIAM_MANH", "GIAM_YEU", "RANGING", "VOLATILE", "OTHER",
)
CONDITIONED_REPRESENTATION_SIDES = ("FLAT", "BUY", "SELL")
CONDITIONED_REPRESENTATION_HEAD_COUNT = (
    len(CONDITIONED_REPRESENTATION_CONTEXTS) * ACTION_COUNT * len(CONDITIONED_REPRESENTATION_SIDES)
)


def _conditioned_representation_context_bucket_from_raw(raw_context: object) -> int:
    """Resolve one immutable regime bucket from a decision-time label."""

    raw = str(raw_context or "").upper()
    for index, label in enumerate(CONDITIONED_REPRESENTATION_CONTEXTS[:-1]):
        if label in raw:
            return index
    return len(CONDITIONED_REPRESENTATION_CONTEXTS) - 1


def _conditioned_representation_context_bucket(trace: "StepTrace") -> int:
    """Resolve a stable context bucket from the decision-time trace only."""

    details = dict(getattr(trace, "action_details", {}) or {})
    audit = dict(getattr(trace, "context_audit", {}) or {})
    return _conditioned_representation_context_bucket_from_raw(
        details.get("decision_policy_context", "")
        or audit.get("ma_context", "")
        or audit.get("context_nhan_dien", "")
        or ""
    )


def _conditioned_representation_side(selected_action: int) -> int:
    if int(selected_action) in {1, 3, 5}:
        return 1
    if int(selected_action) in {2, 4, 6}:
        return 2
    return 0


def conditioned_representation_condition(trace: "StepTrace", selected_action: int) -> tuple[int, dict[str, object]]:
    """Return the fixed `(context, action, side)` head row plus audit data."""

    context_index = _conditioned_representation_context_bucket(trace)
    action_index = int(np.clip(int(selected_action), 0, ACTION_COUNT - 1))
    side_index = _conditioned_representation_side(action_index)
    condition_index = (
        (context_index * ACTION_COUNT + action_index) * len(CONDITIONED_REPRESENTATION_SIDES)
        + side_index
    )
    return condition_index, {
        "context": CONDITIONED_REPRESENTATION_CONTEXTS[context_index],
        "action": action_index,
        "side": CONDITIONED_REPRESENTATION_SIDES[side_index],
        "condition_index": condition_index,
    }


