class GrowthSignal:
    error: float
    novelty: float
    conflict: float
    representation_need: float
    complexity: float

    @property
    def score(self) -> float:
        return self.error + self.novelty + self.conflict + self.representation_need - self.complexity


# ── M₁ Sub-Components ────────────────────────────────────────────────────────


class StateEncoder:
    __slots__ = ("w", "b", "activation_ema")

    def __init__(self, input_size: int, hidden_size: int, rng: np.random.Generator) -> None:
        scale = 1.0 / max(1.0, np.sqrt(float(input_size)))
        self.w = rng.normal(0.0, scale, size=(hidden_size, input_size))
        self.b = rng.normal(0.0, 0.05, size=hidden_size)
        self.activation_ema = 0.0

    def encode(self, x: np.ndarray) -> np.ndarray:
        return np.tanh(self.w @ x + self.b)

    def copy(self) -> "StateEncoder":
        enc = StateEncoder.__new__(StateEncoder)
        enc.w = self.w.copy()
        enc.b = self.b.copy()
        enc.activation_ema = float(self.activation_ema)
        return enc


class WorkingMemory:
    __slots__ = ("size", "state", "g_keep_w", "g_keep_b", "g_write_w", "g_write_b",
                 "g_erase_w", "g_erase_b", "w_write", "decay")

    def __init__(self, size: int, input_size: int, rng: np.random.Generator) -> None:
        scale = 1.0 / max(1.0, np.sqrt(float(input_size)))
        self.size = size
        self.state = np.zeros(size, dtype=float)
        self.g_keep_w = rng.normal(0.0, scale, size=input_size)
        self.g_keep_b = 0.0
        self.g_write_w = rng.normal(0.0, scale, size=input_size)
        self.g_write_b = 0.0
        self.g_erase_w = rng.normal(0.0, scale, size=input_size)
        self.g_erase_b = 0.0
        self.w_write = rng.normal(0.0, 0.1, size=(size, input_size))
        self.decay = 0.85

    def step(self, x: np.ndarray, candidate: np.ndarray | None = None) -> np.ndarray:
        g_keep = 1.0 / (1.0 + np.exp(-np.clip(float(self.g_keep_w @ x + self.g_keep_b), -60, 60)))
        g_write = 1.0 / (1.0 + np.exp(-np.clip(float(self.g_write_w @ x + self.g_write_b), -60, 60)))
        g_erase = 1.0 / (1.0 + np.exp(-np.clip(float(self.g_erase_w @ x + self.g_erase_b), -60, 60)))
        if candidate is None:
            candidate = np.tanh(self.w_write @ x)
        self.state = self.decay * g_keep * self.state + g_write * candidate
        self.state = (1.0 - g_erase) * self.state
        return self.state

    def reset(self) -> None:
        self.state = np.zeros(self.size, dtype=float)

    def copy(self) -> "WorkingMemory":
        wm = WorkingMemory.__new__(WorkingMemory)
        wm.size = self.size
        wm.state = self.state.copy()
        wm.g_keep_w = self.g_keep_w.copy()
        wm.g_keep_b = float(self.g_keep_b)
        wm.g_write_w = self.g_write_w.copy()
        wm.g_write_b = float(self.g_write_b)
        wm.g_erase_w = self.g_erase_w.copy()
        wm.g_erase_b = float(self.g_erase_b)
        wm.w_write = self.w_write.copy()
        wm.decay = float(self.decay)
        return wm


class HypothesisBank:
    __slots__ = ("K", "w_gen", "b_gen", "w_decode", "b_decode", "lateral_w",
                 "scores", "selected_idx", "anti_hebb_strength")

    def __init__(self, K: int, state_size: int, output_size: int, rng: np.random.Generator) -> None:
        scale = 1.0 / max(1.0, np.sqrt(float(state_size)))
        self.K = K
        self.w_gen = rng.normal(0.0, scale, size=(K, state_size))
        self.b_gen = rng.normal(0.0, 0.05, size=K)
        self.w_decode = rng.normal(0.0, 0.25, size=(output_size, K))
        self.b_decode = rng.normal(0.0, 0.05, size=output_size)
        self.lateral_w = np.zeros((K, K), dtype=float)
        np.fill_diagonal(self.lateral_w, 0.0)
        self.scores = np.zeros(K, dtype=float)
        self.selected_idx = 0
        self.anti_hebb_strength = 0.01

    def generate(self, state: np.ndarray, memory: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        combined = np.concatenate([state, memory]) if memory.size > 0 else state
        if combined.size != self.w_gen.shape[1]:
            padded = np.zeros(self.w_gen.shape[1], dtype=float)
            padded[: min(combined.size, self.w_gen.shape[1])] = combined[: self.w_gen.shape[1]]
            combined = padded
        raw = self.w_gen @ combined + self.b_gen
        activations = np.tanh(raw)
        activations = activations - self.anti_hebb_strength * (self.lateral_w @ activations)
        self.scores = activations
        decoded = self.w_decode @ activations + self.b_decode
        return activations, decoded

    def select_lateral_inhibition(self, beta: float = 0.5) -> int:
        z = self.scores.copy()
        for _ in range(5):
            inhibition = self.lateral_w @ z
            z = np.tanh(self.scores - beta * inhibition)
        self.selected_idx = int(np.argmax(z))
        return self.selected_idx

    def update_lateral_weights(self, learning_rate: float = 0.001) -> None:
        for i in range(self.K):
            for j in range(self.K):
                if i != j:
                    self.lateral_w[i, j] += learning_rate * self.scores[i] * self.scores[j]
        np.fill_diagonal(self.lateral_w, 0.0)
        self.lateral_w = np.clip(self.lateral_w, -1.0, 1.0)

    def copy(self) -> "HypothesisBank":
        hb = HypothesisBank.__new__(HypothesisBank)
        hb.K = self.K
        hb.w_gen = self.w_gen.copy()
        hb.b_gen = self.b_gen.copy()
        hb.w_decode = self.w_decode.copy()
        hb.b_decode = self.b_decode.copy()
        hb.lateral_w = self.lateral_w.copy()
        hb.scores = self.scores.copy()
        hb.selected_idx = self.selected_idx
        hb.anti_hebb_strength = float(self.anti_hebb_strength)
        return hb


class Predictor:
    __slots__ = ("w_state", "w_memory", "w_action", "b", "D", "w_proj", "b_proj")

    def __init__(self, state_size: int, memory_size: int, action_size: int, rng: np.random.Generator) -> None:
        scale = 1.0 / max(1.0, np.sqrt(float(state_size + memory_size)))
        self.w_state = rng.normal(0.0, scale, size=(state_size, state_size))
        self.w_memory = rng.normal(0.0, scale, size=(state_size, memory_size))
        self.w_action = rng.normal(0.0, scale, size=(state_size, action_size))
        self.b = rng.normal(0.0, 0.05, size=state_size)
        self.D = 3
        self.w_proj = rng.normal(0.0, 0.1, size=(state_size, state_size))
        self.b_proj = rng.normal(0.0, 0.05, size=state_size)

    def predict(self, state: np.ndarray, memory: np.ndarray, action: np.ndarray) -> np.ndarray:
        s = state.copy()
        for _ in range(self.D):
            prev_s = s.copy()
            s = np.tanh(self.w_state @ s + self.w_memory @ memory + self.w_action @ action + self.b)
            if np.allclose(s, prev_s, atol=1e-6):
                break
        return np.tanh(self.w_proj @ s + self.b_proj)

    def predict_multistep(self, state: np.ndarray, memory: np.ndarray, action: np.ndarray, steps: int = 3) -> list[np.ndarray]:
        predictions = []
        s = state.copy()
        for _ in range(steps):
            prev_s = s.copy()
            s = np.tanh(self.w_state @ s + self.w_memory @ memory + self.w_action @ action + self.b)
            predictions.append(np.tanh(self.w_proj @ s + self.b_proj))
            if np.allclose(s, prev_s, atol=1e-6):
                break
        return predictions

    def copy(self) -> "Predictor":
        pred = Predictor.__new__(Predictor)
        pred.w_state = self.w_state.copy()
        pred.w_memory = self.w_memory.copy()
        pred.w_action = self.w_action.copy()
        pred.b = self.b.copy()
        pred.D = self.D
        pred.w_proj = self.w_proj.copy()
        pred.b_proj = self.b_proj.copy()
        return pred


class Critic:
    __slots__ = ("w_state", "w_goal", "b", "w_score", "b_score", "alpha_risk", "gamma_cost", "delta_info")

    def __init__(self, state_size: int, goal_size: int, rng: np.random.Generator) -> None:
        scale = 1.0 / max(1.0, np.sqrt(float(state_size)))
        self.w_state = rng.normal(0.0, scale, size=(state_size, state_size))
        self.w_goal = rng.normal(0.0, scale, size=(state_size, goal_size))
        self.b = rng.normal(0.0, 0.05, size=state_size)
        self.w_score = rng.normal(0.0, 0.1, size=state_size)
        self.b_score = 0.0
        self.alpha_risk = 0.1
        self.gamma_cost = 0.05
        self.delta_info = 0.2

    def evaluate(self, predicted_state: np.ndarray, goal: np.ndarray, risk: float = 0.0, cost: float = 0.0, info_gain: float = 0.0) -> float:
        goal_padded = np.zeros(self.w_goal.shape[1], dtype=float)
        goal_padded[: min(goal.size, goal_padded.size)] = goal[: goal_padded.size]
        h = np.tanh(self.w_state @ predicted_state + self.w_goal @ goal_padded + self.b)
        raw_score = float(self.w_score @ h + self.b_score)
        return raw_score - self.alpha_risk * risk - self.gamma_cost * cost + self.delta_info * info_gain

    def copy(self) -> "Critic":
        cr = Critic.__new__(Critic)
        cr.w_state = self.w_state.copy()
        cr.w_goal = self.w_goal.copy()
        cr.b = self.b.copy()
        cr.w_score = self.w_score.copy()
        cr.b_score = float(self.b_score)
        cr.alpha_risk = float(self.alpha_risk)
        cr.gamma_cost = float(self.gamma_cost)
        cr.delta_info = float(self.delta_info)
        return cr


class Selector:
    __slots__ = ("K", "lateral_w", "rho", "beta", "prev_z")

    def __init__(self, K: int, rho: float = 0.5, beta: float = 0.3) -> None:
        self.K = K
        self.lateral_w = np.zeros((K, K), dtype=float)
        self.rho = rho
        self.beta = beta
        self.prev_z = np.zeros(K, dtype=float)

    def select(self, scores: np.ndarray) -> tuple[int, np.ndarray]:
        z = scores.copy()
        for _ in range(10):
            inhibition = self.lateral_w @ z
            z = np.tanh(scores - self.beta * inhibition + self.rho * self.prev_z)
        self.prev_z = z.copy()
        selected = int(np.argmax(z))
        return selected, z

    def update_lateral(self, activations: np.ndarray, lr: float = 0.005) -> None:
        for i in range(self.K):
            for j in range(self.K):
                if i != j:
                    self.lateral_w[i, j] += lr * activations[i] * activations[j]
        np.fill_diagonal(self.lateral_w, 0.0)
        self.lateral_w = np.clip(self.lateral_w, -0.5, 0.5)

    def copy(self) -> "Selector":
        sel = Selector.__new__(Selector)
        sel.K = self.K
        sel.lateral_w = self.lateral_w.copy()
        sel.rho = float(self.rho)
        sel.beta = float(self.beta)
        sel.prev_z = self.prev_z.copy()
        return sel


# ── M₁ Module ────────────────────────────────────────────────────────────────




@dataclass(frozen=True)
class DirectRnnForwardTrace:
    """Immutable forward cache for one Direct-RNN decision.

    The cache deliberately holds the exact pre/dropout/normalization path used
    at entry.  A lifecycle settles much later, after recurrent runtime state
    has moved on, so re-running the current module would create an invalid
    gradient for the original trade.
    """

    masked_observation: np.ndarray
    previous_hidden: np.ndarray
    effective_w_in: np.ndarray
    base_raw_preactivation: np.ndarray
    base_normalized_preactivation: np.ndarray
    base_candidate: np.ndarray
    base_hidden: np.ndarray
    deep_inputs: tuple[np.ndarray, ...]
    deep_previous_states: tuple[np.ndarray, ...]
    deep_raw_preactivations: tuple[np.ndarray, ...]
    deep_normalized_preactivations: tuple[np.ndarray, ...]
    deep_candidates: tuple[np.ndarray, ...]
    deep_hidden: tuple[np.ndarray, ...]
    dropout_scales: tuple[np.ndarray, ...]
    output_hidden: np.ndarray
    output_mask: np.ndarray
    gate: float
    normalization_enabled: tuple[bool, ...]
    normalization_mode: str
    normalization_target_rms: float
    normalization_clip: float
    normalization_eps: float
    # Feature-attention caches.  Defaults keep old persisted traces readable;
    # newly-created traces always populate the exact vectors used by forward.
    attended_observation: np.ndarray | None = None
    base_attention_weights: np.ndarray | None = None
    deep_attention_inputs: tuple[np.ndarray, ...] = ()
    deep_attention_weights: tuple[np.ndarray, ...] = ()
    # V190 ordered Q/K/V history read. The cached tokens are immutable causal
    # observations, so a delayed lifecycle never reconstructs memory using a
    # later runtime buffer.
    state_alias_memory_forward: StateAliasingMemoryForward | None = None
    # Single-layer 4096-unit LSTM cache used by the OpenAI Five recurrent core.
    recurrent_core: str = "legacy_rnn"
    lstm_forward: OpenAIFiveLSTMForward | None = None


@dataclass(frozen=True)
class ModuleActionTrace:
    """Decision-time hidden state used for action-specific neuron attribution."""

    module_name: str
    gate: float
    hidden: np.ndarray
    raw_output: np.ndarray
    # Logit before policy-level memory gate bias. The effective ``gate`` is
    # still retained for output aggregation, while this value gives the
    # delayed backward path the exact differentiable gate surface.
    gate_logit: float | None = None
    forward_trace: DirectRnnForwardTrace | None = None
    value_prediction: float = 0.0
    temporal_forward_traces: tuple[DirectRnnForwardTrace, ...] = ()


@dataclass(frozen=True)
class StepTrace:
    trace_id: str
    timestamp: float
    raw_obs: np.ndarray
    encoded_state: np.ndarray
    memory_before: np.ndarray
    memory_after: np.ndarray
    selected_idx: int
    selected_action: np.ndarray
    candidate_actions: np.ndarray
    candidate_logits: np.ndarray
    candidate_scores: np.ndarray
    selected_action_log_prob: float
    predicted_next_state: np.ndarray
    critic_value: float
    confidence: float
    novelty: float
    conflict: float
    risk: float
    gate_values: tuple[float, ...]
    prediction_error: float
    td_delta: float
    action_details: dict[str, object] = field(default_factory=dict)
    positions_pipe: str = ""
    positions_pipe_after: str = ""
    # Populated by the MT5 bridge after it has observed whether the EA actually
    # accepted/executed the action.  Empty keeps direct simulator calls intact.
    execution_details: dict[str, object] = field(default_factory=dict)
    experience_starvation: dict[str, float] = field(default_factory=dict)
    account_context: dict[str, float] = field(default_factory=dict)
    account_context_after: dict[str, float] = field(default_factory=dict)
    # Captured at decision time.  Later lifecycle credit must never infer a
    # neuron's state from chuyen_gia runtime activation.
    module_action_traces: tuple[ModuleActionTrace, ...] = ()
    # Graph-M1 evidence is immutable attribution metadata.  IDs are preserved
    # across journal/replay but never used to mutate a baseline topology.
    active_neuron_ids: tuple[str, ...] = ()
    active_edge_ids: tuple[str, ...] = ()
    graph_edge_gates: dict[str, float] = field(default_factory=dict)
    graph_region_activity: dict[str, float] = field(default_factory=dict)
    # V18 keeps immutable activity evidence for *every* graph, not only the
    # primary M1 module.  Keys are telemetry graph IDs (for example
    # ``m1:m1_thinking`` and ``reasoning_graph``), while local IDs remain
    # unchanged inside each record for lifecycle credit.
    graph_traces: dict[str, dict[str, object]] = field(default_factory=dict)
    memory_match_quality: float = 0.0
    lifecycle_tags: tuple[str, ...] = ()
    module_need_reason: str = ""
    # Immutable decision context needed to keep temporal memory and bridge
    # credit aligned with the exact tick that selected the action.
    context_frame_id: str = ""
    context_schema_version: int = 0
    canonical_context_key: np.ndarray = field(default_factory=lambda: np.zeros(MEMORY_KEY_SIZE, dtype=float))
    allowed_action_mask: tuple[bool, ...] = ()
    goal_context: np.ndarray = field(default_factory=lambda: np.zeros(0, dtype=float))
    learning_drive_context: np.ndarray = field(default_factory=lambda: np.zeros(0, dtype=float))
    context_audit: dict[str, object] = field(default_factory=dict)
    # Dedicated TimingNet decision snapshot. Arrays are small (market/timing
    # features plus one hidden state) and are retained only for exact delayed
    # lifecycle credit; legacy traces leave this empty.
    timing_trace: dict[str, object] = field(default_factory=dict)
    # V186 compact decision-local result.  The causal 32x78 tensor remains in
    # ``timing_trace``; this payload contains only memberships/value telemetry.
    tensor_rule_trace: dict[str, object] = field(default_factory=dict)


@dataclass
class CuriosityNeuronSystem:
    input_size: int = 64
    hidden_size: int = 32
    output_size: int = 32
    w_in: np.ndarray = field(default=None, repr=False)
    w_rec: np.ndarray = field(default=None, repr=False)
    b_hidden: np.ndarray = field(default=None, repr=False)
    w_out: np.ndarray = field(default=None, repr=False)
    b_out: np.ndarray = field(default=None, repr=False)
    state: np.ndarray = field(default=None, repr=False)
    plasticity: float = 0.05
    trust: float = 0.1
    age: int = 0

    @classmethod
    def seed(
        cls,
        input_size: int = 64,
        hidden_size: int = 32,
        output_size: int = 32,
        rng: np.random.Generator | None = None,
    ) -> "CuriosityNeuronSystem":
        rng = rng or np.random.default_rng()
        scale = 1.0 / max(1.0, np.sqrt(float(input_size)))
        return cls(
            input_size=input_size,
            hidden_size=hidden_size,
            output_size=output_size,
            w_in=rng.normal(0.0, scale, size=(hidden_size, input_size)),
            w_rec=rng.normal(0.0, 0.03, size=(hidden_size, hidden_size)),
            b_hidden=np.zeros(hidden_size, dtype=float),
            w_out=rng.normal(0.0, 0.08, size=(output_size, hidden_size)),
            b_out=np.zeros(output_size, dtype=float),
            state=np.zeros(hidden_size, dtype=float),
        )

    def ensure_compatible(self) -> None:
        if self.w_in is None or self.w_rec is None or self.w_out is None:
            seeded = CuriosityNeuronSystem.seed(self.input_size, self.hidden_size, self.output_size)
            self.w_in = seeded.w_in
            self.w_rec = seeded.w_rec
            self.b_hidden = seeded.b_hidden
            self.w_out = seeded.w_out
            self.b_out = seeded.b_out
            self.state = seeded.state
        if self.state is None or self.state.size != self.hidden_size:
            self.state = np.zeros(self.hidden_size, dtype=float)
        if not hasattr(self, "plasticity"):
            self.plasticity = 0.05
        if not hasattr(self, "trust"):
            self.trust = 0.1
        if not hasattr(self, "age"):
            self.age = 0

    def copy(self) -> "CuriosityNeuronSystem":
        self.ensure_compatible()
        return CuriosityNeuronSystem(
            input_size=int(self.input_size),
            hidden_size=int(self.hidden_size),
            output_size=int(self.output_size),
            w_in=self.w_in.copy(),
            w_rec=self.w_rec.copy(),
            b_hidden=self.b_hidden.copy(),
            w_out=self.w_out.copy(),
            b_out=self.b_out.copy(),
            state=self.state.copy(),
            plasticity=float(self.plasticity),
            trust=float(self.trust),
            age=int(self.age),
        )

    @staticmethod
    def _resize(values: np.ndarray, size: int) -> np.ndarray:
        arr = np.asarray(values, dtype=float).reshape(-1)
        out = np.zeros(size, dtype=float)
        if arr.size:
            out[: min(size, arr.size)] = arr[:size]
        return out

    def context_from(
        self,
        *,
        state: np.ndarray,
        action: np.ndarray | None = None,
        memory_query: dict[str, object] | None = None,
        causal_signals: list[dict[str, object]] | None = None,
        starvation: dict[str, float] | None = None,
    ) -> np.ndarray:
        self.ensure_compatible()
        memory_query = memory_query or {}
        causal_signals = causal_signals or []
        starvation = starvation or {}
        context = np.zeros(self.input_size, dtype=float)
        cursor = 0
        for block in (
            self._resize(state, 24),
            self._resize(action if action is not None else np.zeros(0), 12),
            self._resize(np.asarray(memory_query.get("action_bias", []), dtype=float), 12),
            self._resize(np.asarray(memory_query.get("memory_context", []), dtype=float), 8),
            self._resize(np.asarray([
                starvation.get("no_trade_streak", 0.0),
                starvation.get("unfilled_streak", 0.0),
                starvation.get("cadence_deficit", 0.0),
                starvation.get("starvation", 0.0),
                starvation.get("intrinsic_reward", 0.0),
            ], dtype=float), 5),
        ):
            kept = min(block.size, self.input_size - cursor)
            if kept <= 0:
                break
            context[cursor:cursor + kept] = block[:kept]
            cursor += kept
        if cursor < self.input_size:
            severities = [float(item.get("severity", 0.0)) for item in causal_signals[:4]]
            utilities = [float(item.get("utility", 0.0)) for item in causal_signals[:4]]
            tags = [1.0 if item.get("tags") else 0.0 for item in causal_signals[:4]]
            tail = np.asarray(severities + utilities + tags, dtype=float)
            kept = min(tail.size, self.input_size - cursor)
            context[cursor:cursor + kept] = tail[:kept]
        return np.clip(context, -5.0, 5.0)

    def forward(self, context: np.ndarray) -> dict[str, np.ndarray | float]:
        self.ensure_compatible()
        x = self._resize(context, self.input_size)
        self.state = np.tanh(self.w_in @ x + self.w_rec @ self.state + self.b_hidden)
        raw = self.w_out @ self.state + self.b_out
        out = np.tanh(raw)
        return {
            "raw": raw,
            "proposal": out,
            "action_delta": out[:12].copy(),
            "gate_delta": out[12:20].copy(),
            "recurrent_delta": out[20:28].copy(),
            "growth_delta": out[28:32].copy(),
            "drive": float((out[28] + 1.0) * 0.5) if out.size > 28 else 0.0,
            "risk_dampen": float((out[29] + 1.0) * 0.5) if out.size > 29 else 0.0,
            "memory_write": float((out[30] + 1.0) * 0.5) if out.size > 30 else 0.0,
        }

    def observe(self, context: np.ndarray, proposal: np.ndarray, reward: float, td_delta: float, prediction_error: float) -> None:
        self.ensure_compatible()
        x = self._resize(context, self.input_size)
        y = self._resize(proposal, self.output_size)
        signal = float(np.tanh(float(reward) + float(td_delta) - 0.1 * float(prediction_error)))
        lr = float(np.clip(self.plasticity * (0.25 + abs(signal)), 0.0001, 0.02))
        self.w_out += lr * signal * np.outer(y, self.state)
        self.b_out += lr * signal * y
        self.w_in += 0.25 * lr * signal * np.outer(self.state, x)
        self.w_rec += 0.1 * lr * signal * np.outer(self.state, self.state)
        self.trust = float(np.clip(0.995 * self.trust + 0.005 * max(0.0, signal), 0.0, 2.0))
        self.plasticity = float(np.clip(0.995 * self.plasticity + 0.005 * abs(signal), 0.005, 0.5))
        self.age += 1

    def propose_adjustments(self, context: np.ndarray) -> dict[str, np.ndarray | float]:
        return self.forward(context)


DEVELOPMENT_ACTIONS = ("hold", "grow", "prune", "split", "merge", "consolidate")
DEVELOPMENT_ROLE_LIBRARY = (
    (
        ROLE_PREDICTOR_SPECIALIST,
        ("state_encoder", "working_memory"),
        ("critic",),
    ),
    (
        ROLE_MEMORY_SPECIALIST,
        ("state_encoder",),
        ("predictor", "selector"),
    ),
    (
        ROLE_CRITIC_SPECIALIST,
        ("predictor",),
        ("selector",),
    ),
    (
        ROLE_HYPOTHESIS_SPECIALIST,
        ("state_encoder", "working_memory"),
        ("selector",),
    ),
    (
        ROLE_FEATURE_SPECIALIST,
        (),
        ("state_encoder",),
    ),
    (
        ROLE_GENERAL_SPECIALIST,
        ("state_encoder",),
        ("selector",),
    ),
)


def _softmax(values: np.ndarray) -> np.ndarray:
    arr = np.asarray(values, dtype=float)
    arr = arr - float(np.max(arr)) if arr.size else arr
    exp = np.exp(np.clip(arr, -40.0, 40.0))
    total = float(np.sum(exp))
    if total <= 0.0:
        return np.ones_like(exp) / max(1, exp.size)
    return exp / total


@dataclass
class NeuralDevelopmentOutput:
    action: str
    action_probs: np.ndarray
    role: str
    role_probs: np.ndarray
    input_sources: tuple[str, ...]
    output_targets: tuple[str, ...]
    initial_gate_bias: float
    initial_plasticity: float
    edge_open_strength: float
    residual_scale: float
    raw: np.ndarray = field(repr=False)

    def as_spec(self) -> ModuleSpec:
        return ModuleSpec(
            role=self.role,
            input_sources=list(self.input_sources),
            output_targets=list(self.output_targets),
            initial_gate_bias=float(self.initial_gate_bias),
            initial_plasticity=float(self.initial_plasticity),
        )

    def summary(self) -> dict[str, object]:
        return {
            "action": self.action,
            "action_confidence": float(np.max(self.action_probs)) if self.action_probs.size else 0.0,
            "role": self.role,
            "role_confidence": float(np.max(self.role_probs)) if self.role_probs.size else 0.0,
            "initial_gate_bias": float(self.initial_gate_bias),
            "initial_plasticity": float(self.initial_plasticity),
            "edge_open_strength": float(self.edge_open_strength),
            "residual_scale": float(self.residual_scale),
        }


@dataclass
class NeuralDevelopmentController:
    input_size: int = 32
    hidden_size: int = 24
    output_size: int = 18
    w_in: np.ndarray = field(default=None, repr=False)
    w_rec: np.ndarray = field(default=None, repr=False)
    b_hidden: np.ndarray = field(default=None, repr=False)
    w_out: np.ndarray = field(default=None, repr=False)
    b_out: np.ndarray = field(default=None, repr=False)
    state: np.ndarray = field(default=None, repr=False)
    plasticity: float = 0.01
    age: int = 0

    @classmethod
    def seed(
        cls,
        input_size: int = 32,
        hidden_size: int = 24,
        output_size: int = 18,
        rng: np.random.Generator | None = None,
    ) -> "NeuralDevelopmentController":
        rng = rng or np.random.default_rng()
        scale = 1.0 / max(1.0, np.sqrt(float(input_size)))
        controller = cls(
            input_size=input_size,
            hidden_size=hidden_size,
            output_size=output_size,
            w_in=rng.normal(0.0, scale, size=(hidden_size, input_size)),
            w_rec=rng.normal(0.0, 0.03, size=(hidden_size, hidden_size)),
            b_hidden=np.zeros(hidden_size, dtype=float),
            w_out=rng.normal(0.0, 0.08, size=(output_size, hidden_size)),
            b_out=np.zeros(output_size, dtype=float),
            state=np.zeros(hidden_size, dtype=float),
        )
        controller.b_out[0] = 0.35
        controller.b_out[1] = 0.05
        return controller

    def ensure_compatible(self) -> None:
        if self.w_in is None or self.w_rec is None or self.w_out is None:
            seeded = NeuralDevelopmentController.seed(self.input_size, self.hidden_size, self.output_size)
            self.w_in = seeded.w_in
            self.w_rec = seeded.w_rec
            self.b_hidden = seeded.b_hidden
            self.w_out = seeded.w_out
            self.b_out = seeded.b_out
            self.state = seeded.state
        if self.state is None or self.state.size != self.hidden_size:
            self.state = np.zeros(self.hidden_size, dtype=float)
        if not hasattr(self, "plasticity"):
            self.plasticity = 0.01
        if not hasattr(self, "age"):
            self.age = 0

    def copy(self) -> "NeuralDevelopmentController":
        self.ensure_compatible()
        return NeuralDevelopmentController(
            input_size=int(self.input_size),
            hidden_size=int(self.hidden_size),
            output_size=int(self.output_size),
            w_in=self.w_in.copy(),
            w_rec=self.w_rec.copy(),
            b_hidden=self.b_hidden.copy(),
            w_out=self.w_out.copy(),
            b_out=self.b_out.copy(),
            state=self.state.copy(),
            plasticity=float(self.plasticity),
            age=int(self.age),
        )

    @staticmethod
    def _resize(values: np.ndarray, size: int) -> np.ndarray:
        arr = np.asarray(values, dtype=float).reshape(-1)
        out = np.zeros(size, dtype=float)
        out[: min(size, arr.size)] = arr[:size]
        return out

    def context_from(
        self,
        signal: GrowthSignal,
        modules: list["ModuleState"],
        memory_summary: dict[str, object] | None,
        reward_modulator: float,
    ) -> np.ndarray:
        memory_summary = memory_summary or {}
        scores = np.asarray([m.score for m in modules], dtype=float) if modules else np.zeros(1)
        utilities = np.asarray([m.utility for m in modules], dtype=float) if modules else np.zeros(1)
        gates = np.asarray([m.gate_ema for m in modules], dtype=float) if modules else np.zeros(1)
        plasticities = np.asarray([m.plasticity for m in modules], dtype=float) if modules else np.zeros(1)
        context = np.array([
            signal.error,
            signal.novelty,
            signal.conflict,
            signal.representation_need,
            signal.complexity,
            signal.score,
            np.tanh(float(reward_modulator)),
            len(modules) / 16.0,
            float(np.mean(scores)),
            float(np.std(scores)),
            float(np.mean(utilities)),
            float(np.min(utilities)),
            float(np.mean(gates)),
            float(np.mean(plasticities)),
            float(memory_summary.get("neurons", 0)) / 1000.0,
            float(memory_summary.get("clusters", 0)) / 256.0,
            float(memory_summary.get("strategies", 0)) / 96.0,
            float(memory_summary.get("meta_strategies", 0)) / 32.0,
            float(memory_summary.get("positive_neurons", 0)) / max(1.0, float(memory_summary.get("neurons", 1))),
            float(memory_summary.get("causal_nodes", 0)) / 1000.0,
        ], dtype=float)
        return np.clip(self._resize(context, self.input_size), -5.0, 5.0)

    def forward(self, context: np.ndarray) -> NeuralDevelopmentOutput:
        self.ensure_compatible()
        x = self._resize(context, self.input_size)
        self.state = np.tanh(self.w_in @ x + self.w_rec @ self.state + self.b_hidden)
        raw = self.w_out @ self.state + self.b_out
        action_probs = _softmax(raw[:len(DEVELOPMENT_ACTIONS)])
        role_start = len(DEVELOPMENT_ACTIONS)
        role_end = role_start + len(DEVELOPMENT_ROLE_LIBRARY)
        role_probs = _softmax(raw[role_start:role_end])
        action = DEVELOPMENT_ACTIONS[int(np.argmax(action_probs))]
        role_idx = int(np.argmax(role_probs))
        role, inputs, outputs = DEVELOPMENT_ROLE_LIBRARY[role_idx]
        gate_raw = raw[role_end] if raw.size > role_end else 0.0
        plasticity_raw = raw[role_end + 1] if raw.size > role_end + 1 else 0.0
        edge_raw = raw[role_end + 2] if raw.size > role_end + 2 else 0.0
        residual_raw = raw[role_end + 3] if raw.size > role_end + 3 else 0.0
        return NeuralDevelopmentOutput(
            action=action,
            action_probs=action_probs.copy(),
            role=role,
            role_probs=role_probs.copy(),
            input_sources=tuple(inputs),
            output_targets=tuple(outputs),
            initial_gate_bias=float(-2.5 + 2.0 / (1.0 + np.exp(-np.clip(gate_raw, -10.0, 10.0)))),
            initial_plasticity=float(0.5 + 2.0 / (1.0 + np.exp(-np.clip(plasticity_raw, -10.0, 10.0)))),
            edge_open_strength=float(2.0 / (1.0 + np.exp(-np.clip(edge_raw, -10.0, 10.0)))),
            residual_scale=float(0.02 / (1.0 + np.exp(-np.clip(residual_raw, -10.0, 10.0)))),
            raw=raw.copy(),
        )

    def observe(self, context: np.ndarray, output: NeuralDevelopmentOutput, structural_reward: float) -> None:
        self.ensure_compatible()
        signal = float(np.tanh(structural_reward))
        lr = float(np.clip(self.plasticity * (0.25 + abs(signal)), 0.00005, 0.01))
        action_target = -output.action_probs
        action_target[int(np.argmax(output.action_probs))] += 1.0
        role_target = -output.role_probs
        role_target[int(np.argmax(output.role_probs))] += 1.0
        grad = np.zeros(self.output_size, dtype=float)
        grad[:len(DEVELOPMENT_ACTIONS)] = signal * action_target
        role_start = len(DEVELOPMENT_ACTIONS)
        grad[role_start:role_start + len(DEVELOPMENT_ROLE_LIBRARY)] = signal * role_target
        self.w_out += lr * np.outer(grad, self.state)
        self.b_out += lr * grad
        self.w_in += 0.1 * lr * signal * np.outer(self.state, self._resize(context, self.input_size))
        self.w_rec += 0.05 * lr * signal * np.outer(self.state, self.state)
        self.plasticity = float(np.clip(0.995 * self.plasticity + 0.005 * abs(signal), 0.001, 0.2))
        self.age += 1


@dataclass
class NeuralScalarNetwork:
    input_size: int
    hidden_size: int
    output_size: int
    w_in: np.ndarray = field(default=None, repr=False)
    w_rec: np.ndarray = field(default=None, repr=False)
    b_hidden: np.ndarray = field(default=None, repr=False)
    w_out: np.ndarray = field(default=None, repr=False)
    b_out: np.ndarray = field(default=None, repr=False)
    state: np.ndarray = field(default=None, repr=False)
    plasticity: float = 0.01
    age: int = 0

    @classmethod
    def seed(
        cls,
        input_size: int,
        hidden_size: int,
        output_size: int,
        rng: np.random.Generator | None = None,
    ) -> "NeuralScalarNetwork":
        rng = rng or np.random.default_rng()
        scale = 1.0 / max(1.0, np.sqrt(float(input_size)))
        return cls(
            input_size=input_size,
            hidden_size=hidden_size,
            output_size=output_size,
            w_in=rng.normal(0.0, scale, size=(hidden_size, input_size)),
            w_rec=rng.normal(0.0, 0.03, size=(hidden_size, hidden_size)),
            b_hidden=np.zeros(hidden_size, dtype=float),
            w_out=rng.normal(0.0, 0.08, size=(output_size, hidden_size)),
            b_out=np.zeros(output_size, dtype=float),
            state=np.zeros(hidden_size, dtype=float),
        )

    def ensure_compatible(self) -> None:
        if self.w_in is None or self.w_rec is None or self.w_out is None:
            seeded = NeuralScalarNetwork.seed(self.input_size, self.hidden_size, self.output_size)
            self.w_in = seeded.w_in
            self.w_rec = seeded.w_rec
            self.b_hidden = seeded.b_hidden
            self.w_out = seeded.w_out
            self.b_out = seeded.b_out
            self.state = seeded.state
        if self.state is None or self.state.size != self.hidden_size:
            self.state = np.zeros(self.hidden_size, dtype=float)
        if not hasattr(self, "plasticity"):
            self.plasticity = 0.01
        if not hasattr(self, "age"):
            self.age = 0

    def copy(self) -> "NeuralScalarNetwork":
        self.ensure_compatible()
        kwargs = dict(
            input_size=int(self.input_size),
            hidden_size=int(self.hidden_size),
            output_size=int(self.output_size),
            w_in=self.w_in.copy(),
            w_rec=self.w_rec.copy(),
            b_hidden=self.b_hidden.copy(),
            w_out=self.w_out.copy(),
            b_out=self.b_out.copy(),
            state=self.state.copy(),
            plasticity=float(self.plasticity),
            age=int(self.age),
        )
        if hasattr(self, "labels"):
            kwargs["labels"] = tuple(getattr(self, "labels"))
        return self.__class__(**kwargs)

    def _resize(self, values: np.ndarray) -> np.ndarray:
        arr = np.asarray(values, dtype=float).reshape(-1)
        out = np.zeros(self.input_size, dtype=float)
        out[: min(arr.size, self.input_size)] = arr[:self.input_size]
        return np.clip(out, -8.0, 8.0)

    def forward(self, values: np.ndarray) -> np.ndarray:
        self.ensure_compatible()
        x = self._resize(values)
        self.state = np.tanh(self.w_in @ x + self.w_rec @ self.state + self.b_hidden)
        return self.w_out @ self.state + self.b_out

    def observe(self, values: np.ndarray, target: np.ndarray, strength: float = 1.0) -> None:
        self.ensure_compatible()
        x = self._resize(values)
        raw = self.forward(x)
        target_arr = np.asarray(target, dtype=float).reshape(-1)
        padded = np.zeros(self.output_size, dtype=float)
        padded[: min(target_arr.size, self.output_size)] = target_arr[:self.output_size]
        error = np.clip(padded - raw, -2.0, 2.0)
        lr = float(np.clip(self.plasticity * abs(float(strength)), 0.00005, 0.02))
        self.w_out += lr * np.outer(error, self.state)
        self.b_out += lr * error
        self.w_in += 0.05 * lr * np.outer(np.tanh(self.state), x)
        self.w_rec += 0.02 * lr * np.outer(self.state, self.state)
        self.plasticity = float(np.clip(0.995 * self.plasticity + 0.005 * float(np.mean(np.abs(error))), 0.001, 0.2))
        self.age += 1


@dataclass
class NeuralUtilityNetwork(NeuralScalarNetwork):
    @classmethod
    def seed(cls, rng: np.random.Generator | None = None) -> "NeuralUtilityNetwork":
        base = NeuralScalarNetwork.seed(24, 16, 2, rng)
        return cls(**base.__dict__)

    def evaluate_window(self, features: np.ndarray) -> tuple[float, float]:
        raw = self.forward(features)
        utility = float(np.tanh(raw[0]))
        trust = float(1.0 / (1.0 + np.exp(-np.clip(raw[1], -10.0, 10.0)))) if raw.size > 1 else 0.5
        return utility, trust


@dataclass
class NeuralRiskCostGate(NeuralScalarNetwork):
    @classmethod
    def seed(cls, rng: np.random.Generator | None = None) -> "NeuralRiskCostGate":
        base = NeuralScalarNetwork.seed(32, 16, 3, rng)
        gate = cls(**base.__dict__)
        gate.b_out[:] = np.array([0.0, 0.0, 0.0])
        return gate

    def gate(self, features: np.ndarray) -> dict[str, float]:
        raw = self.forward(features)
        risk = float(1.0 / (1.0 + np.exp(-np.clip(raw[0], -10.0, 10.0))))
        cost = float(1.0 / (1.0 + np.exp(-np.clip(raw[1], -10.0, 10.0))))
        patience = float(1.0 / (1.0 + np.exp(-np.clip(raw[2], -10.0, 10.0))))
        return {"risk": risk, "cost": cost, "patience": patience}


@dataclass
class NeuralActionParameterHead(NeuralScalarNetwork):
    @classmethod
    def seed(cls, rng: np.random.Generator | None = None) -> "NeuralActionParameterHead":
        base = NeuralScalarNetwork.seed(64, 24, 8, rng)
        head = cls(**base.__dict__)
        head.b_out[:] = 0.0
        return head

    def parameters(self, features: np.ndarray) -> np.ndarray:
        return np.tanh(self.forward(features))


@dataclass
class NeuralPositionOutcomeClassifier(NeuralScalarNetwork):
    labels: tuple[str, ...] = (
        "gave_back_profit",
        "near_tp_giveback",
        "near_tp_missed",
        "closed_after_near_tp_bad",
        "should_have_partial_or_trail",
    )

    @classmethod
    def seed(cls, rng: np.random.Generator | None = None) -> "NeuralPositionOutcomeClassifier":
        base = NeuralScalarNetwork.seed(16, 16, 5, rng)
        clf = cls(**base.__dict__)
        clf.w_out[:] = 0.0
        clf.b_out[:] = -2.0
        # Biological prior encoded as synaptic weights; it is trainable and can be overridden by experience.
        clf.w_in[:, :] *= 0.2
        return clf

    def features_from(
        self,
        target_position: dict[str, object],
        after_position: dict[str, object] | None,
        reward: float,
        td_delta: float,
        utility: float,
    ) -> np.ndarray:
        mfe_r = float(target_position.get("mfe_r", target_position.get("unrealized_r", 0.0)) or 0.0)
        unrealized = float(target_position.get("unrealized_r", 0.0) or 0.0)
        after_unrealized = float(after_position.get("unrealized_r", unrealized)) if after_position else unrealized
        giveback_r = float(target_position.get("giveback_r", max(0.0, mfe_r - unrealized)) or 0.0)
        if after_position is not None:
            giveback_r = max(giveback_r, mfe_r - after_unrealized)
        min_dist_tp = float(target_position.get("min_dist_tp_atr", 999.0) or 999.0)
        min_dist_sl = float(target_position.get("min_dist_sl_atr", 999.0) or 999.0)
        near_tp_flag = 1.0 if bool(target_position.get("near_tp", False)) else 0.0
        closed_after = 1.0 if after_position is None else 0.0
        return np.array([
            np.tanh(mfe_r),
            np.tanh(giveback_r),
            np.tanh(unrealized),
            np.tanh(after_unrealized),
            np.tanh(float(reward)),
            np.tanh(float(td_delta)),
            np.tanh(float(utility)),
            near_tp_flag,
            np.clip(1.0 / (1.0 + max(0.0, min_dist_tp)), 0.0, 1.0),
            np.clip(1.0 / (1.0 + max(0.0, min_dist_sl)), 0.0, 1.0),
            closed_after,
            np.tanh(float(target_position.get("age_bars", 0.0) or 0.0) / 100.0),
        ], dtype=float)

    def classify(self, features: np.ndarray) -> tuple[list[str], np.ndarray]:
        raw = self.forward(features)
        probs = 1.0 / (1.0 + np.exp(-np.clip(raw, -10.0, 10.0)))
        tags = [label for label, prob in zip(self.labels, probs) if float(prob) >= 0.55]
        return tags, probs


# ── ModuleState (Enhanced) ────────────────────────────────────────────────────


@dataclass
class ModuleState:
    name: str
    role: str
    input_size: int
    hidden_size: int
    output_size: int
    w_in: np.ndarray
    w_rec: np.ndarray
    b_hidden: np.ndarray
    w_out: np.ndarray
    b_out: np.ndarray
    gate_w: np.ndarray
    # Candidate-only critic head. It does not affect live action selection;
    # it supplies the value-loss term when a verified lifecycle settles.
    value_w: np.ndarray
    value_b: float = 0.0
    # Published OpenAI Five recurrent core: one standard 4096-unit LSTM.
    recurrent_core: str = "legacy_rnn"
    lstm_w_in: np.ndarray | None = field(default=None, repr=False)
    lstm_w_rec: np.ndarray | None = field(default=None, repr=False)
    lstm_b: np.ndarray | None = field(default=None, repr=False)
    lstm_cell: np.ndarray | None = field(default=None, repr=False)
    # Training-only quality probes indexed by immutable (context, action,
    # side). They read the final hidden representation but never participate
    # in inference, routing, risk or a runtime gate.
    conditioned_quality_w: np.ndarray | None = field(default=None, repr=False)
    conditioned_quality_b: np.ndarray | None = field(default=None, repr=False)
    w_lat: np.ndarray = field(default=None, repr=False)
    deep_w: tuple[np.ndarray, ...] = field(default_factory=tuple, repr=False)
    deep_rec: tuple[np.ndarray, ...] = field(default_factory=tuple, repr=False)
    deep_b: tuple[np.ndarray, ...] = field(default_factory=tuple, repr=False)
    deep_state: tuple[np.ndarray, ...] = field(default_factory=tuple, repr=False)
    # Routing masks are persisted with a specialist module.  They make the
    # neural-development input/output specification operational rather than
    # metadata-only.
    input_mask: np.ndarray = field(default=None, repr=False)
    output_mask: np.ndarray = field(default=None, repr=False)
    neuron_utility: np.ndarray = field(default=None, repr=False)
    neuron_advantage_ema: np.ndarray = field(default=None, repr=False)
    neuron_contribution_ema: np.ndarray = field(default=None, repr=False)
    neuron_activation_ema: np.ndarray = field(default=None, repr=False)
    neuron_redundancy_ema: np.ndarray = field(default=None, repr=False)
    neuron_samples: np.ndarray = field(default=None, repr=False)
    neuron_frozen: np.ndarray = field(default=None, repr=False)
    input_eligibility: np.ndarray = field(default=None, repr=False)
    credit_ema: float = 0.0
    gate_b: float = 0.0
    plasticity: float = 1.0
    # Candidate-only optimizer for the direct recurrent decision path.  The
    # protected v13 checkpoint keeps this disabled and frozen; a trainable
    # candidate explicitly enables this single writer.
    rnn_optimizer_enabled: bool = False
    rnn_optimizer_learning_rate: float = 0.0005
    rnn_optimizer_weight_decay: float = 1.0e-4
    rnn_optimizer_beta1: float = 0.90
    rnn_optimizer_beta2: float = 0.999
    rnn_optimizer_epsilon: float = 1.0e-8
    rnn_optimizer_gradient_clip: float = 1.0
    rnn_optimizer_cosine_min_factor: float = 0.20
    rnn_optimizer_cosine_cycle_steps: int = 256
    rnn_optimizer_step: int = 0
    rnn_optimizer_m: dict[str, np.ndarray] = field(default_factory=dict, repr=False)
    rnn_optimizer_v: dict[str, np.ndarray] = field(default_factory=dict, repr=False)
    rnn_optimizer_last_stats: dict[str, object] = field(default_factory=dict, repr=False)
    # When enabled, only the unified lifecycle RL batch may write Direct-RNN
    # weights. Older local plasticity/fitness/rejection writers remain for
    # legacy candidates but are explicitly gated off for this contract.
    rnn_full_rl_enabled: bool = False
    rnn_temporal_bptt_steps: int = 8
    rl_temporal_forward_history: list[DirectRnnForwardTrace] = field(default_factory=list, repr=False)
    last_forward_trace: DirectRnnForwardTrace | None = field(default=None, repr=False)
    age: int = 0
    score: float = 0.0
    utility: float = 0.0
    gate_ema: float = 0.0
    activation_ema: float = 0.0
    lifecycle: str = MODULE_LIFECYCLE_DORMANT
    memory_decay: float = 0.85

    p_stp: np.ndarray = field(default=None, repr=False)
    stp_rho: float = 0.95
    stp_alpha: float = 0.1
    # Bound the observation drive of STP before it multiplies w_in.  The
    # default 50 is equivalent to the legacy path because p_stp is capped at
    # 5; candidate runs can lower this without changing the feature contract.
    stp_input_clip: float = 50.0
    # All hidden blocks normalize their preactivation before tanh.
    hidden_normalization_mode: str = REQUIRED_HIDDEN_NORMALIZATION_MODE
    hidden_normalization_target_rms: float = 1.0
    hidden_normalization_clip: float = 3.0
    hidden_normalization_eps: float = 1e-5
    hidden_normalization_enabled: bool = True
    hidden_normalization_layers: tuple[bool, ...] = field(default_factory=tuple)
    # Dropout slots are resolved to the configured recurrent hidden depth.
    # They are applied only on a training forward pass and never mutate the
    # persisted recurrent state.
    hidden_dropout_enabled: bool = True
    hidden_dropout_rates: tuple[float, ...] = REQUIRED_HIDDEN_DROPOUT_RATES
    hidden_dropout_seed: int = 0
    hidden_dropout_train_only: bool = True
    hidden_dropout_step: int = field(default=0, repr=False)
    # Hidden state used by the output head after normalization/dropout.  The
    # recurrent state returned by ``activate`` deliberately stays unmasked;
    # learning credit must nevertheless use this exact forward-path vector.
    last_output_hidden: np.ndarray | None = field(default=None, repr=False)
    # Long-term plasticity has its own bounded correlation contract.  ``raw``
    # is retained only for migrated legacy artifacts; normalized candidates
    # should use ``soft_clip_v1``.
    plasticity_input_normalization_mode: str = "soft_clip_v1"
    plasticity_update_clip: float = 0.25
    plasticity_weight_norm_cap: float = 0.0
    plasticity_update_count: int = 0
    plasticity_update_ema: float = 0.0
    plasticity_update_var: float = 0.0
    plasticity_last_stats: dict[str, float] = field(default_factory=dict, repr=False)

    stdp_params: STDPParams = field(default=None, repr=False)
    plasticity_coeffs: PlasticityCoefficients = field(default=None, repr=False)
    last_spike_time: float = 0.0
    spike_history: list = field(default_factory=list, repr=False)

    m1_component: M1GraphModule | None = field(default=None, repr=False)
    # A learnable feature-attention gate precedes every recurrent hidden
    # block.  Zero scores are an exact neutral initialization because the
    # scaled softmax returns one for every channel.
    attention_enabled: bool = True
    input_attention_q: np.ndarray | None = field(default=None, repr=False)
    input_attention_b: np.ndarray | None = field(default=None, repr=False)
    deep_attention_q: tuple[np.ndarray, ...] = field(default_factory=tuple, repr=False)
    deep_attention_b: tuple[np.ndarray, ...] = field(default_factory=tuple, repr=False)
    # Training-only multi-task heads. Neither head is read by inference.
    auxiliary_w: np.ndarray | None = field(default=None, repr=False)
    auxiliary_b: np.ndarray | None = field(default=None, repr=False)
    auxiliary_reconstruction_w: np.ndarray | None = field(default=None, repr=False)
    auxiliary_reconstruction_b: np.ndarray | None = field(default=None, repr=False)
    # V186: one independent bank belongs to the canonical module of one
    # context expert.  Legacy artifacts leave this None and remain identical.
    tensor_rule_bank: TensorRuleBankState | None = field(default=None, repr=False)
    # V190: per-expert working memory that differentiates equal-looking current
    # snapshots by the ordered path that preceded them.
    state_alias_memory: StateAliasingMemoryState | None = field(default=None, repr=False)

    @classmethod
    def create(
        cls,
        name: str,
        input_size: int,
        hidden_size: int,
        output_size: int,
        rng: np.random.Generator,
        role: str = "specialist",
        hidden_layers: int = 1,
        recurrent_core: str = "legacy_rnn",
    ) -> "ModuleState":
        recurrent_core = str(recurrent_core or "legacy_rnn").strip().lower()
        five_core = recurrent_core == OPENAI_FIVE_RECURRENT_CORE
        layer_count = max(1, int(hidden_layers))
        if five_core and layer_count != 1:
            raise ValueError("OpenAI Five recurrent core requires exactly one LSTM layer")
        scale = 1.0 / max(1.0, np.sqrt(float(input_size)))
        if five_core:
            lstm_w_in, lstm_w_rec, lstm_b = initialize_lstm(input_size, hidden_size, rng)
            # Legacy recurrent matrices are intentionally empty: the Five path
            # has one LSTM only and must not carry a second recurrent writer.
            w_in = np.zeros((0, 0), dtype=np.float32)
            w_rec = np.zeros((0, 0), dtype=np.float32)
            deep_w = ()
            deep_rec = ()
            deep_b = ()
        else:
            lstm_w_in = lstm_w_rec = lstm_b = None
            w_in = rng.normal(0.0, scale, size=(hidden_size, input_size))
            w_rec = rng.normal(0.0, 0.05, size=(hidden_size, hidden_size))
            deep_scale = 1.0 / max(1.0, np.sqrt(float(hidden_size)))
            deep_w = tuple(
                rng.normal(0.0, deep_scale, size=(hidden_size, hidden_size))
                for _ in range(layer_count - 1)
            )
            deep_rec = tuple(
                rng.normal(0.0, 0.035, size=(hidden_size, hidden_size))
                for _ in range(layer_count - 1)
            )
            deep_b = tuple(
                rng.normal(0.0, 0.04, size=hidden_size)
                for _ in range(layer_count - 1)
            )
        return cls(
            name=name,
            role=role,
            input_size=input_size,
            hidden_size=hidden_size,
            output_size=output_size,
            w_in=w_in,
            w_rec=w_rec,
            w_lat=(None if five_core else rng.normal(0.0, 0.02, size=(hidden_size, hidden_size))),
            deep_w=deep_w,
            deep_rec=deep_rec,
            deep_b=deep_b,
            deep_state=tuple(np.zeros(hidden_size, dtype=float) for _ in range(layer_count - 1)),
            hidden_normalization_mode=("none" if five_core else REQUIRED_HIDDEN_NORMALIZATION_MODE),
            hidden_normalization_enabled=not five_core,
            hidden_normalization_layers=(() if five_core else tuple(True for _ in range(layer_count))),
            hidden_dropout_enabled=not five_core,
            hidden_dropout_rates=(() if five_core else layerwise_rates(REQUIRED_HIDDEN_DROPOUT_RATES, layer_count)),
            hidden_dropout_seed=int(rng.integers(0, 2**31 - 1)),
            input_mask=np.ones(input_size, dtype=float),
            output_mask=np.ones(output_size, dtype=float),
            neuron_utility=np.zeros(hidden_size, dtype=float),
            neuron_advantage_ema=np.zeros(hidden_size, dtype=float),
            neuron_contribution_ema=np.zeros(hidden_size, dtype=float),
            neuron_activation_ema=np.zeros(hidden_size, dtype=float),
            neuron_redundancy_ema=np.zeros(hidden_size, dtype=float),
            neuron_samples=np.zeros(hidden_size, dtype=float),
            neuron_frozen=np.zeros(hidden_size, dtype=bool),
            input_eligibility=np.zeros((hidden_size, input_size), dtype=float),
            b_hidden=(np.zeros(0, dtype=np.float32) if five_core else rng.normal(0.0, 0.05, size=hidden_size)),
            w_out=rng.normal(0.0, 0.25, size=(output_size, hidden_size)).astype(np.float32 if five_core else float),
            b_out=rng.normal(0.0, 0.05, size=output_size).astype(np.float32 if five_core else float),
            gate_w=(np.zeros(0, dtype=np.float32) if five_core else rng.normal(0.0, scale, size=input_size)),
            value_w=rng.normal(0.0, 0.05, size=hidden_size).astype(np.float32 if five_core else float),
            value_b=0.0,
            recurrent_core=recurrent_core,
            lstm_w_in=lstm_w_in,
            lstm_w_rec=lstm_w_rec,
            lstm_b=lstm_b,
            lstm_cell=np.zeros(hidden_size, dtype=np.float32) if five_core else None,
            conditioned_quality_w=(None if five_core else rng.normal(
                0.0, 0.02, size=(CONDITIONED_REPRESENTATION_HEAD_COUNT, hidden_size)
            )),
            conditioned_quality_b=(None if five_core else np.zeros(CONDITIONED_REPRESENTATION_HEAD_COUNT, dtype=float)),
            p_stp=(None if five_core else np.ones((hidden_size, input_size), dtype=float)),
            plasticity_weight_norm_cap=max(1.0, float(np.sqrt(hidden_size) * 1.5)),
            stdp_params=STDPParams(),
            plasticity_coeffs=PlasticityCoefficients(),
            attention_enabled=not five_core,
            input_attention_q=(None if five_core else np.zeros(input_size, dtype=float)),
            input_attention_b=(None if five_core else np.zeros(input_size, dtype=float)),
            deep_attention_q=(() if five_core else tuple(np.zeros(hidden_size, dtype=float) for _ in range(layer_count - 1))),
            deep_attention_b=(() if five_core else tuple(np.zeros(hidden_size, dtype=float) for _ in range(layer_count - 1))),
            auxiliary_w=(None if five_core else rng.normal(0.0, 0.02, size=(AUXILIARY_OUTPUT_COUNT, hidden_size))),
            auxiliary_b=(None if five_core else np.zeros(AUXILIARY_OUTPUT_COUNT, dtype=float)),
            auxiliary_reconstruction_w=(None if five_core else rng.normal(0.0, 0.01, size=(input_size, hidden_size))),
            auxiliary_reconstruction_b=(None if five_core else np.zeros(input_size, dtype=float)),
            tensor_rule_bank=None,
            state_alias_memory=None,
        )

    def copy(self) -> "ModuleState":
        return ModuleState(
            name=self.name,
            role=self.role,
            input_size=self.input_size,
            hidden_size=self.hidden_size,
            output_size=self.output_size,
            w_in=self.w_in.copy(),
            w_rec=self.w_rec.copy(),
            w_lat=self.w_lat.copy() if self.w_lat is not None else None,
            deep_w=tuple(layer.copy() for layer in getattr(self, "deep_w", ()) or ()),
            deep_rec=tuple(layer.copy() for layer in getattr(self, "deep_rec", ()) or ()),
            deep_b=tuple(layer.copy() for layer in getattr(self, "deep_b", ()) or ()),
            deep_state=tuple(layer.copy() for layer in getattr(self, "deep_state", ()) or ()),
            input_mask=self.input_mask.copy() if self.input_mask is not None else None,
            output_mask=self.output_mask.copy() if self.output_mask is not None else None,
            neuron_utility=self.neuron_utility.copy() if self.neuron_utility is not None else None,
            neuron_advantage_ema=self.neuron_advantage_ema.copy() if self.neuron_advantage_ema is not None else None,
            neuron_contribution_ema=self.neuron_contribution_ema.copy() if self.neuron_contribution_ema is not None else None,
            neuron_activation_ema=self.neuron_activation_ema.copy() if self.neuron_activation_ema is not None else None,
            neuron_redundancy_ema=self.neuron_redundancy_ema.copy() if self.neuron_redundancy_ema is not None else None,
            neuron_samples=self.neuron_samples.copy() if self.neuron_samples is not None else None,
            neuron_frozen=self.neuron_frozen.copy() if self.neuron_frozen is not None else None,
            input_eligibility=self.input_eligibility.copy() if self.input_eligibility is not None else None,
            credit_ema=float(self.credit_ema),
            b_hidden=self.b_hidden.copy(),
            w_out=self.w_out.copy(),
            b_out=self.b_out.copy(),
            gate_w=self.gate_w.copy(),
            value_w=self.value_w.copy(),
            value_b=float(self.value_b),
            recurrent_core=str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn"),
            lstm_w_in=(np.asarray(self.lstm_w_in, dtype=np.float32).copy() if getattr(self, "lstm_w_in", None) is not None else None),
            lstm_w_rec=(np.asarray(self.lstm_w_rec, dtype=np.float32).copy() if getattr(self, "lstm_w_rec", None) is not None else None),
            lstm_b=(np.asarray(self.lstm_b, dtype=np.float32).copy() if getattr(self, "lstm_b", None) is not None else None),
            lstm_cell=(np.asarray(self.lstm_cell, dtype=np.float32).copy() if getattr(self, "lstm_cell", None) is not None else None),
            conditioned_quality_w=(
                np.asarray(getattr(self, "conditioned_quality_w", None), dtype=float).copy()
                if getattr(self, "conditioned_quality_w", None) is not None else None
            ),
            conditioned_quality_b=(
                np.asarray(getattr(self, "conditioned_quality_b", None), dtype=float).copy()
                if getattr(self, "conditioned_quality_b", None) is not None else None
            ),
            gate_b=float(self.gate_b),
            plasticity=float(self.plasticity),
            rnn_optimizer_enabled=bool(getattr(self, "rnn_optimizer_enabled", False)),
            rnn_optimizer_learning_rate=float(getattr(self, "rnn_optimizer_learning_rate", 0.0005) or 0.0005),
            rnn_optimizer_weight_decay=float(getattr(self, "rnn_optimizer_weight_decay", 1.0e-4) or 0.0),
            rnn_optimizer_beta1=float(getattr(self, "rnn_optimizer_beta1", 0.90) or 0.90),
            rnn_optimizer_beta2=float(getattr(self, "rnn_optimizer_beta2", 0.999) or 0.999),
            rnn_optimizer_epsilon=float(getattr(self, "rnn_optimizer_epsilon", 1.0e-8) or 1.0e-8),
            rnn_optimizer_gradient_clip=float(getattr(self, "rnn_optimizer_gradient_clip", 1.0) or 1.0),
            rnn_optimizer_cosine_min_factor=float(getattr(self, "rnn_optimizer_cosine_min_factor", 0.20) or 0.20),
            rnn_optimizer_cosine_cycle_steps=max(1, int(getattr(self, "rnn_optimizer_cosine_cycle_steps", 256) or 256)),
            rnn_optimizer_step=max(0, int(getattr(self, "rnn_optimizer_step", 0) or 0)),
            rnn_optimizer_m={key: np.asarray(value, dtype=float).copy() for key, value in dict(getattr(self, "rnn_optimizer_m", {}) or {}).items()},
            rnn_optimizer_v={key: np.asarray(value, dtype=float).copy() for key, value in dict(getattr(self, "rnn_optimizer_v", {}) or {}).items()},
            rnn_optimizer_last_stats=copylib.deepcopy(
                dict(getattr(self, "rnn_optimizer_last_stats", {}) or {})
            ),
            rnn_full_rl_enabled=bool(getattr(self, "rnn_full_rl_enabled", False)),
            rnn_temporal_bptt_steps=max(1, int(getattr(self, "rnn_temporal_bptt_steps", 8) or 8)),
            rl_temporal_forward_history=[
                item for item in list(getattr(self, "rl_temporal_forward_history", []) or [])
                if isinstance(item, DirectRnnForwardTrace)
            ][-max(1, int(getattr(self, "rnn_temporal_bptt_steps", 8) or 8)):],
            age=int(self.age),
            score=float(self.score),
            utility=float(self.utility),
            gate_ema=float(self.gate_ema),
            activation_ema=float(self.activation_ema),
            lifecycle=self.lifecycle,
            memory_decay=float(self.memory_decay),
            p_stp=self.p_stp.copy() if self.p_stp is not None else None,
            stp_rho=float(self.stp_rho),
            stp_alpha=float(self.stp_alpha),
            stp_input_clip=float(getattr(self, "stp_input_clip", 50.0) or 50.0),
            hidden_normalization_mode=(
                "none" if str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE
                else _mandatory_hidden_normalization_mode(
                    getattr(self, "hidden_normalization_mode", REQUIRED_HIDDEN_NORMALIZATION_MODE)
                )
            ),
            hidden_normalization_target_rms=float(getattr(self, "hidden_normalization_target_rms", 1.0) or 1.0),
            hidden_normalization_clip=float(getattr(self, "hidden_normalization_clip", 3.0) or 3.0),
            hidden_normalization_eps=float(getattr(self, "hidden_normalization_eps", 1e-5) or 1e-5),
            hidden_normalization_enabled=(str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() != OPENAI_FIVE_RECURRENT_CORE),
            hidden_normalization_layers=(
                () if str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE
                else tuple(True for _ in range(1 + len(getattr(self, "deep_w", ()) or ())))
            ),
            hidden_dropout_enabled=(str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() != OPENAI_FIVE_RECURRENT_CORE),
            hidden_dropout_rates=(
                () if str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE
                else mandatory_layerwise_rates(
                    getattr(self, "hidden_dropout_rates", REQUIRED_HIDDEN_DROPOUT_RATES),
                    1 + len(getattr(self, "deep_w", ()) or ()),
                )
            ),
            hidden_dropout_seed=max(0, int(getattr(self, "hidden_dropout_seed", 0) or 0)),
            hidden_dropout_train_only=bool(getattr(self, "hidden_dropout_train_only", True)),
            hidden_dropout_step=max(0, int(getattr(self, "hidden_dropout_step", 0) or 0)),
            last_output_hidden=(
                np.asarray(getattr(self, "last_output_hidden", None), dtype=float).copy()
                if getattr(self, "last_output_hidden", None) is not None else None
            ),
            plasticity_input_normalization_mode=str(getattr(self, "plasticity_input_normalization_mode", "soft_clip_v1") or "soft_clip_v1"),
            plasticity_update_clip=float(getattr(self, "plasticity_update_clip", 0.25) or 0.25),
            plasticity_weight_norm_cap=float(getattr(self, "plasticity_weight_norm_cap", 0.0) or 0.0),
            plasticity_update_count=int(getattr(self, "plasticity_update_count", 0) or 0),
            plasticity_update_ema=float(getattr(self, "plasticity_update_ema", 0.0) or 0.0),
            plasticity_update_var=float(getattr(self, "plasticity_update_var", 0.0) or 0.0),
            plasticity_last_stats=dict(getattr(self, "plasticity_last_stats", {}) or {}),
            stdp_params=self.stdp_params,
            plasticity_coeffs=self.plasticity_coeffs,
            last_spike_time=float(self.last_spike_time),
            spike_history=list(self.spike_history),
            m1_component=self.m1_component.copy() if self.m1_component is not None else None,
            attention_enabled=bool(getattr(self, "attention_enabled", True)),
            input_attention_q=(np.asarray(self.input_attention_q, dtype=float).copy() if getattr(self, "input_attention_q", None) is not None else None),
            input_attention_b=(np.asarray(self.input_attention_b, dtype=float).copy() if getattr(self, "input_attention_b", None) is not None else None),
            deep_attention_q=tuple(np.asarray(item, dtype=float).copy() for item in getattr(self, "deep_attention_q", ()) or ()),
            deep_attention_b=tuple(np.asarray(item, dtype=float).copy() for item in getattr(self, "deep_attention_b", ()) or ()),
            auxiliary_w=(np.asarray(self.auxiliary_w, dtype=float).copy() if getattr(self, "auxiliary_w", None) is not None else None),
            auxiliary_b=(np.asarray(self.auxiliary_b, dtype=float).copy() if getattr(self, "auxiliary_b", None) is not None else None),
            auxiliary_reconstruction_w=(np.asarray(self.auxiliary_reconstruction_w, dtype=float).copy() if getattr(self, "auxiliary_reconstruction_w", None) is not None else None),
            auxiliary_reconstruction_b=(np.asarray(self.auxiliary_reconstruction_b, dtype=float).copy() if getattr(self, "auxiliary_reconstruction_b", None) is not None else None),
            tensor_rule_bank=(
                self.tensor_rule_bank.copy()
                if isinstance(getattr(self, "tensor_rule_bank", None), TensorRuleBankState)
                else None
            ),
            state_alias_memory=(
                self.state_alias_memory.copy()
                if isinstance(getattr(self, "state_alias_memory", None), StateAliasingMemoryState)
                else None
            ),
        )

    def configure_rnn_adamw_cosine(self, config: Mapping[str, object]) -> None:
        """Install the persistent AdamW/cosine contract for Direct-RNN."""
        self.rnn_optimizer_enabled = bool(config.get("direct_rnn_adamw_enabled", False))
        self.rnn_optimizer_learning_rate = float(np.clip(
            float(config.get("direct_rnn_adamw_learning_rate", 0.0005) or 0.0005), 1e-6, 0.02
        ))
        self.rnn_optimizer_weight_decay = float(np.clip(
            float(config.get("direct_rnn_adamw_weight_decay", 1.0e-4) or 0.0), 0.0, 0.10
        ))
        self.rnn_optimizer_beta1 = float(np.clip(
            float(config.get("direct_rnn_adam_beta1", 0.90) or 0.90), 0.0, 0.9999
        ))
        self.rnn_optimizer_beta2 = float(np.clip(
            float(config.get("direct_rnn_adam_beta2", 0.999) or 0.999), 0.0, 0.999999
        ))
        self.rnn_optimizer_epsilon = float(np.clip(
            float(config.get("direct_rnn_adam_epsilon", 1.0e-8) or 1.0e-8), 1e-12, 1e-3
        ))
        self.rnn_optimizer_gradient_clip = float(np.clip(
            float(config.get("direct_rnn_gradient_clip", 1.0) or 1.0), 1e-6, 100.0
        ))
        self.rnn_optimizer_cosine_min_factor = float(np.clip(
            float(config.get("direct_rnn_cosine_min_factor", 0.20) or 0.20), 0.0, 1.0
        ))
        self.rnn_optimizer_cosine_cycle_steps = max(1, int(
            config.get("direct_rnn_cosine_cycle_steps", 256) or 256
        ))
        self.rnn_full_rl_enabled = bool(config.get("direct_rnn_full_rl_enabled", False))
        self.rnn_temporal_bptt_steps = max(1, int(config.get("direct_rnn_rl_temporal_bptt_steps", 8) or 8))
        if not isinstance(getattr(self, "rl_temporal_forward_history", None), list):
            self.rl_temporal_forward_history = []
        self.rl_temporal_forward_history = [
            item for item in self.rl_temporal_forward_history if isinstance(item, DirectRnnForwardTrace)
        ][-self.rnn_temporal_bptt_steps:]
        if not isinstance(getattr(self, "rnn_optimizer_m", None), dict):
            self.rnn_optimizer_m = {}
        if not isinstance(getattr(self, "rnn_optimizer_v", None), dict):
            self.rnn_optimizer_v = {}
        if not isinstance(getattr(self, "rnn_optimizer_last_stats", None), dict):
            self.rnn_optimizer_last_stats = {}
        self.rnn_optimizer_step = max(0, int(getattr(self, "rnn_optimizer_step", 0) or 0))
        self.configure_state_alias_memory(config)

    def configure_state_alias_memory(self, config: Mapping[str, object]) -> None:
        if str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE:
            # The published recurrent core owns its memory inside the LSTM cell.
            # A second retrieved-memory injection would change that core.
            self.state_alias_memory = None
            for state in (self.rnn_optimizer_m, self.rnn_optimizer_v):
                if isinstance(state, dict):
                    for key in tuple(state):
                        if str(key).startswith(STATE_ALIAS_MEMORY_PARAMETER_PREFIX):
                            state.pop(key, None)
            return
        enabled = bool(config.get("direct_rnn_state_memory_enabled", False))
        capacity = max(2, int(config.get("direct_rnn_state_memory_capacity", 32) or 32))
        memory_size = max(4, int(config.get("direct_rnn_state_memory_size", 32) or 32))
        min_history = int(np.clip(
            int(config.get("direct_rnn_state_memory_min_history", 4) or 4), 1, capacity
        ))
        temperature = float(np.clip(
            float(config.get("direct_rnn_state_memory_temperature", 1.0) or 1.0), 0.05, 10.0
        ))
        injection_scale = float(np.clip(
            float(config.get("direct_rnn_state_memory_injection_scale", 0.25) or 0.0), 0.0, 2.0
        ))
        path_delta_scale = float(np.clip(
            float(config.get("direct_rnn_state_memory_path_delta_scale", 0.75) or 0.0), 0.0, 4.0
        ))
        memory = getattr(self, "state_alias_memory", None)
        if not enabled and not isinstance(memory, StateAliasingMemoryState):
            return
        topology_matches = bool(
            isinstance(memory, StateAliasingMemoryState)
            and int(memory.input_size) == int(self.input_size)
            and int(memory.hidden_size) == int(self.hidden_size)
            and int(memory.memory_size) == memory_size
            and int(memory.capacity) == capacity
        )
        if not topology_matches:
            source_digest = hashlib.sha256(
                np.ascontiguousarray(np.asarray(self.w_in, dtype=np.float32)).tobytes()
            ).hexdigest()[:20]
            seed = StateAliasingMemoryState.deterministic_seed(
                f"{self.name}|{source_digest}",
                self.input_size,
                self.hidden_size,
                memory_size,
            )
            memory = StateAliasingMemoryState.seed(
                input_size=self.input_size,
                hidden_size=self.hidden_size,
                memory_size=memory_size,
                capacity=capacity,
                min_history=min_history,
                temperature=temperature,
                injection_scale=injection_scale,
                path_delta_scale=path_delta_scale,
                enabled=enabled,
                seed=seed,
            )
            self.state_alias_memory = memory
            # Topology replacement invalidates only the memory moments. Other
            # Direct-RNN AdamW state remains untouched.
            for state in (self.rnn_optimizer_m, self.rnn_optimizer_v):
                for key in tuple(state):
                    if str(key).startswith(STATE_ALIAS_MEMORY_PARAMETER_PREFIX):
                        state.pop(key, None)
        memory.configure({
            "direct_rnn_state_memory_enabled": enabled,
            "direct_rnn_state_memory_capacity": capacity,
            "direct_rnn_state_memory_size": memory_size,
            "direct_rnn_state_memory_min_history": min_history,
            "direct_rnn_state_memory_temperature": temperature,
            "direct_rnn_state_memory_injection_scale": injection_scale,
            "direct_rnn_state_memory_path_delta_scale": path_delta_scale,
        })

    def _rnn_optimizer_parameters(self) -> dict[str, np.ndarray]:
        five_core = str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE
        if five_core:
            parameters = {
                "lstm_w_in": np.asarray(self.lstm_w_in, dtype=np.float32),
                "lstm_w_rec": np.asarray(self.lstm_w_rec, dtype=np.float32),
                "lstm_b": np.asarray(self.lstm_b, dtype=np.float32),
                "w_out": self.w_out,
                "b_out": self.b_out,
                "value_w": self.value_w,
                "value_b": np.asarray([float(self.value_b)], dtype=np.float32),
            }
        else:
            parameters = {
                "w_in": self.w_in,
                "w_rec": self.w_rec,
                "w_out": self.w_out,
                "b_hidden": self.b_hidden,
                "b_out": self.b_out,
                "gate_w": self.gate_w,
                "value_w": self.value_w,
                # Scalars use a one-element temporary array and are written back
                # after the optimizer step so they share AdamW state as well.
                "gate_b": np.asarray([float(self.gate_b)], dtype=float),
                "value_b": np.asarray([float(self.value_b)], dtype=float),
            }
        if (not five_core) and bool(getattr(self, "attention_enabled", True)):
            input_attention_q = getattr(self, "input_attention_q", None)
            input_attention_b = getattr(self, "input_attention_b", None)
            parameters["input_attention_q"] = np.asarray(
                input_attention_q if input_attention_q is not None else np.zeros(self.input_size), dtype=float
            )
            parameters["input_attention_b"] = np.asarray(
                input_attention_b if input_attention_b is not None else np.zeros(self.input_size), dtype=float
            )
            for index, layer in enumerate(tuple(getattr(self, "deep_attention_q", ()) or ())):
                parameters[f"deep_attention_q_{index}"] = np.asarray(layer, dtype=float)
            for index, layer in enumerate(tuple(getattr(self, "deep_attention_b", ()) or ())):
                parameters[f"deep_attention_b_{index}"] = np.asarray(layer, dtype=float)
        for index, layer in enumerate(tuple(getattr(self, "deep_w", ()) or ()) if not five_core else ()):
            parameters[f"deep_w_{index}"] = layer
        for index, layer in enumerate(tuple(getattr(self, "deep_rec", ()) or ()) if not five_core else ()):
            parameters[f"deep_rec_{index}"] = layer
        for index, layer in enumerate(tuple(getattr(self, "deep_b", ()) or ()) if not five_core else ()):
            parameters[f"deep_b_{index}"] = layer
        if (not five_core) and self.w_lat is not None:
            parameters["w_lat"] = self.w_lat
        quality_w = getattr(self, "conditioned_quality_w", None)
        quality_b = getattr(self, "conditioned_quality_b", None)
        if np.asarray(quality_w).shape == (CONDITIONED_REPRESENTATION_HEAD_COUNT, self.hidden_size):
            parameters["conditioned_quality_w"] = np.asarray(quality_w, dtype=float)
        if np.asarray(quality_b).shape == (CONDITIONED_REPRESENTATION_HEAD_COUNT,):
            parameters["conditioned_quality_b"] = np.asarray(quality_b, dtype=float)
        if np.asarray(getattr(self, "auxiliary_w", None)).shape == (AUXILIARY_OUTPUT_COUNT, self.hidden_size):
            parameters["auxiliary_w"] = np.asarray(self.auxiliary_w, dtype=float)
        if np.asarray(getattr(self, "auxiliary_b", None)).shape == (AUXILIARY_OUTPUT_COUNT,):
            parameters["auxiliary_b"] = np.asarray(self.auxiliary_b, dtype=float)
        if np.asarray(getattr(self, "auxiliary_reconstruction_w", None)).shape == (self.input_size, self.hidden_size):
            parameters["auxiliary_reconstruction_w"] = np.asarray(self.auxiliary_reconstruction_w, dtype=float)
        if np.asarray(getattr(self, "auxiliary_reconstruction_b", None)).shape == (self.input_size,):
            parameters["auxiliary_reconstruction_b"] = np.asarray(self.auxiliary_reconstruction_b, dtype=float)
        tensor_rule_bank = getattr(self, "tensor_rule_bank", None)
        if isinstance(tensor_rule_bank, TensorRuleBankState):
            tensor_rule_bank.ensure_compatible()
            parameters.update(tensor_rule_bank.parameters())
        state_alias_memory = getattr(self, "state_alias_memory", None)
        if isinstance(state_alias_memory, StateAliasingMemoryState) and state_alias_memory.enabled:
            state_alias_memory.ensure_compatible()
            parameters.update(state_alias_memory.parameters())
        return parameters

    @staticmethod
    def _direct_rnn_tensor_fingerprint(tensors: Iterable[tuple[str, np.ndarray]]) -> str:
        """Return a stable, value-based fingerprint for compact optimizer telemetry.

        The legacy ``weight_hash`` describes the dormant reasoning graph and
        policy revision.  It is deliberately *not* used here: a Full-RL
        Direct-RNN update must be observable from the actual tensor values.
        ``float64`` plus a shape/name prefix makes the digest stable across
        contiguous/non-contiguous tensor views and unambiguous across blocks.
        """
        digest = hashlib.sha256()
        for label, tensor in tensors:
            values = np.ascontiguousarray(np.asarray(tensor, dtype=np.float64))
            digest.update(str(label).encode("utf-8"))
            digest.update(repr(tuple(int(size) for size in values.shape)).encode("ascii"))
            digest.update(values.tobytes(order="C"))
        return digest.hexdigest()[:20]

    def _direct_rnn_optimizer_block_views(
        self,
        parameters: Mapping[str, np.ndarray] | None = None,
    ) -> dict[str, tuple[tuple[str, np.ndarray], ...]]:
        """Expose the actual Direct-RNN parameter blocks for batch auditing.

        The returned arrays are copied snapshots, never live views.  Output
        rows are deliberately split so the fixed geometry compatibility rows
        13/14 can be proven frozen independently from the actor, risk and
        auxiliary parameter rows.
        """
        values = dict(parameters or self._rnn_optimizer_parameters())
        blocks: dict[str, tuple[tuple[str, np.ndarray], ...]] = {}

        def add_block(name: str, entries: Iterable[tuple[str, np.ndarray]]) -> None:
            copied: list[tuple[str, np.ndarray]] = []
            for label, tensor in entries:
                array = np.asarray(tensor, dtype=float)
                if array.size:
                    copied.append((str(label), np.ascontiguousarray(array).copy()))
            if copied:
                blocks[str(name)] = tuple(copied)

        if str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE:
            # Keep optimizer telemetry bounded. Copying the complete 4096-unit
            # recurrent matrix twice just to compute an audit delta would add
            # hundreds of MiB of transient memory. The optimizer itself still
            # updates every parameter; telemetry samples fixed leading blocks.
            five_in = np.asarray(values.get("lstm_w_in", np.zeros(0, dtype=np.float32)))
            five_rec = np.asarray(values.get("lstm_w_rec", np.zeros(0, dtype=np.float32)))
            five_bias = np.asarray(values.get("lstm_b", np.zeros(0, dtype=np.float32)))
            add_block("encoder", (
                ("lstm_w_in_sample", five_in[:min(64, five_in.shape[0]), :min(64, five_in.shape[1])] if five_in.ndim == 2 else five_in),
                ("lstm_w_rec_sample", five_rec[:min(64, five_rec.shape[0]), :min(64, five_rec.shape[1])] if five_rec.ndim == 2 else five_rec),
                ("lstm_b_sample", five_bias[:min(256, five_bias.size)]),
            ))
        else:
            add_block("encoder", (
                ("input_attention_q", values.get("input_attention_q", np.zeros(0, dtype=float))),
                ("input_attention_b", values.get("input_attention_b", np.zeros(0, dtype=float))),
                ("w_in", values.get("w_in", np.zeros(0, dtype=float))),
                ("w_rec", values.get("w_rec", np.zeros(0, dtype=float))),
                ("b_hidden", values.get("b_hidden", np.zeros(0, dtype=float))),
            ))
        for index in range(len(tuple(getattr(self, "deep_w", ()) or ()))):
            add_block(f"hidden_layer_{index + 1}", (
                (f"deep_attention_q_{index}", values.get(f"deep_attention_q_{index}", np.zeros(0, dtype=float))),
                (f"deep_attention_b_{index}", values.get(f"deep_attention_b_{index}", np.zeros(0, dtype=float))),
                (f"deep_w_{index}", values.get(f"deep_w_{index}", np.zeros(0, dtype=float))),
                (f"deep_rec_{index}", values.get(f"deep_rec_{index}", np.zeros(0, dtype=float))),
                (f"deep_b_{index}", values.get(f"deep_b_{index}", np.zeros(0, dtype=float))),
            ))

        output_w = np.asarray(values.get("w_out", np.zeros((0, 0), dtype=float)), dtype=float)
        output_b = np.asarray(values.get("b_out", np.zeros(0, dtype=float)), dtype=float)
        action_stop = min(int(EXECUTION_ACTION_COUNT), int(output_w.shape[0]))
        if action_stop:
            add_block("action_head", (
                ("w_out_rows_0_11", output_w[:action_stop]),
                ("b_out_rows_0_11", output_b[:action_stop]),
            ))
        risk_row = int(EXECUTION_ACTION_COUNT)
        if risk_row < output_w.shape[0]:
            add_block("risk_head", (
                ("w_out_row_12", output_w[risk_row:risk_row + 1]),
                ("b_out_row_12", output_b[risk_row:risk_row + 1]),
            ))
        geometry_rows = [
            row for row in (int(SL_OUTPUT_INDEX), int(RR_OUTPUT_INDEX))
            if 0 <= row < output_w.shape[0]
        ]
        if geometry_rows:
            add_block("geometry_compatibility_head", (
                ("w_out_rows_13_14", output_w[geometry_rows]),
                ("b_out_rows_13_14", output_b[geometry_rows]),
            ))
        parameter_start = max(geometry_rows, default=risk_row) + 1
        if parameter_start < output_w.shape[0]:
            add_block("execution_parameter_head", (
                ("w_out_rows_15_plus", output_w[parameter_start:]),
                ("b_out_rows_15_plus", output_b[parameter_start:]),
            ))

        add_block("value_head", (
            ("value_w", values.get("value_w", np.zeros(0, dtype=float))),
            ("value_b", values.get("value_b", np.zeros(0, dtype=float))),
        ))
        add_block("gate", (
            ("gate_w", values.get("gate_w", np.zeros(0, dtype=float))),
            ("gate_b", values.get("gate_b", np.zeros(0, dtype=float))),
        ))
        if "w_lat" in values:
            add_block("lateral_recurrence", (("w_lat", values["w_lat"]),))
        if "conditioned_quality_w" in values or "conditioned_quality_b" in values:
            add_block("conditioned_representation_head", (
                ("conditioned_quality_w", values.get("conditioned_quality_w", np.zeros(0, dtype=float))),
                ("conditioned_quality_b", values.get("conditioned_quality_b", np.zeros(0, dtype=float))),
            ))
        add_block("multi_task_auxiliary_head", (
            ("auxiliary_w", values.get("auxiliary_w", np.zeros(0, dtype=float))),
            ("auxiliary_b", values.get("auxiliary_b", np.zeros(0, dtype=float))),
        ))
        add_block("snapshot_reconstruction_head", (
            ("auxiliary_reconstruction_w", values.get("auxiliary_reconstruction_w", np.zeros(0, dtype=float))),
            ("auxiliary_reconstruction_b", values.get("auxiliary_reconstruction_b", np.zeros(0, dtype=float))),
        ))
        state_memory_entries = tuple(
            (name, value) for name, value in values.items()
            if str(name).startswith(STATE_ALIAS_MEMORY_PARAMETER_PREFIX)
        )
        if state_memory_entries:
            add_block("state_alias_temporal_memory", state_memory_entries)
        tensor_rule_entries = tuple(
            (name, value) for name, value in values.items()
            if str(name).startswith(TENSOR_RULE_PARAMETER_PREFIX)
        )
        if tensor_rule_entries:
            add_block("tensor_rule_abstraction", tensor_rule_entries)
        return blocks

    @classmethod
    def _direct_rnn_block_snapshot(
        cls,
        views: Mapping[str, Iterable[tuple[str, np.ndarray]]],
    ) -> dict[str, object]:
        """Capture fingerprints/norms without retaining optimizer-sized arrays."""
        block_payload: dict[str, dict[str, object]] = {}
        whole_digest = hashlib.sha256()
        for name in sorted(views):
            tensors = tuple((label, np.asarray(tensor, dtype=float)) for label, tensor in views[name])
            if not tensors:
                continue
            count = int(sum(tensor.size for _, tensor in tensors))
            l2 = float(np.sqrt(sum(float(np.sum(tensor * tensor)) for _, tensor in tensors)))
            fingerprint = cls._direct_rnn_tensor_fingerprint(tensors)
            block_payload[str(name)] = {
                "fingerprint": fingerprint,
                "parameter_count": count,
                "parameter_l2": l2,
                "parameters": [label for label, _ in tensors],
            }
            whole_digest.update(str(name).encode("utf-8"))
            whole_digest.update(fingerprint.encode("ascii"))
        return {
            "fingerprint": whole_digest.hexdigest()[:20],
            "blocks": block_payload,
        }

    @classmethod
    def _direct_rnn_block_delta_telemetry(
        cls,
        before: Mapping[str, Iterable[tuple[str, np.ndarray]]],
        after: Mapping[str, Iterable[tuple[str, np.ndarray]]],
    ) -> dict[str, object]:
        """Summarise one AdamW write at block granularity, without tensors."""
        before_snapshot = cls._direct_rnn_block_snapshot(before)
        after_snapshot = cls._direct_rnn_block_snapshot(after)
        block_deltas: dict[str, dict[str, object]] = {}
        for name in sorted(set(before).union(after)):
            before_tensors = {
                label: np.asarray(tensor, dtype=float)
                for label, tensor in before.get(name, ())
            }
            after_tensors = {
                label: np.asarray(tensor, dtype=float)
                for label, tensor in after.get(name, ())
            }
            delta_l2_sq = 0.0
            delta_linf = 0.0
            changed = 0
            count = 0
            for label in sorted(set(before_tensors).union(after_tensors)):
                previous = before_tensors.get(label)
                current = after_tensors.get(label)
                if (
                    previous is None
                    or current is None
                    or previous.shape != current.shape
                ):
                    continue
                delta = current - previous
                delta_l2_sq += float(np.sum(delta * delta))
                delta_linf = max(
                    delta_linf,
                    float(np.max(np.abs(delta))) if delta.size else 0.0,
                )
                changed += int(np.count_nonzero(np.abs(delta) > 1e-15))
                count += int(delta.size)
            previous_meta = dict(
                dict(before_snapshot.get("blocks", {}) or {}).get(name, {}) or {}
            )
            current_meta = dict(
                dict(after_snapshot.get("blocks", {}) or {}).get(name, {}) or {}
            )
            delta_l2 = float(np.sqrt(max(0.0, delta_l2_sq)))
            previous_l2 = float(previous_meta.get("parameter_l2", 0.0) or 0.0)
            block_deltas[str(name)] = {
                "fingerprint_before": str(previous_meta.get("fingerprint", "") or ""),
                "fingerprint_after": str(current_meta.get("fingerprint", "") or ""),
                "parameter_count": int(count),
                "changed_parameter_count": int(changed),
                "delta_l2": delta_l2,
                "delta_linf": float(delta_linf),
                "relative_delta_l2": float(delta_l2 / max(previous_l2, 1e-12)),
                "parameters": list(
                    current_meta.get("parameters", previous_meta.get("parameters", ()))
                    or ()
                ),
            }
        return {
            "schema_version": 1,
            "fingerprint_before": str(before_snapshot.get("fingerprint", "") or ""),
            "fingerprint_after": str(after_snapshot.get("fingerprint", "") or ""),
            "blocks": block_deltas,
        }

    def apply_rnn_adamw_cosine(
        self,
        directions: Mapping[str, np.ndarray],
        *,
        source: str = "unknown",
        frozen_output_rows: Iterable[int] = (),
    ) -> dict[str, object]:
        """Apply ascent directions through AdamW and a lifecycle-clocked cosine LR.

        ``directions`` are local credit gradients (positive means increase the
        parameter). They are never written directly to a weight matrix.
        """
        if not bool(getattr(self, "rnn_optimizer_enabled", False)):
            return {
                "updated": 0.0,
                "optimizer_step": float(getattr(self, "rnn_optimizer_step", 0) or 0),
            }
        if (
            bool(getattr(self, "rnn_full_rl_enabled", False))
            and str(source) != "full_lifecycle_rl"
        ):
            return {
                "updated": 0.0,
                "optimizer_step": float(getattr(self, "rnn_optimizer_step", 0) or 0),
                "optimizer_skipped_non_rl": 1.0,
            }

        pending_rule = getattr(self, "_tensor_rule_pending_directions", None)
        if str(source) == "full_lifecycle_rl" and isinstance(pending_rule, Mapping):
            merged = {
                str(key): np.asarray(value, dtype=float)
                for key, value in directions.items()
            }
            for key, value in pending_rule.items():
                array = np.asarray(value, dtype=float)
                merged[str(key)] = merged.get(
                    str(key), np.zeros_like(array)
                ) + array
            directions = merged
            self._tensor_rule_pending_directions = {}

        parameters = self._rnn_optimizer_parameters()
        frozen_rows = tuple(
            sorted({
                int(row)
                for row in frozen_output_rows
                if 0 <= int(row) < self.output_size
            })
        )
        if frozen_rows:
            for key in ("w_out", "b_out"):
                state = getattr(self, "rnn_optimizer_m", {}).get(key)
                variance_state = getattr(self, "rnn_optimizer_v", {}).get(key)
                if key == "w_out":
                    shape = getattr(self.w_out, "shape", ())
                else:
                    shape = getattr(self.b_out, "shape", ())
                if isinstance(state, np.ndarray) and state.shape == shape:
                    state[list(frozen_rows), ...] = 0.0
                if isinstance(variance_state, np.ndarray) and variance_state.shape == shape:
                    variance_state[list(frozen_rows), ...] = 0.0

        prepared: dict[str, np.ndarray] = {}
        for key, value in directions.items():
            parameter = parameters.get(str(key))
            if parameter is None:
                continue
            parameter_dtype = np.asarray(parameter).dtype
            direction_dtype = np.float32 if parameter_dtype == np.float32 else float
            direction = np.asarray(value, dtype=direction_dtype)
            if direction.shape != parameter.shape:
                continue
            clean = np.nan_to_num(direction, nan=0.0, posinf=0.0, neginf=0.0)
            if frozen_rows and str(key) == "w_out":
                clean[list(frozen_rows), ...] = 0.0
            elif frozen_rows and str(key) == "b_out":
                clean[list(frozen_rows), ...] = 0.0
            if np.any(np.abs(clean) > 1e-15):
                prepared[str(key)] = clean
        if not prepared:
            return {
                "updated": 0.0,
                "optimizer_step": float(getattr(self, "rnn_optimizer_step", 0) or 0),
            }

        direct_rnn_blocks_before = self._direct_rnn_optimizer_block_views(parameters)
        raw_norm_sq = sum(
            float(np.sum(value * value)) for value in prepared.values()
        )
        raw_norm = float(np.sqrt(max(0.0, raw_norm_sq)))
        clip = max(
            1e-12,
            float(getattr(self, "rnn_optimizer_gradient_clip", 1.0) or 1.0),
        )
        clip_factor = min(1.0, clip / max(raw_norm, 1e-12))
        if clip_factor < 1.0:
            prepared = {
                key: value * clip_factor for key, value in prepared.items()
            }

        step = max(0, int(getattr(self, "rnn_optimizer_step", 0) or 0)) + 1
        beta1 = float(getattr(self, "rnn_optimizer_beta1", 0.90) or 0.90)
        beta2 = float(getattr(self, "rnn_optimizer_beta2", 0.999) or 0.999)
        epsilon = float(getattr(self, "rnn_optimizer_epsilon", 1e-8) or 1e-8)
        phase = (step - 1) % max(
            1, int(getattr(self, "rnn_optimizer_cosine_cycle_steps", 256) or 256)
        )
        cycle = max(
            1, int(getattr(self, "rnn_optimizer_cosine_cycle_steps", 256) or 256)
        )
        cosine_min = float(
            getattr(self, "rnn_optimizer_cosine_min_factor", 0.20) or 0.20
        )
        cosine_factor = cosine_min + (1.0 - cosine_min) * 0.5 * (
            1.0 + np.cos(np.pi * phase / cycle)
        )
        learning_rate = float(
            getattr(self, "rnn_optimizer_learning_rate", 0.0005) or 0.0005
        ) * cosine_factor
        decay = float(getattr(self, "rnn_optimizer_weight_decay", 0.0) or 0.0)
        update_norm_sq = 0.0
        decayed = 0
        for key, direction in prepared.items():
            parameter = parameters[key]
            state_dtype = (
                np.float32 if np.asarray(parameter).dtype == np.float32 else float
            )
            moment = np.asarray(
                getattr(self, "rnn_optimizer_m", {}).get(
                    key, np.zeros_like(parameter)
                ),
                dtype=state_dtype,
            )
            variance = np.asarray(
                getattr(self, "rnn_optimizer_v", {}).get(
                    key, np.zeros_like(parameter)
                ),
                dtype=state_dtype,
            )
            if moment.shape != parameter.shape:
                moment = np.zeros_like(parameter)
            if variance.shape != parameter.shape:
                variance = np.zeros_like(parameter)
            output_row_mask: np.ndarray | None = None
            if frozen_rows and key == "w_out":
                output_row_mask = np.ones(parameter.shape, dtype=bool)
                output_row_mask[list(frozen_rows), :] = False
                moment[list(frozen_rows), :] = 0.0
                variance[list(frozen_rows), :] = 0.0
            elif frozen_rows and key == "b_out":
                output_row_mask = np.ones(parameter.shape, dtype=bool)
                output_row_mask[list(frozen_rows)] = False
                moment[list(frozen_rows)] = 0.0
                variance[list(frozen_rows)] = 0.0
            moment = beta1 * moment + (1.0 - beta1) * direction
            variance = beta2 * variance + (1.0 - beta2) * direction * direction
            moment_hat = moment / max(1e-12, 1.0 - beta1 ** step)
            variance_hat = variance / max(1e-12, 1.0 - beta2 ** step)
            update = learning_rate * moment_hat / (np.sqrt(variance_hat) + epsilon)
            if output_row_mask is not None:
                update = np.where(output_row_mask, update, 0.0)
                moment = np.where(output_row_mask, moment, 0.0)
                variance = np.where(output_row_mask, variance, 0.0)
            if decay > 0.0:
                factor = max(0.0, 1.0 - learning_rate * decay)
                if output_row_mask is None:
                    parameter *= factor
                    decayed += int(parameter.size)
                else:
                    parameter[output_row_mask] *= factor
                    decayed += int(np.count_nonzero(output_row_mask))
            parameter += update
            if key in frozenset({
                "w_in", "w_rec", "w_lat", "b_hidden",
                "lstm_w_in", "lstm_w_rec", "lstm_b",
            }):
                np.clip(parameter, -4.0, 4.0, out=parameter)
            else:
                np.clip(parameter, -8.0, 8.0, out=parameter)
            if key == "gate_b":
                self.gate_b = float(parameter[0])
            elif key == "value_b":
                self.value_b = float(parameter[0])
            self.rnn_optimizer_m[key] = moment
            self.rnn_optimizer_v[key] = variance
            update_norm_sq += float(np.sum(update * update))

        if (
            self.input_mask is not None
            and self.input_mask.size == self.input_size
        ):
            if (
                str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn")
                .strip()
                .lower()
                == OPENAI_FIVE_RECURRENT_CORE
            ):
                if self.lstm_w_in is not None:
                    self.lstm_w_in[:, self.input_mask < 0.5] = 0.0
            else:
                self.w_in[:, self.input_mask < 0.5] = 0.0
        if (
            self.output_mask is not None
            and self.output_mask.size == self.output_size
        ):
            self.w_out[self.output_mask < 0.5, :] = 0.0

        tensor_rule_bank = getattr(self, "tensor_rule_bank", None)
        if isinstance(tensor_rule_bank, TensorRuleBankState):
            tensor_rule_bank.sanitize()
        state_alias_memory = getattr(self, "state_alias_memory", None)
        if isinstance(state_alias_memory, StateAliasingMemoryState):
            state_alias_memory.sanitize()
        self.rnn_optimizer_step = step
        direct_rnn_blocks = self._direct_rnn_block_delta_telemetry(
            direct_rnn_blocks_before,
            self._direct_rnn_optimizer_block_views(),
        )
        stats: dict[str, object] = {
            "updated": 1.0,
            "optimizer_step": float(step),
            "optimizer_raw_gradient_norm": raw_norm,
            "optimizer_gradient_clip_factor": float(clip_factor),
            "optimizer_cosine_factor": float(cosine_factor),
            "optimizer_effective_learning_rate": float(learning_rate),
            "optimizer_weight_decay": decay,
            "optimizer_decayed_parameters": float(decayed),
            "optimizer_update_norm": float(
                np.sqrt(max(0.0, update_norm_sq))
            ),
            "direct_rnn_blocks": direct_rnn_blocks,
        }
        self.rnn_optimizer_last_stats = dict(stats)
        return stats

    def _normalize_hidden_layer(self, values: np.ndarray, layer_index: int, layer_count: int) -> np.ndarray:
        # Repair stale/tampered artifact state at the forward boundary.  A
        # hidden block may never bypass normalization in the Direct-RNN path.
        self.hidden_normalization_mode = _mandatory_hidden_normalization_mode(
            getattr(self, "hidden_normalization_mode", REQUIRED_HIDDEN_NORMALIZATION_MODE)
        )
        self.hidden_normalization_enabled = True
        self.hidden_normalization_layers = tuple(True for _ in range(max(1, layer_count)))
        return normalize_hidden(
            values,
            mode=self.hidden_normalization_mode,
            target_rms=float(getattr(self, "hidden_normalization_target_rms", 1.0) or 1.0),
            clip=float(getattr(self, "hidden_normalization_clip", 3.0) or 3.0),
            eps=float(getattr(self, "hidden_normalization_eps", 1e-5) or 1e-5),
        )

    def _dropout_hidden(
        self,
        values: np.ndarray,
        layer_index: int,
        layer_count: int,
        *,
        training: bool,
        dropout_step: int,
    ) -> np.ndarray:
        # Dropout must remain configured for every hidden block.  It is
        # correctly inactive only for deterministic inference/OOS forwards.
        self.hidden_dropout_enabled = True
        self.hidden_dropout_train_only = True
        self.hidden_dropout_rates = mandatory_layerwise_rates(
            getattr(self, "hidden_dropout_rates", REQUIRED_HIDDEN_DROPOUT_RATES),
            max(1, layer_count),
        )
        if not training:
            return np.asarray(values, dtype=float).reshape(-1).copy()
        rates = layerwise_rates(getattr(self, "hidden_dropout_rates", ()), layer_count)
        rate = rates[min(max(0, int(layer_index)), layer_count - 1)]
        return deterministic_dropout(
            values,
            rate,
            seed=max(0, int(getattr(self, "hidden_dropout_seed", 0) or 0)),
            step=dropout_step,
            layer_index=layer_index,
        )

    def _dropout_scale(
        self,
        values: np.ndarray,
        layer_index: int,
        layer_count: int,
        *,
        training: bool,
        dropout_step: int,
    ) -> np.ndarray:
        """Return the exact inverted-dropout Jacobian for one forward layer."""
        return self._dropout_hidden(
            np.ones_like(np.asarray(values, dtype=float).reshape(-1)),
            layer_index,
            layer_count,
            training=training,
            dropout_step=dropout_step,
        )

    @staticmethod
    def _feature_attention(
        values: np.ndarray,
        query: np.ndarray | None,
        bias: np.ndarray | None,
        *,
        enabled: bool,
    ) -> tuple[np.ndarray, np.ndarray]:
        """Apply scaled-softmax channel attention without changing width.

        Multiplying softmax by the channel count makes zero query/bias an
        identity map.  That property is required for behavior-compatible
        migration of learned checkpoints.
        """
        vector = np.asarray(values, dtype=float).reshape(-1)
        if not enabled or vector.size == 0:
            return vector.copy(), np.ones_like(vector)
        q = np.asarray(query, dtype=float).reshape(-1) if query is not None else np.zeros_like(vector)
        b = np.asarray(bias, dtype=float).reshape(-1) if bias is not None else np.zeros_like(vector)
        if q.size != vector.size:
            q = np.zeros_like(vector)
        if b.size != vector.size:
            b = np.zeros_like(vector)
        scores = np.clip(q * vector + b, -30.0, 30.0)
        shifted = scores - float(np.max(scores))
        probabilities = np.exp(shifted)
        probabilities /= max(float(np.sum(probabilities)), 1e-12)
        weights = float(vector.size) * probabilities
        return vector * weights, weights

    def _activate_openai_five_lstm(
        self,
        observation: np.ndarray,
        previous_hidden: np.ndarray | None = None,
    ) -> tuple[float, np.ndarray, np.ndarray]:
        """Run the published OpenAI Five recurrent core: one 4096-unit LSTM.

        The trading bridge keeps its own observation and action semantics, but
        the recurrent transformation itself has no deep recurrent stack,
        feature attention, hidden normalization, dropout, STP, or fixed memory
        decay.  The LSTM hidden state feeds linear policy/value projections.
        """
        obs = np.asarray(observation, dtype=np.float32).reshape(-1)
        if obs.size != self.input_size:
            padded = np.zeros(self.input_size, dtype=np.float32)
            padded[: min(obs.size, self.input_size)] = obs[: self.input_size]
            obs = padded
        if self.input_mask is None or self.input_mask.size != self.input_size:
            self.input_mask = np.ones(self.input_size, dtype=float)
        if self.output_mask is None or self.output_mask.size != self.output_size:
            self.output_mask = np.ones(self.output_size, dtype=float)
        masked_obs = (obs * np.clip(self.input_mask, 0.0, 1.0)).astype(np.float32, copy=False)
        if previous_hidden is None or np.asarray(previous_hidden).size != self.hidden_size:
            previous_hidden = np.zeros(self.hidden_size, dtype=np.float32)
        else:
            previous_hidden = np.asarray(previous_hidden, dtype=np.float32).reshape(-1)
        previous_cell = getattr(self, "lstm_cell", None)
        if previous_cell is None or np.asarray(previous_cell).size != self.hidden_size:
            previous_cell = np.zeros(self.hidden_size, dtype=np.float32)
        else:
            previous_cell = np.asarray(previous_cell, dtype=np.float32).reshape(-1)
        if (
            getattr(self, "lstm_w_in", None) is None
            or np.asarray(self.lstm_w_in).shape != (4 * self.hidden_size, self.input_size)
            or getattr(self, "lstm_w_rec", None) is None
            or np.asarray(self.lstm_w_rec).shape != (4 * self.hidden_size, self.hidden_size)
            or getattr(self, "lstm_b", None) is None
            or np.asarray(self.lstm_b).shape != (4 * self.hidden_size,)
        ):
            seed_bytes = hashlib.sha256(f"{self.name}:openai-five-lstm".encode("utf-8")).digest()[:8]
            rng = np.random.default_rng(int.from_bytes(seed_bytes, "little", signed=False))
            self.lstm_w_in, self.lstm_w_rec, self.lstm_b = initialize_lstm(
                self.input_size, self.hidden_size, rng
            )
        forward = lstm_step(
            masked_obs, previous_hidden, previous_cell,
            self.lstm_w_in, self.lstm_w_rec, self.lstm_b,
        )
        self.lstm_cell = forward.cell.copy()
        hidden = forward.hidden.copy()
        self.deep_state = ()
        self.last_output_hidden = hidden.copy()
        output = (
            np.asarray(self.w_out, dtype=np.float32) @ hidden
            + np.asarray(self.b_out, dtype=np.float32)
        ) * np.clip(self.output_mask, 0.0, 1.0)
        empty = np.zeros(0, dtype=np.float32)
        self.last_forward_trace = DirectRnnForwardTrace(
            masked_observation=masked_obs.copy(),
            previous_hidden=previous_hidden.copy(),
            effective_w_in=empty.reshape(0, 0),
            base_raw_preactivation=empty.copy(),
            base_normalized_preactivation=empty.copy(),
            base_candidate=empty.copy(),
            base_hidden=hidden.copy(),
            deep_inputs=(),
            deep_previous_states=(),
            deep_raw_preactivations=(),
            deep_normalized_preactivations=(),
            deep_candidates=(),
            deep_hidden=(),
            dropout_scales=(),
            output_hidden=hidden.copy(),
            output_mask=np.asarray(self.output_mask, dtype=float).copy(),
            gate=1.0,
            normalization_enabled=(),
            normalization_mode="none",
            normalization_target_rms=1.0,
            normalization_clip=0.0,
            normalization_eps=0.0,
            attended_observation=masked_obs.copy(),
            base_attention_weights=np.ones(self.input_size, dtype=np.float32),
            recurrent_core=OPENAI_FIVE_RECURRENT_CORE,
            lstm_forward=forward,
        )
        if bool(getattr(self, "rnn_full_rl_enabled", False)):
            history = list(getattr(self, "rl_temporal_forward_history", []) or [])
            history.append(self.last_forward_trace)
            limit = max(1, int(getattr(self, "rnn_temporal_bptt_steps", 16) or 16))
            self.rl_temporal_forward_history = history[-limit:]
        return 1.0, hidden.astype(float), np.asarray(output, dtype=float)

    def activate(
        self,
        observation: np.ndarray,
        previous_hidden: np.ndarray | None = None,
        *,
        training: bool = False,
    ) -> tuple[float, np.ndarray, np.ndarray]:
        if str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE:
            return self._activate_openai_five_lstm(observation, previous_hidden)
        if previous_hidden is None or previous_hidden.size != self.hidden_size:
            previous_hidden = np.zeros(self.hidden_size, dtype=float)
        obs = np.asarray(observation, dtype=float).reshape(-1)
        if obs.size != self.input_size:
            padded = np.zeros(self.input_size, dtype=float)
            padded[: min(obs.size, self.input_size)] = obs[:self.input_size]
            obs = padded
        if self.input_mask is None or self.input_mask.size != self.input_size:
            self.input_mask = np.ones(self.input_size, dtype=float)
        if self.output_mask is None or self.output_mask.size != self.output_size:
            self.output_mask = np.ones(self.output_size, dtype=float)
        masked_obs = obs * np.clip(self.input_mask, 0.0, 1.0)
        attention_enabled = bool(getattr(self, "attention_enabled", True))
        attended_obs, base_attention_weights = self._feature_attention(
            masked_obs,
            getattr(self, "input_attention_q", None),
            getattr(self, "input_attention_b", None),
            enabled=attention_enabled,
        )
        state_alias_memory = getattr(self, "state_alias_memory", None)
        state_alias_memory_forward: StateAliasingMemoryForward | None = None
        state_alias_injection = np.zeros(self.hidden_size, dtype=float)
        if isinstance(state_alias_memory, StateAliasingMemoryState) and state_alias_memory.enabled:
            state_alias_memory_forward = state_alias_memory.read(masked_obs)
            state_alias_injection = np.asarray(
                state_alias_memory_forward.injected, dtype=float
            ).reshape(-1)
            if state_alias_injection.size != self.hidden_size:
                state_alias_injection = np.zeros(self.hidden_size, dtype=float)
        if self.p_stp is None:
            self.p_stp = np.ones_like(self.w_in)

        # Full-RL has a single optimizer-owned recurrent encoder.  STP is a
        # mutable, per-tick multiplier outside AdamW, therefore it would make
        # the executed action differ from the parameter surface receiving the
        # lifecycle gradient.  Keep it for legacy policies only.
        if bool(getattr(self, "rnn_full_rl_enabled", False)):
            effective_w = self.w_in.copy()
        else:
            stp_clip = float(np.clip(getattr(self, "stp_input_clip", 50.0) or 50.0, 0.1, 50.0))
            stp_drive = np.minimum(np.abs(attended_obs), stp_clip)
            self.p_stp = np.clip(self.stp_rho * self.p_stp + self.stp_alpha * stp_drive.reshape(1, -1), 0.01, 5.0)
            effective_w = self.w_in * self.p_stp

        recurrent = self.w_rec @ previous_hidden
        base_raw_preactivation = (
            effective_w @ attended_obs + recurrent + self.b_hidden + state_alias_injection
        )
        hidden_preactivation = base_raw_preactivation.copy()
        deep_w = tuple(getattr(self, "deep_w", ()) or ())
        layer_count = 1 + len(deep_w)
        hidden_preactivation = self._normalize_hidden_layer(hidden_preactivation, 0, layer_count)
        base_normalized_preactivation = hidden_preactivation.copy()
        base_candidate = np.tanh(hidden_preactivation)
        hidden = self.memory_decay * previous_hidden + (1.0 - self.memory_decay) * base_candidate
        base_hidden = hidden.copy()

        deep_rec = tuple(getattr(self, "deep_rec", ()) or ())
        deep_b = tuple(getattr(self, "deep_b", ()) or ())
        deep_state = tuple(getattr(self, "deep_state", ()) or ())
        if len(deep_rec) != len(deep_w):
            deep_rec = tuple(np.zeros((self.hidden_size, self.hidden_size), dtype=float) for _ in deep_w)
        if len(deep_b) != len(deep_w):
            deep_b = tuple(np.zeros(self.hidden_size, dtype=float) for _ in deep_w)
        if len(deep_state) != len(deep_w):
            deep_state = tuple(np.zeros(self.hidden_size, dtype=float) for _ in deep_w)

        dropout_active = bool(training)
        if dropout_active:
            self.hidden_dropout_step = max(0, int(getattr(self, "hidden_dropout_step", 0) or 0)) + 1
        dropout_step = max(0, int(getattr(self, "hidden_dropout_step", 0) or 0))
        next_deep_state: list[np.ndarray] = []
        deep_inputs: list[np.ndarray] = []
        deep_previous_states: list[np.ndarray] = []
        deep_raw_preactivations: list[np.ndarray] = []
        deep_normalized_preactivations: list[np.ndarray] = []
        deep_candidates: list[np.ndarray] = []
        deep_hidden: list[np.ndarray] = []
        deep_attention_inputs: list[np.ndarray] = []
        deep_attention_weights: list[np.ndarray] = []
        dropout_scales: list[np.ndarray] = []
        base_dropout_scale = self._dropout_scale(
            hidden, 0, layer_count, training=bool(training), dropout_step=dropout_step,
        )
        dropout_scales.append(base_dropout_scale.copy())
        layer_input = self._dropout_hidden(
            hidden,
            0,
            layer_count,
            training=bool(training),
            dropout_step=dropout_step,
        )
        final_hidden = hidden
        for deep_index, (layer_w, layer_rec, layer_b, layer_prev) in enumerate(zip(deep_w, deep_rec, deep_b, deep_state), start=1):
            if layer_w.shape != (self.hidden_size, self.hidden_size):
                continue
            if layer_rec.shape != (self.hidden_size, self.hidden_size):
                layer_rec = np.zeros((self.hidden_size, self.hidden_size), dtype=float)
            layer_prev = np.asarray(layer_prev, dtype=float).reshape(-1)
            if layer_prev.size != self.hidden_size:
                layer_prev = np.zeros(self.hidden_size, dtype=float)
            layer_b = np.asarray(layer_b, dtype=float).reshape(-1)
            if layer_b.size != self.hidden_size:
                layer_b = np.zeros(self.hidden_size, dtype=float)
            attention_input = layer_input.copy()
            attention_q = tuple(getattr(self, "deep_attention_q", ()) or ())
            attention_b = tuple(getattr(self, "deep_attention_b", ()) or ())
            attended_layer_input, layer_attention_weights = self._feature_attention(
                attention_input,
                attention_q[deep_index - 1] if deep_index - 1 < len(attention_q) else None,
                attention_b[deep_index - 1] if deep_index - 1 < len(attention_b) else None,
                enabled=attention_enabled,
            )
            deep_attention_inputs.append(attention_input)
            deep_attention_weights.append(layer_attention_weights.copy())
            deep_inputs.append(attended_layer_input.copy())
            deep_previous_states.append(layer_prev.copy())
            layer_raw_preactivation = layer_w @ attended_layer_input + layer_rec @ layer_prev + layer_b
            layer_preactivation = self._normalize_hidden_layer(layer_raw_preactivation, deep_index, layer_count)
            layer_candidate = np.tanh(layer_preactivation)
            layer_hidden = self.memory_decay * layer_prev + (1.0 - self.memory_decay) * layer_candidate
            deep_raw_preactivations.append(layer_raw_preactivation.copy())
            deep_normalized_preactivations.append(layer_preactivation.copy())
            deep_candidates.append(layer_candidate.copy())
            deep_hidden.append(layer_hidden.copy())
            next_deep_state.append(layer_hidden)
            final_hidden = layer_hidden
            layer_dropout_scale = self._dropout_scale(
                layer_hidden, deep_index, layer_count, training=bool(training), dropout_step=dropout_step,
            )
            dropout_scales.append(layer_dropout_scale.copy())
            layer_input = self._dropout_hidden(
                layer_hidden,
                deep_index,
                layer_count,
                training=bool(training),
                dropout_step=dropout_step,
            )
        self.deep_state = tuple(next_deep_state)
        hidden = final_hidden

        raw_gate = float(self.gate_w @ masked_obs + self.gate_b)
        gate = 1.0 / (1.0 + np.exp(-np.clip(raw_gate, -60.0, 60.0)))
        output_hidden = layer_input if deep_w else self._dropout_hidden(
            hidden,
            0,
            layer_count,
            training=bool(training),
            dropout_step=dropout_step,
        )
        # Keep the recurrent memory unmasked in the return value, but expose
        # the exact masked path for lifecycle/neuron credit and telemetry.
        self.last_output_hidden = np.asarray(output_hidden, dtype=float).copy()
        output = (self.w_out @ output_hidden + self.b_out) * np.clip(self.output_mask, 0.0, 1.0)
        normalization_switches = tuple(True for _ in range(layer_count))
        normalization_active = True
        self.last_forward_trace = DirectRnnForwardTrace(
            masked_observation=masked_obs.copy(),
            previous_hidden=previous_hidden.copy(),
            effective_w_in=effective_w.copy(),
            base_raw_preactivation=base_raw_preactivation.copy(),
            base_normalized_preactivation=base_normalized_preactivation.copy(),
            base_candidate=base_candidate.copy(),
            base_hidden=base_hidden.copy(),
            deep_inputs=tuple(item.copy() for item in deep_inputs),
            deep_previous_states=tuple(item.copy() for item in deep_previous_states),
            deep_raw_preactivations=tuple(item.copy() for item in deep_raw_preactivations),
            deep_normalized_preactivations=tuple(item.copy() for item in deep_normalized_preactivations),
            deep_candidates=tuple(item.copy() for item in deep_candidates),
            deep_hidden=tuple(item.copy() for item in deep_hidden),
            dropout_scales=tuple(item.copy() for item in dropout_scales),
            output_hidden=np.asarray(output_hidden, dtype=float).copy(),
            output_mask=np.asarray(self.output_mask, dtype=float).copy(),
            gate=float(gate),
            normalization_enabled=tuple(bool(normalization_active and switch) for switch in normalization_switches),
            normalization_mode=str(self.hidden_normalization_mode),
            normalization_target_rms=float(getattr(self, "hidden_normalization_target_rms", 1.0) or 1.0),
            normalization_clip=float(getattr(self, "hidden_normalization_clip", 3.0) or 3.0),
            normalization_eps=float(getattr(self, "hidden_normalization_eps", 1e-5) or 1e-5),
            attended_observation=attended_obs.copy(),
            base_attention_weights=base_attention_weights.copy(),
            deep_attention_inputs=tuple(item.copy() for item in deep_attention_inputs),
            deep_attention_weights=tuple(item.copy() for item in deep_attention_weights),
            state_alias_memory_forward=state_alias_memory_forward,
        )
        # The current observation becomes readable only by future decisions.
        # Appending after the forward is the no-lookahead boundary.
        if isinstance(state_alias_memory, StateAliasingMemoryState) and state_alias_memory.enabled:
            state_alias_memory.remember(masked_obs)
        if bool(getattr(self, "rnn_full_rl_enabled", False)):
            history = list(getattr(self, "rl_temporal_forward_history", []) or [])
            history.append(self.last_forward_trace)
            self.rl_temporal_forward_history = history[-max(1, int(getattr(self, "rnn_temporal_bptt_steps", 8) or 8)):]
        return gate, hidden, output

    def reforward_immutable(
        self,
        source: DirectRnnForwardTrace,
        *,
        previous_hidden: np.ndarray | None = None,
        previous_deep_states: tuple[np.ndarray, ...] | None = None,
    ) -> tuple[float, np.ndarray, tuple[np.ndarray, ...], np.ndarray, DirectRnnForwardTrace]:
        """Re-run a causal decision cache using the module's current weights.

        This is deliberately side-effect free: recurrent state, dropout step,
        temporal history and State-Aliasing Memory buffers remain unchanged.
        Frozen observations/history and decision-time dropout masks are data;
        every trainable tensor is read from the current module.  Delayed
        credit therefore differentiates the policy that will actually receive
        the AdamW update, not an activation produced by an older policy.
        """
        if not isinstance(source, DirectRnnForwardTrace):
            raise TypeError("source must be DirectRnnForwardTrace")
        if str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE:
            cached = getattr(source, "lstm_forward", None)
            if not isinstance(cached, OpenAIFiveLSTMForward):
                raise ValueError("Five recurrent trace is missing its LSTM cache")
            masked_obs = self._resize_local(
                np.asarray(source.masked_observation, dtype=np.float32), self.input_size
            ).astype(np.float32)
            prev_hidden = self._resize_local(
                np.asarray(cached.previous_hidden if previous_hidden is None else previous_hidden, dtype=np.float32),
                self.hidden_size,
            ).astype(np.float32)
            prev_cell = self._resize_local(
                np.asarray(cached.previous_cell, dtype=np.float32), self.hidden_size
            ).astype(np.float32)
            current = lstm_step(
                masked_obs, prev_hidden, prev_cell,
                np.asarray(self.lstm_w_in, dtype=np.float32),
                np.asarray(self.lstm_w_rec, dtype=np.float32),
                np.asarray(self.lstm_b, dtype=np.float32),
            )
            hidden = np.asarray(current.hidden, dtype=np.float32)
            output = (
                np.asarray(self.w_out, dtype=np.float32) @ hidden
                + np.asarray(self.b_out, dtype=np.float32)
            ) * np.clip(np.asarray(self.output_mask, dtype=np.float32), 0.0, 1.0)
            empty = np.zeros(0, dtype=np.float32)
            trace = DirectRnnForwardTrace(
                masked_observation=masked_obs.copy(), previous_hidden=prev_hidden.copy(),
                effective_w_in=empty.reshape(0, 0), base_raw_preactivation=empty.copy(),
                base_normalized_preactivation=empty.copy(), base_candidate=empty.copy(),
                base_hidden=hidden.copy(), deep_inputs=(), deep_previous_states=(),
                deep_raw_preactivations=(), deep_normalized_preactivations=(),
                deep_candidates=(), deep_hidden=(), dropout_scales=(),
                output_hidden=hidden.copy(),
                output_mask=np.asarray(self.output_mask, dtype=float).copy(),
                gate=1.0, normalization_enabled=(), normalization_mode="none",
                normalization_target_rms=1.0, normalization_clip=0.0, normalization_eps=0.0,
                attended_observation=masked_obs.copy(),
                base_attention_weights=np.ones(self.input_size, dtype=np.float32),
                recurrent_core=OPENAI_FIVE_RECURRENT_CORE, lstm_forward=current,
            )
            return 1.0, hidden.astype(float), (), np.asarray(output, dtype=float), trace
        masked_obs = self._resize_local(
            np.asarray(source.masked_observation, dtype=float), self.input_size
        )
        attended_obs, base_attention_weights = self._feature_attention(
            masked_obs,
            getattr(self, "input_attention_q", None),
            getattr(self, "input_attention_b", None),
            enabled=bool(getattr(self, "attention_enabled", True)),
        )
        old_memory = getattr(source, "state_alias_memory_forward", None)
        current_memory: StateAliasingMemoryForward | None = None
        memory_injection = np.zeros(self.hidden_size, dtype=float)
        memory = getattr(self, "state_alias_memory", None)
        if isinstance(memory, StateAliasingMemoryState) and memory.enabled:
            frozen_tokens = (
                np.asarray(old_memory.tokens, dtype=float)
                if isinstance(old_memory, StateAliasingMemoryForward)
                else np.zeros((0, self.input_size), dtype=float)
            )
            current_memory = memory.read_frozen(masked_obs, frozen_tokens)
            memory_injection = self._resize_local(
                np.asarray(current_memory.injected, dtype=float), self.hidden_size
            )

        prev = self._resize_local(
            np.asarray(
                source.previous_hidden if previous_hidden is None else previous_hidden,
                dtype=float,
            ),
            self.hidden_size,
        )
        effective_w = np.asarray(self.w_in, dtype=float)
        base_raw = effective_w @ attended_obs + self.w_rec @ prev + self.b_hidden + memory_injection
        layer_count = 1 + len(tuple(getattr(self, "deep_w", ()) or ()))
        mode = _mandatory_hidden_normalization_mode(
            getattr(self, "hidden_normalization_mode", REQUIRED_HIDDEN_NORMALIZATION_MODE)
        )
        target_rms = float(getattr(self, "hidden_normalization_target_rms", 1.0) or 1.0)
        clip = float(getattr(self, "hidden_normalization_clip", 3.0) or 3.0)
        eps = float(getattr(self, "hidden_normalization_eps", 1e-5) or 1e-5)

        def normalized(values: np.ndarray) -> np.ndarray:
            return normalize_hidden(
                values, mode=mode, target_rms=target_rms, clip=clip, eps=eps
            )

        base_normalized = normalized(base_raw)
        base_candidate = np.tanh(base_normalized)
        base_hidden = self.memory_decay * prev + (1.0 - self.memory_decay) * base_candidate
        dropout_scales = tuple(
            self._resize_local(np.asarray(item, dtype=float), self.hidden_size)
            for item in tuple(getattr(source, "dropout_scales", ()) or ())
        )
        base_scale = dropout_scales[0] if dropout_scales else np.ones(self.hidden_size, dtype=float)
        layer_input = base_hidden * base_scale

        deep_w = tuple(getattr(self, "deep_w", ()) or ())
        deep_rec = tuple(getattr(self, "deep_rec", ()) or ())
        deep_b = tuple(getattr(self, "deep_b", ()) or ())
        supplied_deep = tuple(previous_deep_states or ())
        source_deep = tuple(getattr(source, "deep_previous_states", ()) or ())
        deep_inputs: list[np.ndarray] = []
        deep_previous: list[np.ndarray] = []
        deep_raw: list[np.ndarray] = []
        deep_normalized: list[np.ndarray] = []
        deep_candidates: list[np.ndarray] = []
        deep_hidden: list[np.ndarray] = []
        deep_attention_inputs: list[np.ndarray] = []
        deep_attention_weights: list[np.ndarray] = []
        current_deep_states: list[np.ndarray] = []
        for index, layer_w in enumerate(deep_w):
            layer_rec = (
                np.asarray(deep_rec[index], dtype=float)
                if index < len(deep_rec) else np.zeros((self.hidden_size, self.hidden_size), dtype=float)
            )
            layer_b = self._resize_local(
                np.asarray(deep_b[index], dtype=float) if index < len(deep_b) else np.zeros(0),
                self.hidden_size,
            )
            layer_prev_source = (
                supplied_deep[index]
                if index < len(supplied_deep)
                else source_deep[index] if index < len(source_deep) else np.zeros(self.hidden_size)
            )
            layer_prev = self._resize_local(np.asarray(layer_prev_source, dtype=float), self.hidden_size)
            attention_input = layer_input.copy()
            attention_q = tuple(getattr(self, "deep_attention_q", ()) or ())
            attention_b = tuple(getattr(self, "deep_attention_b", ()) or ())
            attended_layer, layer_weights = self._feature_attention(
                attention_input,
                attention_q[index] if index < len(attention_q) else None,
                attention_b[index] if index < len(attention_b) else None,
                enabled=bool(getattr(self, "attention_enabled", True)),
            )
            layer_raw = layer_w @ attended_layer + layer_rec @ layer_prev + layer_b
            layer_normalized = normalized(layer_raw)
            layer_candidate = np.tanh(layer_normalized)
            layer_hidden = self.memory_decay * layer_prev + (1.0 - self.memory_decay) * layer_candidate
            deep_attention_inputs.append(attention_input)
            deep_attention_weights.append(layer_weights.copy())
            deep_inputs.append(attended_layer.copy())
            deep_previous.append(layer_prev.copy())
            deep_raw.append(layer_raw.copy())
            deep_normalized.append(layer_normalized.copy())
            deep_candidates.append(layer_candidate.copy())
            deep_hidden.append(layer_hidden.copy())
            current_deep_states.append(layer_hidden.copy())
            scale = (
                dropout_scales[index + 1]
                if index + 1 < len(dropout_scales)
                else np.ones(self.hidden_size, dtype=float)
            )
            layer_input = layer_hidden * scale

        final_hidden = deep_hidden[-1] if deep_hidden else base_hidden
        output_hidden = layer_input if deep_w else base_hidden * base_scale
        output_mask = self._resize_local(
            np.asarray(getattr(source, "output_mask", self.output_mask), dtype=float),
            self.output_size,
        )
        output = (self.w_out @ output_hidden + self.b_out) * np.clip(output_mask, 0.0, 1.0)
        gate_logit = float(self.gate_w @ masked_obs + self.gate_b)
        gate = float(1.0 / (1.0 + np.exp(-np.clip(gate_logit, -60.0, 60.0))))
        current_forward = DirectRnnForwardTrace(
            masked_observation=masked_obs.copy(),
            previous_hidden=prev.copy(),
            effective_w_in=effective_w.copy(),
            base_raw_preactivation=base_raw.copy(),
            base_normalized_preactivation=base_normalized.copy(),
            base_candidate=base_candidate.copy(),
            base_hidden=base_hidden.copy(),
            deep_inputs=tuple(item.copy() for item in deep_inputs),
            deep_previous_states=tuple(item.copy() for item in deep_previous),
            deep_raw_preactivations=tuple(item.copy() for item in deep_raw),
            deep_normalized_preactivations=tuple(item.copy() for item in deep_normalized),
            deep_candidates=tuple(item.copy() for item in deep_candidates),
            deep_hidden=tuple(item.copy() for item in deep_hidden),
            dropout_scales=tuple(item.copy() for item in (
                dropout_scales if dropout_scales else (base_scale,)
            )),
            output_hidden=output_hidden.copy(),
            output_mask=output_mask.copy(),
            gate=gate,
            normalization_enabled=tuple(True for _ in range(layer_count)),
            normalization_mode=mode,
            normalization_target_rms=target_rms,
            normalization_clip=clip,
            normalization_eps=eps,
            attended_observation=attended_obs.copy(),
            base_attention_weights=base_attention_weights.copy(),
            deep_attention_inputs=tuple(item.copy() for item in deep_attention_inputs),
            deep_attention_weights=tuple(item.copy() for item in deep_attention_weights),
            state_alias_memory_forward=current_memory,
        )
        return gate, final_hidden.copy(), tuple(current_deep_states), output.copy(), current_forward

    @staticmethod
    def _resize_local(values: np.ndarray, size: int) -> np.ndarray:
        source = np.asarray(values, dtype=float).reshape(-1)
        result = np.zeros(max(0, int(size)), dtype=float)
        result[:min(result.size, source.size)] = source[:result.size]
        return result

    def mutate(self, rng: np.random.Generator, sigma: float) -> None:
        if str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE:
            return
        # Full-lifecycle RL has one explicit writer.  A proposal mutation is
        # neither part of its loss nor represented in the AdamW state, so it
        # must not silently perturb a live Direct-RNN between settled batches.
        if bool(getattr(self, "rnn_full_rl_enabled", False)):
            return
        strength = sigma * max(0.05, self.plasticity)
        self.w_in += rng.normal(0.0, strength, size=self.w_in.shape)
        self.w_rec += rng.normal(0.0, strength * 0.35, size=self.w_rec.shape)
        if self.w_lat is not None:
            self.w_lat += rng.normal(0.0, strength * 0.2, size=self.w_lat.shape)
            self.w_lat *= 0.995
        if getattr(self, "deep_w", None):
            self.deep_w = tuple(layer + rng.normal(0.0, strength * 0.45, size=layer.shape) for layer in self.deep_w)
            self.deep_rec = tuple(layer + rng.normal(0.0, strength * 0.2, size=layer.shape) for layer in self.deep_rec)
            self.deep_b = tuple(layer + rng.normal(0.0, strength * 0.45, size=layer.shape) for layer in self.deep_b)
        self.b_hidden += rng.normal(0.0, strength, size=self.b_hidden.shape)
        self.w_out += rng.normal(0.0, strength, size=self.w_out.shape)
        self.b_out += rng.normal(0.0, strength, size=self.b_out.shape)
        self.gate_w += rng.normal(0.0, strength * 0.5, size=self.gate_w.shape)
        self.gate_b += float(rng.normal(0.0, strength * 0.5))
        self.plasticity = float(np.clip(self.plasticity * rng.uniform(0.92, 1.08), 0.05, 2.5))
        self.memory_decay = float(np.clip(self.memory_decay + rng.normal(0.0, 0.02), 0.1, 0.98))
        self.w_rec *= 0.995

        if self.m1_component is not None:
            self.m1_component.mutate(rng, sigma)

        self.age += 1

    def apply_plasticity_rules(
        self,
        pre_activation: np.ndarray,
        post_activation: np.ndarray,
        grad_loss_w: np.ndarray | None = None,
        current_time: float = 0.0,
        reward_modulator: float = 0.0,
    ) -> None:
        if str(getattr(self, "recurrent_core", "legacy_rnn") or "legacy_rnn").strip().lower() == OPENAI_FIVE_RECURRENT_CORE:
            return
        # Hebbian/Oja/STDP is a legacy local writer.  In Full-RL mode the same
        # encoder weights are owned exclusively by the lifecycle batch loss.
        if bool(getattr(self, "rnn_full_rl_enabled", False)):
            return
        if self.plasticity_coeffs is None:
            return
        coeffs = self.plasticity_coeffs

        modulator = np.clip(reward_modulator, -2.0, 2.0)
        if abs(modulator) < 0.01:
            return

        stdp_matrix_total = np.zeros_like(self.w_in)
        if self.stdp_params is not None and len(self.spike_history) > 0:
            post = np.tanh(np.nan_to_num(
                np.asarray(post_activation, dtype=float).flatten()[:self.hidden_size],
                nan=0.0,
                posinf=20.0,
                neginf=-20.0,
            ))
            for past_time, past_pre in self.spike_history[-5:]:
                dt = current_time - past_time
                stdp_delta = stdp_update_scalar(dt, self.stdp_params)
                if abs(stdp_delta) > 1e-6:
                    pre = normalize_plasticity_vector(
                        past_pre,
                        size=self.input_size,
                        mode=str(getattr(self, "plasticity_input_normalization_mode", "soft_clip_v1") or "soft_clip_v1"),
                    )
                    stdp_matrix = stdp_delta * np.outer(
                        np.pad(post, (0, max(0, self.hidden_size - post.size)))[:self.hidden_size],
                        np.pad(pre, (0, max(0, self.input_size - pre.size)))[:self.input_size],
                    )
                    if stdp_matrix.shape == self.w_in.shape:
                        stdp_matrix_total += stdp_matrix

        delta, normalized_pre, stats = compose_stable_plasticity_update(
            self.w_in,
            pre_activation,
            post_activation,
            grad_loss_w,
            coeffs,
            modulator,
            input_mode=str(getattr(self, "plasticity_input_normalization_mode", "soft_clip_v1") or "soft_clip_v1"),
            max_update_norm=float(getattr(self, "plasticity_update_clip", 0.25) or 0.25),
            stdp_delta=stdp_matrix_total,
        )
        update = delta * float(np.clip(self.plasticity, 0.05, 2.5))
        if bool(getattr(self, "rnn_optimizer_enabled", False)):
            optimizer = self.apply_rnn_adamw_cosine(
                {"w_in": update}, source="local_plasticity"
            )
            update_norm = float(optimizer.get("optimizer_update_norm", 0.0) or 0.0)
            count = int(getattr(self, "plasticity_update_count", 0) or 0)
            ema = float(getattr(self, "plasticity_update_ema", 0.0) or 0.0)
            variance = float(getattr(self, "plasticity_update_var", 0.0) or 0.0)
            alpha = 0.05
            diff = update_norm - ema
            ema = ema + alpha * diff
            variance = (1.0 - alpha) * (variance + alpha * diff * diff)
            self.plasticity_update_count = count + int(bool(optimizer.get("updated", 0.0)))
            self.plasticity_update_ema = float(ema)
            self.plasticity_update_var = float(max(0.0, variance))
            stats["scaled_update_norm"] = update_norm
            stats["weight_norm"] = float(np.linalg.norm(self.w_in))
            stats["update_count"] = float(self.plasticity_update_count)
            stats["update_ema"] = self.plasticity_update_ema
            stats["update_var"] = self.plasticity_update_var
            stats.update({key: float(value) for key, value in optimizer.items()})
            self.plasticity_last_stats = {key: float(value) for key, value in stats.items()}
            self.last_spike_time = current_time
            self.spike_history.append((current_time, normalized_pre.copy()))
            if len(self.spike_history) > 20:
                self.spike_history = self.spike_history[-20:]
            return
        candidate_weights = self.w_in + update
        weight_cap = float(getattr(self, "plasticity_weight_norm_cap", 0.0) or 0.0)
        if weight_cap <= 0.0:
            weight_cap = max(1.0, float(np.sqrt(self.hidden_size) * 1.5))
            self.plasticity_weight_norm_cap = weight_cap
        candidate_norm = float(np.linalg.norm(candidate_weights))
        if candidate_norm > weight_cap:
            candidate_weights *= weight_cap / max(candidate_norm, 1e-12)
            update = candidate_weights - self.w_in
        self.w_in = candidate_weights
        # Hard bounds are a final safety net for old artifacts with oversized
        # weights; normal operation is governed by the update-norm cap above.
        self.w_in = np.nan_to_num(np.clip(self.w_in, -4.0, 4.0), nan=0.0, posinf=4.0, neginf=-4.0)
        update_norm = float(np.linalg.norm(update))
        count = int(getattr(self, "plasticity_update_count", 0) or 0)
        ema = float(getattr(self, "plasticity_update_ema", 0.0) or 0.0)
        variance = float(getattr(self, "plasticity_update_var", 0.0) or 0.0)
        alpha = 0.05
        diff = update_norm - ema
        ema = ema + alpha * diff
        variance = (1.0 - alpha) * (variance + alpha * diff * diff)
        self.plasticity_update_count = count + 1
        self.plasticity_update_ema = float(ema)
        self.plasticity_update_var = float(max(0.0, variance))
        stats["scaled_update_norm"] = update_norm
        stats["weight_norm"] = float(np.linalg.norm(self.w_in))
        stats["update_count"] = float(self.plasticity_update_count)
        stats["update_ema"] = self.plasticity_update_ema
        stats["update_var"] = self.plasticity_update_var
        self.plasticity_last_stats = {key: float(value) for key, value in stats.items()}
        self.last_spike_time = current_time
        self.spike_history.append((current_time, normalized_pre.copy()))
        if len(self.spike_history) > 20:
            self.spike_history = self.spike_history[-20:]

    def observe_usage(self, gate: float, hidden: np.ndarray, fitness: float | None = None) -> None:
        activation = float(np.mean(np.abs(hidden))) if hidden.size else 0.0
        self.gate_ema = 0.95 * self.gate_ema + 0.05 * float(gate)
        self.activation_ema = 0.95 * self.activation_ema + 0.05 * activation
        if fitness is not None:
            self.utility = 0.9 * self.utility + 0.1 * (float(gate) * float(fitness))
        if self.utility > 0.0 and self.gate_ema > 0.02:
            self.lifecycle = MODULE_LIFECYCLE_ACTIVE
        if self.utility > 0.0 and self.age >= 5 and self.plasticity < 0.35:
            self.lifecycle = MODULE_LIFECYCLE_CONSOLIDATED
        if self.gate_ema < 0.005 and self.age >= 5:
            self.lifecycle = MODULE_LIFECYCLE_PRUNING

    def apply_homeostatic_plasticity(self, target_activation: float = 0.35) -> None:
        # This routine writes w_in, w_rec, b_hidden and gate_b directly.  Do
        # not let it race the AdamW moments when Full-RL owns the module.
        if bool(getattr(self, "rnn_full_rl_enabled", False)):
            return
        activation_error = target_activation - self.activation_ema
        self.b_hidden += 0.01 * activation_error
        norm = float(np.linalg.norm(self.w_in))
        if norm > 0.0:
            self.w_in *= min(1.0, np.sqrt(self.w_in.size) / norm)
        rec_norm = float(np.linalg.norm(self.w_rec))
        if rec_norm > 0.0:
            self.w_rec *= min(1.0, np.sqrt(self.w_rec.size) * 0.25 / rec_norm)
        if self.gate_ema > 0.85 and self.activation_ema > target_activation * 1.8:
            self.gate_b -= 0.02
            self.plasticity = min(2.5, self.plasticity * 1.02)
        elif self.gate_ema < 0.02 and self.activation_ema < target_activation * 0.25:
            self.gate_b += 0.01


# ── Gating Functions ─────────────────────────────────────────────────────────


def sparsemax(logits: np.ndarray) -> np.ndarray:
    sorted_logits = np.sort(logits)[::-1]
    cumsum = np.cumsum(sorted_logits)
    k = np.arange(1, len(sorted_logits) + 1)
    threshold = (cumsum - 1.0) / k
    support = sorted_logits > threshold
    if not np.any(support):
        return np.ones_like(logits) / len(logits)
    k_star = int(np.max(np.where(support)))
    tau = threshold[k_star]
    return np.maximum(logits - tau, 0.0)


def top_k_gating(logits: np.ndarray, k: int = 2) -> np.ndarray:
    gates = np.zeros_like(logits)
    top_indices = np.argsort(logits)[-k:]
    top_values = logits[top_indices]
    exp_values = np.exp(top_values - np.max(top_values))
    softmax_values = exp_values / np.sum(exp_values)
    gates[top_indices] = softmax_values
    return gates


@dataclass
class MemoryNeuron:
    node_id: str
    trace_id: str
    obs_embedding: np.ndarray
    action_embedding: np.ndarray
    next_embedding: np.ndarray
    reward_ema: float
    td_ema: float
    prediction_error_ema: float
    strength: float = 1.0
    utility: float = 0.0
    forget_gate: float = 0.02
    plasticity: float = 0.1
    recurrent_state: float = 0.0
    age: int = 0
    support_count: int = 1
    memory_key_schema_version: int = MEMORY_KEY_SCHEMA_VERSION
    account_context: dict[str, float] = field(default_factory=dict)
    account_context_after: dict[str, float] = field(default_factory=dict)
    position_context: np.ndarray = field(default_factory=lambda: np.zeros(POSITION_MEMORY_KEY_SIZE, dtype=float), repr=False)
    # Multi-timescale context turns a raw snapshot into an episode signature.
    context_delta: np.ndarray = field(default_factory=lambda: np.zeros(MEMORY_KEY_SIZE, dtype=float), repr=False)
    short_context: np.ndarray = field(default_factory=lambda: np.zeros(MEMORY_KEY_SIZE, dtype=float), repr=False)
    regime_context: np.ndarray = field(default_factory=lambda: np.zeros(MEMORY_KEY_SIZE, dtype=float), repr=False)
    evidence_for: float = 0.0
    evidence_against: float = 0.0
    outcome_variance: float = 0.0
    uncertainty: float = 1.0
    last_seen_step: int = 0
    # Detailed memory upgrade: distinguish policy decisions from bootstrap,
    # risk overrides and forced management. Non-policy episodes remain useful
    # evidence, but they cannot directly train or promote the policy action path.
    action_origin: str = "policy"
    raw_utility: float = 0.0
    credit_weight: float = 1.0
    promotion_state: str = "tentative"
    support_policy_count: float = 0.0
    support_bootstrap_count: float = 0.0
    counterfactual_action_values: dict[str, float] = field(default_factory=dict)
    causal_lesson: dict[str, object] = field(default_factory=dict)

    def copy(self) -> "MemoryNeuron":
        return MemoryNeuron(
            node_id=self.node_id,
            trace_id=self.trace_id,
            obs_embedding=self.obs_embedding.copy(),
            action_embedding=self.action_embedding.copy(),
            next_embedding=self.next_embedding.copy(),
            reward_ema=float(self.reward_ema),
            td_ema=float(self.td_ema),
            prediction_error_ema=float(self.prediction_error_ema),
            strength=float(self.strength),
            utility=float(self.utility),
            forget_gate=float(self.forget_gate),
            plasticity=float(self.plasticity),
            recurrent_state=float(self.recurrent_state),
            age=int(self.age),
            support_count=int(getattr(self, "support_count", 1)),
            memory_key_schema_version=int(getattr(self, "memory_key_schema_version", 1)),
            account_context={str(k): float(v) for k, v in getattr(self, "account_context", {}).items()},
            account_context_after={str(k): float(v) for k, v in getattr(self, "account_context_after", {}).items()},
            position_context=np.asarray(getattr(self, "position_context", np.zeros(POSITION_MEMORY_KEY_SIZE)), dtype=float).copy(),
            context_delta=np.asarray(getattr(self, "context_delta", np.zeros(MEMORY_KEY_SIZE)), dtype=float).copy(),
            short_context=np.asarray(getattr(self, "short_context", np.zeros(MEMORY_KEY_SIZE)), dtype=float).copy(),
            regime_context=np.asarray(getattr(self, "regime_context", np.zeros(MEMORY_KEY_SIZE)), dtype=float).copy(),
            evidence_for=float(getattr(self, "evidence_for", max(0.0, getattr(self, "utility", 0.0)))),
            evidence_against=float(getattr(self, "evidence_against", max(0.0, -getattr(self, "utility", 0.0)))),
            outcome_variance=float(getattr(self, "outcome_variance", 0.0)),
            uncertainty=float(getattr(self, "uncertainty", 1.0)),
            last_seen_step=int(getattr(self, "last_seen_step", 0)),
            action_origin=str(getattr(self, "action_origin", "policy") or "policy"),
            raw_utility=float(getattr(self, "raw_utility", getattr(self, "utility", 0.0))),
            credit_weight=float(getattr(self, "credit_weight", 1.0)),
            promotion_state=str(getattr(self, "promotion_state", "tentative") or "tentative"),
            support_policy_count=float(getattr(self, "support_policy_count", 1.0 if str(getattr(self, "action_origin", "policy")) == "policy" else 0.0)),
            support_bootstrap_count=float(getattr(self, "support_bootstrap_count", 1.0 if str(getattr(self, "action_origin", "policy")) == "bootstrap" else 0.0)),
            counterfactual_action_values={str(k): float(v) for k, v in dict(getattr(self, "counterfactual_action_values", {}) or {}).items()},
            causal_lesson=copylib.deepcopy(dict(getattr(self, "causal_lesson", {}) or {})),
        )


