        if not isinstance(getattr(self, "conditioned_entry_expectancy", None), ConditionedEntryExpectancyLedger):
            self.conditioned_entry_expectancy = ConditionedEntryExpectancyLedger()
        self.conditioned_entry_expectancy.ensure_compatible()
        if not isinstance(getattr(self, "full_rl_expectancy_audit", None), ContextualExpectancyLedger):
            self.full_rl_expectancy_audit = ContextualExpectancyLedger()
