def build_mt5_curriculum_stages(config: AppConfig, rounds: int) -> list[MT5CurriculumStage]:
    max_positions = int(config.risk.max_positions)
    max_holding_bars = int(config.orders.max_holding_bars)
    if max_positions == 0:
        return [MT5CurriculumStage("full", 0, "2025.01.01", "2025.02.01", 0, max_holding_bars)]
    if rounds < 3:
        return [MT5CurriculumStage("full", 0, "2025.01.01", "2025.02.01", max_positions, max_holding_bars)]
    medium_start = max(1, int(np.ceil(rounds / 3.0)))
    full_start = max(medium_start + 1, int(np.ceil(rounds * 2.0 / 3.0)))
    return [
        MT5CurriculumStage("easy-week", 0, "2025.01.01", "2025.01.08", max(1, min(max_positions, 2)), min(max_holding_bars, 30)),
        MT5CurriculumStage("medium-half-month", medium_start, "2025.01.01", "2025.01.16", max(1, min(max_positions, 3)), min(max_holding_bars, 45)),
        MT5CurriculumStage("full-month", full_start, "2025.01.01", "2025.02.01", max_positions, max_holding_bars),
    ]


def mt5_curriculum_stage_for_round(stages: list[MT5CurriculumStage], round_index: int) -> tuple[int, MT5CurriculumStage]:
    active_index = 0
    for idx, stage in enumerate(stages):
        if round_index >= stage.start_round:
            active_index = idx
    return active_index, stages[active_index]


def _normalize_m1_backend(value: str | None = None) -> str:
    backend = str(value or "direct_rnn").strip().lower()
    aliases = {
        "rnn": "direct_rnn",
        "direct": "direct_rnn",
        "direct_head": "direct_rnn",
        "direct_rnn": "direct_rnn",
        "graph": "m1_graph",
        "m1": "m1_graph",
        "m1_graph": "m1_graph",
    }
    if backend not in aliases:
        raise ValueError("decision backend phai la direct_rnn hoac m1_graph")
    return aliases[backend]



def tao_policy_chuyen_gia_doc_lap(
    config: AppConfig,
    *,
    seed: int | None = None,
) -> Callable[[], "ChuyenGiaPolicy"]:
    """Tạo policy neural độc lập cho từng chuyên gia/context.

    Factory không nạp checkpoint cũ, không copy memory, trọng số, reward,
    fitness hoặc bias hành động. Mỗi lần gọi tạo một bộ não mới cùng contract
    119 đầu vào / 20 đầu ra nhưng độc lập hoàn toàn với expert khác.
    """
    rng = np.random.default_rng(seed)
    hidden_size = int(getattr(getattr(config, "model", None), "hidden_size", 24) or 24)
    hidden_layers = int(getattr(getattr(config, "model", None), "hidden_layers", 1) or 1)
    recurrent_core = str(
        getattr(getattr(config, "model", None), "recurrent_core", "")
        or getattr(getattr(config, "learning", None), "recurrent_core", "")
        or "legacy_rnn"
    ).strip().lower()
    if bool(getattr(getattr(config, "learning", None), "tier2_compact_core_enabled", False)):
        recurrent_core = "sgt_compact_xlstm"
    he_cfg = getattr(config, "he_chuyen_gia", None)
    five_agent_mode = str(getattr(he_cfg, "che_do_quyet_dinh", "") or "") == "nam_tac_nhan_dung_chung"
    policy_input_size = INPUT_COUNT

    def tao() -> "ChuyenGiaPolicy":
        policy_seed = int(rng.integers(0, 2**31 - 1))
        policy = ChuyenGiaPolicy.seed(
            input_size=policy_input_size,
            output_size=OUTPUT_COUNT,
            hidden_size=hidden_size,
            hidden_layers=hidden_layers,
            recurrent_core=recurrent_core,
            seed=policy_seed,
        )
        if five_agent_mode:
            # Đường Five không được tái gắn các mạng phụ Direct-RNN/TimingNet
            # sau khi seed đã cố ý loại chúng. Mọi tham số học được nằm trong
            # SharedFiveTradingPolicy và bộ tối ưu Five duy nhất.
            policy.timing_network_enabled = False
            policy.timing_network = None
            policy.curiosity_system = None
            policy.neural_utility = None
            policy.risk_cost_gate = None
            policy.action_parameter_head = None
            policy.reasoning_graph = None
            policy.graph_supernetwork = None
            policy.child_supernetwork_manager = None
            return policy
        # Role/context specialists can be created lazily after the initial
        # system migration.  Apply the current candidate contract here too;
        # otherwise late-born experts silently fall back to a TimingNet-off
        # policy even when the run config explicitly enabled it.
        learning = getattr(config, "learning", None)
        setattr(policy, "timing_network_enabled", bool(getattr(learning, "timing_network_enabled", False)))
        setattr(policy, "timing_network_action_scale", float(
            0.10 if getattr(learning, "timing_network_action_scale", None) is None else getattr(learning, "timing_network_action_scale")
        ))
        setattr(policy, "timing_network_update_scale", float(getattr(learning, "timing_network_update_scale", 0.25) or 0.25))
        setattr(policy, "timing_network_lifecycle_scale", float(getattr(learning, "timing_network_lifecycle_scale", 0.0) or 0.0))
        setattr(policy, "timing_network_learning_rate", float(getattr(learning, "timing_network_learning_rate", 0.0005) or 0.0005))
        setattr(policy, "timing_network_hidden_size", int(getattr(learning, "timing_network_hidden_size", 32) or 32))
        setattr(policy, "timing_network_embedding_size", int(getattr(learning, "timing_network_embedding_size", 16) or 16))
        setattr(policy, "timing_network_bptt_window", int(getattr(learning, "timing_network_bptt_window", 24) or 24))
        setattr(policy, "timing_network_sequence_length", int(getattr(learning, "timing_network_sequence_length", 32) or 32))
        setattr(policy, "timing_network_eligibility_decay", float(getattr(learning, "timing_network_eligibility_decay", 0.90) or 0.90))
        setattr(policy, "timing_network_gradient_clip", float(getattr(learning, "timing_network_gradient_clip", 1.0) or 1.0))
        setattr(policy, "timing_network_deceleration_enabled", bool(getattr(learning, "timing_network_deceleration_enabled", False)))
        setattr(policy, "timing_network_deceleration_horizon", int(getattr(learning, "timing_network_deceleration_horizon", 3) or 3))
        setattr(policy, "timing_network_deceleration_min_trend_strength", float(getattr(learning, "timing_network_deceleration_min_trend_strength", 0.18) or 0.18))
        setattr(policy, "timing_network_deceleration_min_drop", float(getattr(learning, "timing_network_deceleration_min_drop", 0.10) or 0.10))
        setattr(policy, "timing_network_deceleration_update_scale", float(getattr(learning, "timing_network_deceleration_update_scale", 0.25) or 0.25))
        setattr(policy, "timing_network_deceleration_learning_rate", float(getattr(learning, "timing_network_deceleration_learning_rate", 0.01) or 0.01))
        setattr(policy, "timing_network_deceleration_encoder_scale", float(getattr(learning, "timing_network_deceleration_encoder_scale", 0.10) or 0.10))
        setattr(policy, "timing_network_deceleration_l2", float(getattr(learning, "timing_network_deceleration_l2", 1e-4) or 0.0))
        for name in (
            "timing_network_regime_transition_enabled", "timing_network_regime_transition_horizons",
            "timing_network_regime_transition_update_scale", "timing_network_regime_transition_learning_rate",
            "timing_network_regime_transition_encoder_scale", "timing_network_regime_transition_l2",
            "semantic_input_routing_mode", "semantic_duplicate_entry_block_enabled",
            "semantic_risk_base_fraction", "semantic_risk_min_fraction",
            "semantic_risk_drawdown_soft_limit", "semantic_risk_drawdown_hard_limit",
            "semantic_risk_open_risk_soft_limit", "semantic_risk_open_risk_hard_limit",
            "input_lifecycle_encoder_learning_enabled", "input_lifecycle_encoder_batch_size",
            "input_lifecycle_encoder_min_abs_advantage", "input_lifecycle_encoder_min_sign_coherence",
            "direct_rnn_adamw_enabled", "direct_rnn_adamw_learning_rate",
            "direct_rnn_adamw_weight_decay", "direct_rnn_adam_beta1",
            "direct_rnn_adam_beta2", "direct_rnn_adam_epsilon",
            "direct_rnn_gradient_clip", "direct_rnn_cosine_min_factor",
            "direct_rnn_cosine_cycle_steps",
            "direct_rnn_full_rl_enabled", "direct_rnn_rl_batch_size",
            *STATE_ALIAS_MEMORY_CONFIG_NAMES,
            "direct_rnn_rl_min_abs_mean_advantage",
            "direct_rnn_rl_value_loss_weight", "direct_rnn_rl_entropy_weight",
            "direct_rnn_rl_exploration_enabled", "direct_rnn_rl_exploration_rate",
            "direct_rnn_rl_exploration_min_action_probability",
            "direct_rnn_rl_exploration_importance_clip", "direct_rnn_rl_exploration_seed",
            "direct_rnn_rl_delayed_reconciliation_enabled",
            "direct_rnn_rl_delayed_importance_clip",
            "direct_rnn_rl_delayed_policy_kl_temperature",
            "direct_rnn_rl_delayed_max_policy_js",
            "direct_rnn_rl_delayed_min_effective_weight",
            "direct_rnn_rl_delayed_lifecycle_encoder_credit_scale",
            "direct_rnn_rl_delayed_counterfactual_encoder_credit_scale",
            "direct_rnn_rl_delayed_preference_target_mode",
            "direct_rnn_rl_entry_preference_enabled", "direct_rnn_rl_entry_preference_loss_weight",
            "direct_rnn_rl_entry_preference_temperature",
            "direct_rnn_rl_rlhf_enabled", "direct_rnn_rl_rlhf_loss_weight",
            "direct_rnn_rl_rlhf_temperature", "direct_rnn_rl_rlhf_min_confidence",
            "direct_rnn_rl_entry_utility_mode",
            "direct_rnn_rl_timing_first_enabled", "direct_rnn_rl_timing_delay_bars",
            "direct_rnn_rl_timing_gate_loss_weight", "direct_rnn_rl_timing_margin_r",
            "direct_rnn_rl_timing_temperature_r", "direct_rnn_rl_timing_consensus_actions",
            "direct_rnn_rl_timing_freeze_entry_lifecycle_actor",
            *DIRECT_RNN_RETENTION_CONFIG_NAMES,
            "direct_rnn_rl_auxiliary_enabled", "direct_rnn_rl_auxiliary_loss_weight",
            "direct_rnn_rl_reconstruction_loss_weight",
            "direct_rnn_rl_counterfactual_representation_enabled",
            "direct_rnn_rl_counterfactual_representation_loss_weight",
            "direct_rnn_rl_counterfactual_representation_temperature",
            "direct_rnn_rl_advantage_mode", "direct_rnn_rl_critic_warmup_lifecycles",
            "direct_rnn_rl_critic_max_weight", "direct_rnn_rl_profit_floor",
            "direct_rnn_rl_loss_floor", "direct_rnn_rl_advantage_normalization_enabled",
            "direct_rnn_rl_advantage_norm_decay", "direct_rnn_rl_advantage_norm_scale_floor",
            "direct_rnn_rl_advantage_norm_clip",
            "direct_rnn_rl_temporal_bptt_steps",
            "tier1_vicreg_regularizer_enabled", "tier1_regularizer_enabled",
            "tier1_reservoir_buffer_enabled", "tier1_ewc_enabled",
            "tier2_compact_core_enabled", "tier2_coma_enabled", "tier2_rnd_enabled",
        ):
            setattr(policy, name, getattr(learning, name, getattr(policy, name)))
        policy.ensure_compatible()
        # The factory is also used by lazy experts before the MT5 profile is
        # installed. Apply the depth-resolved schedule here so a policy created
        # from ``model.hidden_layers`` never carries a stale seed-time
        # regularization schedule into its first decision.
        policy.configure_learning_integrity(learning)
        timing_network = getattr(policy, "timing_network", None)
        if timing_network is not None and hasattr(timing_network, "configure_optimizer"):
            optimizer_names = (
                "timing_network_swats_enabled", "timing_network_pid_enabled",
                "timing_network_adam_beta1", "timing_network_adam_beta2",
                "timing_network_adam_epsilon", "timing_network_adamw_enabled",
                "timing_network_adamw_weight_decay", "timing_network_cosine_annealing_enabled",
                "timing_network_cosine_min_factor", "timing_network_cosine_cycle_steps",
                "timing_network_projection_beta",
                "timing_network_projection_tolerance", "timing_network_switch_consecutive",
                "timing_network_min_projection_steps", "timing_network_target_alignment",
                "timing_network_sgd_eta_min", "timing_network_sgd_eta_max",
                "timing_network_sgd_eta_init_factor", "timing_network_pid_kp",
                "timing_network_pid_ki", "timing_network_pid_kd",
                "timing_network_pid_integral_limit", "timing_network_pid_derivative_ema",
                "timing_network_pid_deadband", "timing_network_pid_r_target",
                "timing_network_pid_r_scale_floor", "timing_network_pid_alignment_weight",
                "timing_network_pid_r_weight", "timing_network_pid_bad_steps_to_freeze",
                "timing_network_pid_recovery_steps", "timing_network_pid_cooldown_steps",
                "timing_network_pid_fallback_to_adam",
            )
            timing_network.configure_optimizer({
                name: value
                for name in optimizer_names
                for value in (getattr(learning, name, None),)
                if value is not None
            })
        return policy

    return tao


def tao_he_chuyen_gia_mot_context_mot_policy(
    config: AppConfig,
    *,
    seed: int | None = None,
):
    """Khởi tạo hệ quyết định; cấu hình mới dùng một bộ não chung duy nhất."""
    from .he_chuyen_gia_ngu_canh import CauHinhHeChuyenGia, HeChuyenGiaMotContextMotPolicy

    cau_hinh = getattr(config, "he_chuyen_gia", CauHinhHeChuyenGia())
    if not isinstance(cau_hinh, CauHinhHeChuyenGia):
        cau_hinh = CauHinhHeChuyenGia()
    if not bool(cau_hinh.bat):
        raise ValueError("he_chuyen_gia.bat phai = true")
    return HeChuyenGiaMotContextMotPolicy(
        cau_hinh=cau_hinh,
        tao_policy=tao_policy_chuyen_gia_doc_lap(config, seed=seed),
    )


def _context_expert_architecture_mismatches(system: object, config: AppConfig) -> list[str]:
    """Return trained policy owners that do not match the requested topology.

    Width/depth are tensor-shape choices, not live hyperparameters.  Allowing a
    resume run to silently retain an old checkpoint after YAML changes to a
    different depth makes the configuration deceptive; resizing in place would
    instead discard learned recurrent tensors.  Fresh systems are created from
    the factory and therefore have no mismatch.
    """

    requested_width = int(getattr(getattr(config, "model", None), "hidden_size", 0) or 0)
    requested_depth = int(getattr(getattr(config, "model", None), "hidden_layers", 0) or 0)
    requested_core = str(
        getattr(getattr(config, "model", None), "recurrent_core", "legacy_rnn") or "legacy_rnn"
    ).strip().lower()
    if requested_width < 1 or requested_depth < 1:
        return []
    experts = getattr(system, "experts", {}) or {}
    if not isinstance(experts, Mapping):
        return []
    mismatches: list[str] = []
    for expert_name, expert in sorted(experts.items(), key=lambda item: str(item[0])):
        policy = getattr(expert, "policy", None)
        modules = tuple(getattr(policy, "modules", ()) or ())
        for index, module in enumerate(modules):
            observed_width = int(getattr(module, "hidden_size", 0) or 0)
            observed_depth = 1 + len(getattr(module, "deep_w", ()) or ())
            observed_core = str(
                getattr(module, "recurrent_core", "legacy_rnn") or "legacy_rnn"
            ).strip().lower()
            if (
                observed_width != requested_width
                or observed_depth != requested_depth
                or observed_core != requested_core
            ):
                mismatches.append(
                    f"{expert_name}/module[{index}]={observed_core}:{observed_depth}x{observed_width}"
                )
    return mismatches


def _require_context_expert_architecture_match(
    system: object,
    config: AppConfig,
    *,
    artifact_path: str | Path,
) -> None:
    mismatches = _context_expert_architecture_mismatches(system, config)
    if not mismatches:
        return
    requested = (
        f"{str(getattr(config.model, 'recurrent_core', 'legacy_rnn'))}:"
        f"{int(config.model.hidden_layers)}x{int(config.model.hidden_size)}"
    )
    preview = "; ".join(mismatches[:6])
    suffix = "; ..." if len(mismatches) > 6 else ""
    raise ValueError(
        "checkpoint architecture does not match config.model "
        f"(requested {requested}; observed {preview}{suffix}). "
        "Use --fresh-system or a distinct --output to create an artifact with the new depth/width; "
        f"the existing checkpoint is preserved: {Path(artifact_path)}"
    )


def tai_he_chuyen_gia_mot_context_mot_policy(
    path: str | Path,
    config: AppConfig,
    *,
    seed: int | None = None,
):
    """Đọc artifact hệ chuyên gia; từ chối mọi artifact ngoài contract."""
    from .he_chuyen_gia_ngu_canh import HeChuyenGiaMotContextMotPolicy

    p = Path(path)
    file_size = p.stat().st_size if p.is_file() else 0
    with p.open("rb") as handle:
        if file_size > 5 * 1024 * 1024:
            from .progress_reader import ProgressFileReader
            reader = ProgressFileReader(handle, file_size, label=f"Nap Checkpoint ({p.name})")
            system = load_pickle_with_removed_context_structural_migration(reader)
            reader.finish()
        else:
            system = load_pickle_with_removed_context_structural_migration(handle)
    if not isinstance(system, HeChuyenGiaMotContextMotPolicy):
        raise TypeError(
            "artifact khong phai he mot-context-mot-chuyen-gia; "
            "artifact ngoài contract bị từ chối và không được phép nạp"
        )
    # Migration must see the current profile, not the configuration serialized
    # inside the seed. Previously ensure_compatible() ran first, so an artifact
    # written with volatile_subexperts_bat=false never created the three new
    # owners even though the live classifier was rebound later and emitted
    # subtype labels. Registry.owner then silently fell back to CTX_VOLATILE.
    current_expert_config = getattr(config, "he_chuyen_gia", None)
    if current_expert_config is not None:
        for component in (
            system,
            getattr(system, "nhan_dien", None),
            getattr(system, "registry", None),
        ):
            if component is not None and hasattr(component, "cau_hinh"):
                component.cau_hinh = current_expert_config
    system.gan_factory_tao_policy(tao_policy_chuyen_gia_doc_lap(config, seed=seed))
    system.ensure_compatible()
    return system

def backup_context_expert_artifacts(output_path: str | Path) -> dict[str, str]:
    """Copy existing context-expert artifact/registry before an overwrite."""
    output = Path(output_path)
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backups: dict[str, str] = {}
    for label, path in (
        ("policy", output),
        ("registry", output.with_suffix(".registry.json")),
    ):
        if not path.exists() or not path.is_file():
            continue
        backup = path.with_name(f"{path.stem}.rollback.{timestamp}{path.suffix}")
        shutil.copy2(path, backup)
        backups[label] = str(backup)
    return backups


def archive_context_expert_runtime_artifacts(
    output_path: str | Path,
    *,
    evaluator: object,
    metrics: object | None,
) -> dict[str, str]:
    """Persist the exact mutable MT5 evidence beside one candidate artifact.

    The portable tester reuses ``Common\\Files`` on the next run.  A checkpoint
    alone therefore cannot later answer which feature rows, bridge actions or
    counterfactual paths produced its weights.  Copy the immutable end-of-run
    files before another candidate can overwrite them.  This is observability
    only: it never feeds an archive back into learning or inference.
    """
    output = Path(output_path)
    archive_dir = output.with_name(f"{output.stem}.runtime")
    archive_dir.mkdir(parents=True, exist_ok=True)
    config = getattr(evaluator, "config", None)
    latest_runtime_file = getattr(evaluator, "_latest_runtime_file", None)

    def _runtime_path(filename: object) -> object:
        if not callable(latest_runtime_file) or not str(filename or "").strip():
            return None
        try:
            return latest_runtime_file(str(filename))
        except (OSError, TypeError, ValueError):
            return None

    sources: dict[str, object] = {
        "report": getattr(metrics, "report_path", None),
        "execution_ledger": getattr(metrics, "execution_ledger_path", None),
        "feature_audit": getattr(metrics, "feature_audit_path", None),
        "bridge": _runtime_path(getattr(config, "bridge_file", "")),
        "request": _runtime_path(getattr(config, "request_file", "")),
        "action": _runtime_path(getattr(config, "action_file", "")),
        "entry_preference": _runtime_path(getattr(config, "entry_preference_file", "")),
    }
    archived: dict[str, str] = {}
    for label, raw_source in sources.items():
        if raw_source is None:
            continue
        source = Path(raw_source)
        if not source.is_file():
            continue
        destination = archive_dir / f"{label}{source.suffix}"
        temporary = destination.with_suffix(destination.suffix + ".tmp")
        try:
            shutil.copy2(source, temporary)
            temporary.replace(destination)
        except OSError:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                pass
            raise
        archived[label] = str(destination)
    return archived


def resolve_context_expert_resume_path(
    output_path: str | Path,
    *,
    seed_system_path: str | Path | None = None,
    resume_existing: bool = True,
) -> Path | None:
    """Resolve the authoritative seed without silently restarting a trained system."""
    if seed_system_path is not None:
        explicit = Path(seed_system_path)
        if not explicit.is_file():
            raise FileNotFoundError(f"khong tim thay seed system: {explicit}")
        return explicit
    output = Path(output_path)
    if bool(resume_existing) and output.is_file():
        return output
    return None


def _reset_context_expert_runtime_for_new_mt5_session(system: object) -> bool:
    """Clear serialized transient state before a continuation backtest.

    Checkpoints intentionally persist weights and lifecycle evidence, but RNN
    activations, M15-regime cache and trace-routing caches belong to the MT5
    session that produced the checkpoint. Reusing them at a different
    ``from_date`` makes continuation training start from a hidden state that
    frozen OOS correctly discards, so train and evaluation can emit different
    actions on the same market window.
    """
    reset_runtime = getattr(system, "reset_runtime_state", None)
    if not callable(reset_runtime):
        return False
    reset_runtime()
    return True


def _compact_context_expert_artifact_state(
    policy,
    *,
    max_archived_traces: int = 256,
    drop_trace_archive: bool = False,
    learning_settings: object | None = None,
) -> None:
    """Keep lifecycle memory while bounding duplicated immutable trace state.

    The execution cache and causal archive both hold full ``StepTrace`` objects
    (including graph telemetry).  Persisting thousands of those objects adds
    hundreds of MB without adding learning evidence: lifecycle memory,
    recovery cells, contextual expectancy and the causal ledger are stored
    separately.  Keep a recent replay window and let the live JSONL stream
    remain the complete observability record.
    """
    def _compact_graph_record(record: object) -> dict[str, object]:
        """Retain lifecycle-credit fields while dropping bulky telemetry."""
        if not isinstance(record, Mapping):
            return {}
        compact: dict[str, object] = {}
        for key in (
            "graph_id",
            "graph_label",
            "schema_version",
            "active_node_count",
            "active_edge_count",
            "active_neuron_ids",
            "active_edge_ids",
            "region_activity",
        ):
            if key not in record:
                continue
            value = record[key]
            if key == "active_neuron_ids":
                value = tuple(str(item) for item in tuple(value or ())[:128])
            elif key == "active_edge_ids":
                value = tuple(str(item) for item in tuple(value or ())[:192])
            elif key == "region_activity" and isinstance(value, Mapping):
                value = {str(name): float(raw) for name, raw in list(value.items())[:24]}
            compact[key] = value
        controllers = record.get("controllers")
        if isinstance(controllers, Mapping):
            compact_controllers: dict[str, dict[str, object]] = {}
            for name, raw_controller in list(controllers.items())[:8]:
                if not isinstance(raw_controller, Mapping):
                    continue
                controller: dict[str, object] = {}
                for key in ("active_neuron_ids", "active_edge_ids", "node_values", "edge_contributions"):
                    value = raw_controller.get(key)
                    if key == "active_neuron_ids":
                        controller[key] = tuple(str(item) for item in tuple(value or ())[:128])
                    elif key == "active_edge_ids":
                        controller[key] = tuple(str(item) for item in tuple(value or ())[:192])
                    elif isinstance(value, Mapping):
                        limit = 128 if key == "node_values" else 192
                        controller[key] = {str(item): value[item] for item in list(value)[:limit]}
                compact_controllers[str(name)] = controller
            compact["controllers"] = compact_controllers
        return compact

    def _compact_trace(trace: object) -> object:
        if not isinstance(trace, StepTrace):
            return trace
        graph_traces = dict(getattr(trace, "graph_traces", {}) or {})
        compact_graphs = {
            str(graph_id): _compact_graph_record(record)
            for graph_id, record in list(graph_traces.items())[:12]
        }
        return replace(trace, graph_traces=compact_graphs)

    limit = max(16, int(max_archived_traces))
    strip_five_optimizer_state = bool(getattr(
        learning_settings,
        "five_rlhf_strip_optimizer_state_for_oos",
        False,
    ))
    optimizer_state_stripped_count = 0
    for expert in getattr(policy, "experts", {}).values():
        local = getattr(expert, "policy", None)
        if local is None:
            continue
        # Re-apply passive quotas before pickle. Structural ``develop()`` is
        # never a persistence side effect: saving a candidate must not mutate
        # it after the last audited lifecycle.
        configure_integrity = getattr(local, "configure_learning_integrity", None)
        if learning_settings is not None and callable(configure_integrity):
            configure_integrity(learning_settings)
        else:
            memory = getattr(local, "memory_supernet", None)
            ensure_memory = getattr(memory, "ensure_compatible", None)
            if callable(ensure_memory):
                ensure_memory()
        archive = getattr(local, "_causal_trace_archive", None)
        if drop_trace_archive:
            # Lifecycle ledger/expectancy and observability JSONL are the
            # durable learning evidence.  Raw StepTrace objects duplicate
            # graph/controller arrays and can exceed hundreds of MB after a
            # long MT5 window; replay can still be run from seed/candidate
            # decisions on the frozen window.
            local._causal_trace_archive = {}
            archive = None
        if isinstance(archive, dict) and len(archive) > limit:
            keys = list(archive)[-limit:]
            local._causal_trace_archive = {key: _compact_trace(archive[key]) for key in keys}
        elif isinstance(archive, dict):
            local._causal_trace_archive = {key: _compact_trace(value) for key, value in archive.items()}
        # The archive is the persisted fallback used after a restart.  The
        # in-process cache is a duplicate and can be rebuilt on the next run.
        if isinstance(getattr(local, "_execution_trace_cache", None), dict):
            local._execution_trace_cache = {}
        # The MT5 tester has already closed before this persistence boundary.
        # Counterfactual rows that matured were converted to replay items and
        # removed; the remaining records can never receive another path row
        # from that closed tester.  Persisting their full immutable
        # DirectRnnForwardTrace duplicated hundreds of MB without preserving
        # usable learning evidence.
        if isinstance(getattr(local, "_entry_preference_trace_cache", None), dict):
            local._entry_preference_trace_cache = {}
        # Five pattern anchors are likewise session-local.  Any label that did
        # not mature before the tester closed can never be completed after
        # restart, and persisting 5 x hidden/cell 4096 snapshots only bloats
        # the checkpoint with unusable runtime state.
        if isinstance(getattr(local, "_five_pattern_anchor_cache", None), dict):
            local._five_pattern_anchor_cache = {}
        if isinstance(getattr(local, "_five_pattern_settled_sequences", None), set):
            local._five_pattern_settled_sequences = set()
        if strip_five_optimizer_state:
            # FiveAdam keeps full-size m/v tensors for every trainable Five
            # parameter. They are useful for continuation training but are
            # not needed by frozen-OOS evaluation after this MT5 tester closes.
            # This is deliberately opt-in: silently resetting Adam moments
            # would make a training resume scientifically incomparable.
            trainer = getattr(local, "five_ppo_trainer", None)
            optimizer = getattr(trainer, "optimizer", None)
            optimizer_state = getattr(optimizer, "state", None)
            if isinstance(optimizer_state, dict) and optimizer_state:
                optimizer_state.clear()
                optimizer_state_stripped_count += 1

    # Persist a forensic marker so a stripped artifact cannot be mistaken for
    # a continuation-training checkpoint. Preserve an existing marker when a
    # second compaction pass sees an already-stripped object.
    previous_strip_marker = bool(getattr(
        policy, "_five_rlhf_optimizer_state_stripped", False
    ))
    setattr(
        policy,
        "_five_rlhf_optimizer_state_stripped",
        bool(previous_strip_marker or optimizer_state_stripped_count > 0),
    )
    setattr(
        policy,
        "_five_rlhf_optimizer_state_stripped_count",
        int(max(
            optimizer_state_stripped_count,
            int(getattr(policy, "_five_rlhf_optimizer_state_stripped_count", 0) or 0),
        )),
    )

    # These maps route callbacks only inside the just-finished tester session.
    # Lifecycle/expectancy ledgers and replay stores above remain persistent.
    for name in (
        "_trace_to_expert", "_trace_to_timing_network_trace",
        "_trace_to_selector_policy", "_trace_to_selector_context",
        "_trace_to_selector_evidence_group", "_bridge_finalized_trace_ids",
        "_expert_live_writers",
    ):
        value = getattr(policy, name, None)
        if isinstance(value, dict):
            setattr(policy, name, {})


def _ensure_rlhf_optimizer_state_available_for_update(
    policy: object,
    learning_settings: object | None,
) -> None:
    """Guard FiveAdam resume semantics and optionally reset research state.

    A candidate/OOS artifact may deliberately omit FiveAdam's moment tensors
    to keep persistence within the Windows disk budget. Such an artifact is
    not a continuation checkpoint. The default remains fail-closed; an
    explicit research-only setting may instead start a fresh lazy optimizer
    state while preserving a forensic marker in the runtime metrics.
    """
    if not (
        bool(getattr(learning_settings, "five_rlhf_policy_update_enabled", False))
        or bool(getattr(learning_settings, "five_codex_teacher_enabled", False))
        # Missing fields in legacy/frozen test settings do not request an
        # optimizer writer. Real loaded configs carry this field explicitly.
        or bool(getattr(learning_settings, "five_codex_teacher_auto_connect", False))
    ):
        return
    if bool(getattr(policy, "_five_rlhf_optimizer_state_stripped", False)):
        allow_reinitialization = bool(getattr(
            learning_settings,
            "five_rlhf_allow_optimizer_state_reinitialization_for_research",
            False,
        ))
        if not allow_reinitialization:
            raise ValueError(
                "RLHF policy update cannot resume from an OOS artifact with "
                "FiveAdam optimizer state stripped; use the immutable source checkpoint "
                "or explicitly enable research optimizer reinitialization"
            )

        # Do not allocate the full m/v tensors before the first gradient. A
        # stripped artifact has no usable moments to preserve; FiveAdam.step
        # creates fresh zero moments for each trainable parameter lazily. Clear
        # every expert-local trainer defensively because the marker lives on
        # the context-expert system rather than on one policy owner.
        reset_count = 0
        experts = getattr(policy, "experts", {})
        local_policies = [
            getattr(expert, "policy", None)
            for expert in (experts.values() if isinstance(experts, dict) else ())
        ]
        local_policies.append(policy)
        seen: set[int] = set()
        for local in local_policies:
            if local is None or id(local) in seen:
                continue
            seen.add(id(local))
            trainer = getattr(local, "five_ppo_trainer", None)
            optimizer = getattr(trainer, "optimizer", None)
            state = getattr(optimizer, "state", None)
            if isinstance(state, dict):
                state.clear()
                reset_count += 1
        setattr(policy, "_five_rlhf_optimizer_state_reinitialized", True)
        setattr(
            policy,
            "_five_rlhf_optimizer_state_reinitialization_count",
            int(max(1, reset_count)),
        )


def _cau_hinh_policy_chuyen_gia_cho_mt5(policy, config: AppConfig) -> None:
    """Cấu hình từng policy owner; tuyệt đối không tạo graph/global memory chung."""
    from .he_chuyen_gia_ngu_canh import CauHinhHeChuyenGia

    config_expert = getattr(config, "he_chuyen_gia", CauHinhHeChuyenGia())
    if not isinstance(config_expert, CauHinhHeChuyenGia):
        config_expert = CauHinhHeChuyenGia()
    learning_cfg = getattr(config, "learning", None)
    online_update_scale = float(np.clip(
        float(getattr(learning_cfg, "mt5_online_update_scale", 1.0)),
        0.0,
        1.0,
    ))
    negative_context_credit_multiplier = float(np.clip(
        float(getattr(learning_cfg, "negative_context_credit_multiplier", NEGATIVE_CONTEXT_CREDIT_MULTIPLIER) or 0.0),
        0.0,
        16.0,
    ))
    negative_entry_replacement_gain = float(np.clip(
        float(getattr(learning_cfg, "negative_entry_replacement_gain", 3.0) or 0.0),
        0.0,
        8.0,
    ))
    stp_input_clip = float(np.clip(
        float(getattr(learning_cfg, "stp_input_clip", 50.0) or 50.0),
        0.1,
        50.0,
    ))
    plasticity_input_normalization_mode = str(
        getattr(learning_cfg, "plasticity_input_normalization_mode", "raw") or "raw"
    ).strip().lower()
    if plasticity_input_normalization_mode not in {"raw", "tanh_v1", "soft_clip_v1", "groupwise_v2", "groupwise_mtf_v3", "structure_aware_v4"}:
        plasticity_input_normalization_mode = "raw"
    plasticity_update_clip = float(np.clip(
        float(getattr(learning_cfg, "plasticity_update_clip", 0.25) or 0.25),
        0.0,
        10.0,
    ))
    # This is intentionally not a profile switch. Loading a legacy pickle or
    # invoking this helper without AppConfig validation must still produce a
    # regularized Direct-RNN for every configured hidden block.
    hidden_normalization_mode = _mandatory_hidden_normalization_mode(
        getattr(learning_cfg, "hidden_normalization_mode", REQUIRED_HIDDEN_NORMALIZATION_MODE)
    )
    hidden_normalization_target_rms = float(np.clip(
        float(getattr(learning_cfg, "hidden_normalization_target_rms", 1.0) or 1.0),
        1e-6,
        10.0,
    ))
    hidden_normalization_clip = float(np.clip(
        float(getattr(learning_cfg, "hidden_normalization_clip", 3.0) or 3.0),
        1e-6,
        20.0,
    ))
    hidden_normalization_eps = float(np.clip(
        float(getattr(learning_cfg, "hidden_normalization_eps", 1e-5) or 1e-5),
        1e-9,
        1.0,
    ))
    configured_hidden_layers = max(
        1,
        int(getattr(getattr(config, "model", None), "hidden_layers", 1) or 1),
    )
    hidden_normalization_enabled = True
    hidden_normalization_layers = tuple(True for _ in range(configured_hidden_layers))
    hidden_dropout_enabled = True
    hidden_dropout_rates = mandatory_layerwise_rates(
        getattr(learning_cfg, "hidden_dropout_rates", REQUIRED_HIDDEN_DROPOUT_RATES),
        configured_hidden_layers,
    )
    hidden_dropout_seed = max(0, int(getattr(learning_cfg, "hidden_dropout_seed", 0) or 0))
    hidden_dropout_train_only = True
    output_normalization_mode = str(getattr(learning_cfg, "output_normalization_mode", "raw") or "raw").strip().lower()
    if output_normalization_mode not in {"raw", "rms_v1", "layernorm_v1"}:
        output_normalization_mode = "raw"
    output_normalization_target_rms = float(np.clip(
        float(getattr(learning_cfg, "output_normalization_target_rms", 0.70) or 0.70),
        1e-6,
        10.0,
    ))
    output_normalization_clip = float(np.clip(
        float(getattr(learning_cfg, "output_normalization_clip", 3.0) or 3.0),
        1e-6,
        20.0,
    ))
    execution_parameter_activation_mode = normalize_parameter_activation_mode(
        getattr(learning_cfg, "execution_parameter_activation_mode", "legacy_tanh_v1")
    )
    semantic_input_routing_mode = str(
        getattr(learning_cfg, "semantic_input_routing_mode", SEMANTIC_INPUT_ROUTING_LEGACY)
        or SEMANTIC_INPUT_ROUTING_LEGACY
    ).strip().lower()
    if semantic_input_routing_mode not in SEMANTIC_INPUT_ROUTING_MODES:
        semantic_input_routing_mode = SEMANTIC_INPUT_ROUTING_LEGACY
    semantic_duplicate_entry_block_enabled = bool(
        getattr(learning_cfg, "semantic_duplicate_entry_block_enabled", True)
    )
    semantic_risk_base_fraction = float(np.clip(
        getattr(learning_cfg, "semantic_risk_base_fraction", 0.50) or 0.50, 0.27, 0.73
    ))
    semantic_risk_min_fraction = float(np.clip(
        getattr(learning_cfg, "semantic_risk_min_fraction", 0.30) or 0.30,
        0.27, semantic_risk_base_fraction,
    ))
    semantic_risk_drawdown_soft_limit = float(np.clip(
        getattr(learning_cfg, "semantic_risk_drawdown_soft_limit", 0.06) or 0.06, 1e-6, 1.0
    ))
    semantic_risk_drawdown_hard_limit = float(np.clip(
        getattr(learning_cfg, "semantic_risk_drawdown_hard_limit", 0.12) or 0.12,
        semantic_risk_drawdown_soft_limit, 1.0,
    ))
    semantic_risk_open_risk_soft_limit = float(np.clip(
        getattr(learning_cfg, "semantic_risk_open_risk_soft_limit", 0.60) or 0.60, 1e-6, 2.0
    ))
    semantic_risk_open_risk_hard_limit = float(np.clip(
        getattr(learning_cfg, "semantic_risk_open_risk_hard_limit", 0.90) or 0.90,
        semantic_risk_open_risk_soft_limit, 2.0,
    ))
    timing_network_enabled = bool(getattr(learning_cfg, "timing_network_enabled", False))
    timing_network_action_scale = float(np.clip(
        float(0.10 if getattr(learning_cfg, "timing_network_action_scale", None) is None else getattr(learning_cfg, "timing_network_action_scale")),
        0.0,
        0.50,
    ))
    timing_network_update_scale = float(np.clip(
        float(getattr(learning_cfg, "timing_network_update_scale", 0.25) or 0.25),
        0.0,
        1.0,
    ))
    timing_network_lifecycle_scale = float(np.clip(
        float(getattr(learning_cfg, "timing_network_lifecycle_scale", 0.0) or 0.0),
        0.0,
        1.0,
    ))
    timing_network_learning_rate = float(np.clip(
        float(getattr(learning_cfg, "timing_network_learning_rate", 0.0005) or 0.0005),
        1e-6,
        0.02,
    ))
    timing_network_hidden_size = max(4, int(getattr(learning_cfg, "timing_network_hidden_size", 32) or 32))
    timing_network_embedding_size = max(4, int(getattr(learning_cfg, "timing_network_embedding_size", 16) or 16))
    timing_network_bptt_window = int(np.clip(int(getattr(learning_cfg, "timing_network_bptt_window", 24) or 24), 1, 128))
    timing_network_sequence_length = int(np.clip(int(getattr(learning_cfg, "timing_network_sequence_length", 32) or 32), 1, 128))
    timing_network_eligibility_decay = float(np.clip(
        float(getattr(learning_cfg, "timing_network_eligibility_decay", 0.90) or 0.90),
        0.5,
        0.999,
    ))
    timing_network_gradient_clip = float(np.clip(
        float(getattr(learning_cfg, "timing_network_gradient_clip", 1.0) or 1.0),
        0.05,
        10.0,
    ))
    timing_network_deceleration_enabled = bool(getattr(learning_cfg, "timing_network_deceleration_enabled", False))
    timing_network_deceleration_horizon = int(np.clip(
        int(getattr(learning_cfg, "timing_network_deceleration_horizon", 3) or 3), 1, 12
    ))
    timing_network_deceleration_min_trend_strength = float(np.clip(
        float(getattr(learning_cfg, "timing_network_deceleration_min_trend_strength", 0.18) or 0.18), 0.01, 1.0
    ))
    timing_network_deceleration_min_drop = float(np.clip(
        float(getattr(learning_cfg, "timing_network_deceleration_min_drop", 0.10) or 0.10), 0.005, 1.0
    ))
    timing_network_deceleration_update_scale = float(np.clip(
        float(getattr(learning_cfg, "timing_network_deceleration_update_scale", 0.25) or 0.25), 0.01, 1.0
    ))
    timing_network_deceleration_learning_rate = float(np.clip(
        float(getattr(learning_cfg, "timing_network_deceleration_learning_rate", 0.01) or 0.01), 1e-5, 0.05
    ))
    timing_network_deceleration_encoder_scale = float(np.clip(
        float(getattr(learning_cfg, "timing_network_deceleration_encoder_scale", 0.10) or 0.10), 0.0, 1.0
    ))
    timing_network_deceleration_l2 = float(np.clip(
        float(getattr(learning_cfg, "timing_network_deceleration_l2", 1e-4) or 0.0), 0.0, 0.1
    ))
