    # Frozen inference must not recruit lazy context-role specialists.  The
    # old route treated registry growth as harmless runtime setup, but that
    # changes the policy and invalidates a no-learning control.  Training
    # explicitly opts in through the MT5 config.
    learning_enabled = bool(getattr(config, "mt5_learning_enabled", getattr(config, "learning_enabled", True)))
    setattr(policy, "_learning_enabled", learning_enabled)
