    configure_risk_caps = getattr(policy, "configure_risk_caps", None)
    if callable(configure_risk_caps):
        configure_risk_caps(getattr(config, "risk", None))
    for expert in policy.experts.values():
        local = expert.policy
        local.ensure_compatible()
        # Each context owner has its own candidate-growth scope. This is not a
        # global trial and never shares neurons/edges across experts.
        local.graph_trial_mode = True
        local.graph_trial_id = f"owner-{expert.ma_chuyen_gia}-{time.time_ns()}"
        local.owner_local_mode = True
        setattr(local, "_mt5_online_update_scale", online_update_scale)
        setattr(local, "_negative_context_credit_multiplier", negative_context_credit_multiplier)
