def _v186_canonical_module(self: ChuyenGiaPolicy) -> ModuleState | None:
    modules = list(getattr(self, "modules", ()) or ())
    if not modules:
        return None
    return next(
        (module for module in modules if str(getattr(module, "role", "")) == "m1_thinking_core"),
        modules[0],
    )


def _v186_bank_seed(self: ChuyenGiaPolicy, module: ModuleState) -> int:
    owner = dict(getattr(self, "_context_expert_owner_metadata", {}) or {})
    identity = "|".join((
        str(owner.get("expert_id", owner.get("ma_chuyen_gia", "independent_expert"))),
        str(owner.get("context_id", owner.get("ma_context", "unknown_context"))),
        str(getattr(module, "name", "m1_thinking")),
        str(getattr(self, "input_size", 0)), str(getattr(self, "output_size", 0)),
    ))
    return int.from_bytes(hashlib.sha256(identity.encode("utf-8")).digest()[:8], "little")


def _v186_seed_fingerprint(self: ChuyenGiaPolicy, module: ModuleState) -> str:
    """Fingerprint the cloned expert surface before installing V186 tensors."""
    digest = hashlib.sha256()
    owner = dict(getattr(self, "_context_expert_owner_metadata", {}) or {})
    digest.update(repr(sorted((str(key), str(value)) for key, value in owner.items())).encode("utf-8"))
    for name, value in sorted(module._rnn_optimizer_parameters().items()):
        if str(name).startswith(TENSOR_RULE_PARAMETER_PREFIX):
            continue
        array = np.ascontiguousarray(np.asarray(value, dtype=np.float32))
        digest.update(str(name).encode("utf-8"))
        digest.update(repr(array.shape).encode("ascii"))
        digest.update(array.tobytes())
    return digest.hexdigest()


def _v186_install_bank(self: ChuyenGiaPolicy) -> TensorRuleBankState | None:
    module = _v186_canonical_module(self)
    if module is None:
        return None
    bank = getattr(module, "tensor_rule_bank", None)
    enabled = bool(getattr(self, "tensor_rule_enabled", False))
    if not isinstance(bank, TensorRuleBankState):
        if not enabled:
            module.tensor_rule_bank = None
            return None
        source_fingerprint = _v186_seed_fingerprint(self, module)
        bank_seed = int.from_bytes(hashlib.sha256(
            f"{_v186_bank_seed(self, module)}|{source_fingerprint}".encode("utf-8")
        ).digest()[:8], "little")
        bank = TensorRuleBankState.seed(
            seed=bank_seed,
            sequence_length=int(getattr(self, "tensor_rule_sequence_length", 32) or 32),
            input_size=int(getattr(self, "tensor_rule_input_size", 78) or 78),
            hidden_size=int(getattr(self, "tensor_rule_hidden_size", 64) or 64),
            encoder_layers=int(getattr(self, "tensor_rule_encoder_layers", 2) or 2),
            attention_heads=int(getattr(self, "tensor_rule_attention_heads", 4) or 4),
            ffn_size=int(getattr(self, "tensor_rule_ffn_size", 128) or 128),
            max_rules=int(getattr(self, "tensor_rule_max_rules", 16) or 16),
            initial_rules=int(getattr(self, "tensor_rule_initial_rules", 2) or 2),
            min_valid_length=int(getattr(self, "tensor_rule_min_valid_length", 16) or 16),
            unknown_membership=float(getattr(self, "tensor_rule_unknown_membership", 0.55) or 0.55),
            membership_temperature=float(getattr(
                self, "tensor_rule_membership_temperature", 0.10
            ) or 0.10),
            motif_distance_weight=float(getattr(
                self, "tensor_rule_motif_distance_weight", 0.75
            ) or 0.0),
            utility_assignment_temperature=float(getattr(
                self, "tensor_rule_utility_assignment_temperature", 0.15
            ) or 0.15),
            authority=str(getattr(self, "tensor_rule_authority", "telemetry") or "telemetry"),
            actor_residual_clip=float(getattr(self, "tensor_rule_actor_residual_clip", 0.25) or 0.25),
            effective_batch_size=int(getattr(self, "tensor_rule_effective_batch_size", 64) or 64),
            ready_gradient_norm_budget=float(getattr(
                self, "tensor_rule_ready_gradient_norm_budget", 0.50
            ) or 0.50),
            component_size=int(getattr(self, "tensor_rule_component_size", 16) or 16),
            action_latent_size=int(getattr(self, "tensor_rule_action_latent_size", 32) or 32),
            counterfactual_encoder_credit_scale=float(getattr(
                self, "tensor_rule_counterfactual_encoder_credit_scale", 0.25
            )),
            lifecycle_encoder_credit_scale=float(getattr(
                self, "tensor_rule_lifecycle_encoder_credit_scale", 0.0
            )),
            utility_contrastive_margin=float(getattr(
                self, "tensor_rule_utility_contrastive_margin", 0.20
            )),
            seed_fingerprint=source_fingerprint,
        )
        module.tensor_rule_bank = bank
    bank.ensure_compatible()
    expected_geometry = (
        int(getattr(self, "tensor_rule_sequence_length", 32) or 32),
        int(getattr(self, "tensor_rule_input_size", 78) or 78),
        int(getattr(self, "tensor_rule_hidden_size", 64) or 64),
        int(getattr(self, "tensor_rule_encoder_layers", 2) or 2),
        int(getattr(self, "tensor_rule_attention_heads", 4) or 4),
        int(getattr(self, "tensor_rule_ffn_size", 128) or 128),
        int(getattr(self, "tensor_rule_max_rules", 16) or 16),
        int(getattr(self, "tensor_rule_component_size", 16) or 16),
        int(getattr(self, "tensor_rule_action_latent_size", 32) or 32),
    )
    actual_geometry = (
        bank.sequence_length, bank.input_size, bank.hidden_size, bank.encoder_layers,
        bank.attention_heads, bank.ffn_size, bank.max_rules,
        bank.component_size, bank.action_latent_size,
    )
    if enabled and actual_geometry != expected_geometry:
        raise ValueError(
            "tensor-rule checkpoint geometry differs from active config; clone a fresh candidate"
        )
    bank.authority = str(getattr(self, "tensor_rule_authority", bank.authority) or "telemetry").lower()
    if bank.authority not in TENSOR_RULE_AUTHORITIES:
        bank.authority = "telemetry"
    bank.min_valid_length = int(np.clip(
        getattr(self, "tensor_rule_min_valid_length", bank.min_valid_length), 1, bank.sequence_length
    ))
    bank.unknown_membership = float(np.clip(
        getattr(self, "tensor_rule_unknown_membership", bank.unknown_membership), 0.0, 1.0
    ))
    bank.membership_temperature = float(np.clip(getattr(
        self, "tensor_rule_membership_temperature", bank.membership_temperature,
    ), 0.02, 2.0))
    bank.motif_distance_weight = float(np.clip(getattr(
        self, "tensor_rule_motif_distance_weight", bank.motif_distance_weight,
    ), 0.0, 1.0))
    bank.utility_assignment_temperature = float(np.clip(getattr(
        self, "tensor_rule_utility_assignment_temperature",
        bank.utility_assignment_temperature,
    ), 0.02, 2.0))
    bank.ready_gradient_norm_budget = float(np.clip(getattr(
        self, "tensor_rule_ready_gradient_norm_budget",
        bank.ready_gradient_norm_budget,
    ), 0.01, 10.0))
    bank.actor_residual_clip = float(np.clip(
        getattr(self, "tensor_rule_actor_residual_clip", bank.actor_residual_clip), 0.0, 2.0
    ))
    bank.trade_margin_r = float(np.clip(
        getattr(self, "tensor_rule_trade_margin_r", bank.trade_margin_r), -3.0, 3.0
    ))
    bank.effective_batch_size = max(1, int(
        getattr(self, "tensor_rule_effective_batch_size", bank.effective_batch_size) or 64
    ))
    bank.counterfactual_encoder_credit_scale = float(np.clip(getattr(
        self, "tensor_rule_counterfactual_encoder_credit_scale",
        bank.counterfactual_encoder_credit_scale,
    ), 0.0, 1.0))
    bank.lifecycle_encoder_credit_scale = float(np.clip(getattr(
        self, "tensor_rule_lifecycle_encoder_credit_scale",
        bank.lifecycle_encoder_credit_scale,
    ), 0.0, 1.0))
    bank.utility_contrastive_margin = float(np.clip(getattr(
        self, "tensor_rule_utility_contrastive_margin", bank.utility_contrastive_margin,
    ), -0.5, 0.95))
    self.artifact_version = max(
        int(getattr(self, "artifact_version", 0) or 0), TENSOR_RULE_ARTIFACT_VERSION
    )
    return bank


def _v186_policy_ensure(self: ChuyenGiaPolicy, target_input_size: int | None = None) -> None:
    _V186_PRIOR_ENSURE(self, target_input_size=target_input_size)
    defaults = {
        "tensor_rule_enabled": False, "tensor_rule_authority": "telemetry",
        "tensor_rule_sequence_length": 32, "tensor_rule_input_size": 78,
        "tensor_rule_hidden_size": 64, "tensor_rule_encoder_layers": 2,
        "tensor_rule_attention_heads": 4, "tensor_rule_ffn_size": 128,
        "tensor_rule_max_rules": 16, "tensor_rule_initial_rules": 2,
        "tensor_rule_min_valid_length": 16, "tensor_rule_unknown_membership": 0.55,
        "tensor_rule_membership_temperature": 0.10,
        "tensor_rule_ready_gradient_norm_budget": 0.50,
        "tensor_rule_motif_distance_weight": 0.75,
        "tensor_rule_utility_assignment_temperature": 0.15,
        "tensor_rule_actor_residual_clip": 0.25, "tensor_rule_trade_margin_r": 0.10,
        "tensor_rule_entry_lcb_gate_enabled": False,
        "tensor_rule_effective_batch_size": 64,
        "tensor_rule_component_size": 16, "tensor_rule_action_latent_size": 32,
        "tensor_rule_counterfactual_encoder_credit_scale": 0.25,
        "tensor_rule_lifecycle_encoder_credit_scale": 0.0,
        "tensor_rule_utility_contrastive_margin": 0.20,
    }
    for name, value in defaults.items():
        if not hasattr(self, name):
            setattr(self, name, value)
    authority = str(getattr(self, "tensor_rule_authority", "telemetry") or "telemetry").lower()
    self.tensor_rule_authority = authority if authority in TENSOR_RULE_AUTHORITIES else "telemetry"
    self._tensor_rule_sequence_counter = max(
        0, int(getattr(self, "_tensor_rule_sequence_counter", 0) or 0)
    )
    _v186_install_bank(self)
    if bool(getattr(self, "direct_rnn_state_memory_enabled", False)):
        self.artifact_version = max(
            int(getattr(self, "artifact_version", 0) or 0),
            STATE_ALIAS_MEMORY_ARTIFACT_VERSION,
        )


def _v186_policy_configure(self: ChuyenGiaPolicy, settings: object | None = None) -> None:
    _V186_PRIOR_CONFIGURE(self, settings)
    if settings is not None:
        # ``configure_learning_integrity`` is also a public construction path
        # used by debug/candidate clones.  Keep the optimizer contract complete
        # here instead of relying on the production factory to have copied the
        # Direct-RNN fields beforehand.
        optimizer_names = (
            "direct_rnn_adamw_enabled", "direct_rnn_adamw_learning_rate",
            "direct_rnn_adamw_weight_decay", "direct_rnn_adam_beta1",
            "direct_rnn_adam_beta2", "direct_rnn_adam_epsilon",
            "direct_rnn_gradient_clip", "direct_rnn_cosine_min_factor",
            "direct_rnn_cosine_cycle_steps", "direct_rnn_full_rl_enabled",
            "direct_rnn_rl_temporal_bptt_steps",
            *STATE_ALIAS_MEMORY_CONFIG_NAMES,
        )
        optimizer_config: dict[str, object] = {}
        for name in optimizer_names:
            if hasattr(settings, name):
                value = getattr(settings, name)
                setattr(self, name, value)
                optimizer_config[name] = value
        if optimizer_config:
            for module in getattr(self, "modules", ()) or ():
                module.configure_rnn_adamw_cosine(optimizer_config)
        for name in _V186_CONFIG_NAMES:
            if hasattr(settings, name):
                setattr(self, name, getattr(settings, name))
        if bool(getattr(self, "tensor_rule_enabled", False)):
            # The tensor encoder becomes the sole owner of these representation
            # objectives in V186; legacy heads remain loader-compatible only.
            self.direct_rnn_rl_auxiliary_enabled = False
            self.direct_rnn_rl_conditioned_representation_enabled = False
            self.direct_rnn_rl_counterfactual_representation_enabled = False
    _v186_policy_ensure(self, target_input_size=getattr(self, "input_size", None))


def _v186_policy_copy(self: ChuyenGiaPolicy) -> ChuyenGiaPolicy:
    copied = _V186_PRIOR_COPY(self)
    for name in _V186_CONFIG_NAMES:
        setattr(copied, name, copylib.deepcopy(getattr(self, name, getattr(copied, name, None))))
    copied._tensor_rule_sequence_counter = int(
        getattr(self, "_tensor_rule_sequence_counter", 0) or 0
    )
    copied._tensor_rule_last_sequence_fingerprint = str(
        getattr(self, "_tensor_rule_last_sequence_fingerprint", "") or ""
    )
    copied.artifact_version = max(
        int(getattr(copied, "artifact_version", 0) or 0),
        TENSOR_RULE_ARTIFACT_VERSION if bool(getattr(copied, "tensor_rule_enabled", False)) else 0,
        STATE_ALIAS_MEMORY_ARTIFACT_VERSION
        if bool(getattr(copied, "direct_rnn_state_memory_enabled", False)) else 0,
    )
    _v186_policy_ensure(copied)
    return copied


def _v186_policy_reset(self: ChuyenGiaPolicy) -> None:
    _V186_PRIOR_RESET(self)
    # This is deliberately run-local.  Checkpoint evidence and a previous
    # MT5 window must never decide which side gets less exploration in the
    # next independent evaluation window.
    self._five_live_owner_outcomes = {}
    self._five_live_owner_outcome_ids = set()
    self._five_live_action_outcomes = {}
    self._direct_rnn_rl_lifecycle_queued = 0
    self._direct_rnn_rl_preference_queued = 0
    self._direct_rnn_rl_lifecycle_batches = 0
    self._direct_rnn_rl_preference_batches = 0
    self._direct_rnn_rl_optimizer_updated_modules = 0
    self._direct_rnn_rl_last_batch = {}
    self._tensor_rule_sequence_counter = 0
    self._tensor_rule_last_sequence_fingerprint = ""
    module = _v186_canonical_module(self)
    bank = getattr(module, "tensor_rule_bank", None) if module is not None else None
    if isinstance(bank, TensorRuleBankState):
        bank.pending_regime = []
        bank.ready_regime = []
        bank.decision_count = 0
        bank.unknown_count = 0


def _v186_rule_action_mask(trace: StepTrace, action_count: int) -> np.ndarray:
    mask = np.asarray(tuple(getattr(trace, "allowed_action_mask", ()) or ()), dtype=bool).reshape(-1)
    if mask.size < action_count:
        details = dict(getattr(trace, "action_details", {}) or {})
        mask = np.asarray(details.get("direct_rnn_rl_action_mask", ()), dtype=bool).reshape(-1)
    if mask.size < action_count:
        mask = np.ones(action_count, dtype=bool)
    else:
        mask = mask[:action_count].copy()
    if action_count:
        mask[0] = True
    return mask


def _curriculum_apply_timing_veto(
    self: ChuyenGiaPolicy, trace: StepTrace
) -> StepTrace:
    permissions = _policy_curriculum_permissions(self)
    details = dict(getattr(trace, "action_details", {}) or {})
    if permissions is None:
        return trace
    details["curriculum"] = {
        "enabled": True, "stage": permissions.stage,
        "permissions": permissions.as_dict(),
    }
    if permissions.timing_runtime != "veto_only":
        details["curriculum_timing_veto"] = {
            "applied": False, "veto": False, "reason": "shadow",
        }
        return replace(trace, action_details=details)
    output = np.asarray(trace.selected_action, dtype=float).copy()
    action_count = min(ACTION_COUNT, output.size)
    proposed = int(np.argmax(output[:action_count])) if action_count else 0
    module = _v186_canonical_module(self)
    hidden = np.asarray(getattr(module, "last_output_hidden", ()), dtype=float).reshape(-1) \
        if module is not None else np.zeros(0, dtype=float)
    rule_timing = dict(getattr(trace, "tensor_rule_trace", {}) or {}).get(
        "timing_predictions", {}
    )
    if isinstance(rule_timing, Mapping) and str(proposed) in rule_timing:
        prediction = dict(rule_timing[str(proposed)] or {})
        enter_probability = float(prediction.get("enter_probability", 0.0) or 0.0)
        timing_advantage_r = float(prediction.get("timing_advantage_r", 0.0) or 0.0)
    elif bool(getattr(self, "tensor_rule_enabled", False)):
        details["curriculum_timing_veto"] = {
            "applied": False, "veto": False, "reason": "awaiting_tensor_rule_forward",
            "proposed_action": proposed,
        }
        return replace(trace, action_details=details)
    elif (
        module is not None and proposed in ENTRY_PREFERENCE_ACTIONS[1:]
        and hidden.size == module.hidden_size
        and np.asarray(getattr(module, "auxiliary_w", None)).shape
        == (AUXILIARY_OUTPUT_COUNT, module.hidden_size)
    ):
        logits = np.asarray(module.auxiliary_w @ hidden + module.auxiliary_b, dtype=float)
        enter_index = AUXILIARY_TARGET_NAMES.index(
            f"action_{proposed}_enter_now_probability"
        )
        advantage_index = AUXILIARY_TARGET_NAMES.index(
            f"action_{proposed}_timing_advantage_r"
        )
        enter_probability = 1.0 / (1.0 + float(np.exp(-np.clip(logits[enter_index], -30.0, 30.0))))
        timing_advantage_r = float(np.clip(logits[advantage_index], -1.0, 1.0) * 3.0)
    else:
        enter_probability = timing_advantage_r = 0.0
    if (
        proposed not in ENTRY_PREFERENCE_ACTIONS[1:]
        or (not isinstance(rule_timing, Mapping) or str(proposed) not in rule_timing)
        and (module is None or hidden.size != module.hidden_size)
    ):
        details["curriculum_timing_veto"] = {
            "applied": False, "veto": False, "reason": "head_or_entry_unavailable",
            "proposed_action": proposed,
        }
        return replace(trace, action_details=details)
    state = getattr(self, "curriculum_state", CurriculumState())
    final_action, audit = timing_veto_decision(
        proposed_action=proposed,
        enter_probability=enter_probability,
        timing_advantage_r=timing_advantage_r,
        support=int(getattr(state, "timing_support", 0) or 0),
        calibration_error=float(getattr(state, "timing_calibration_error_ema", 1.0)),
        probability_threshold=float(getattr(
            self, "curriculum_timing_probability_threshold", 0.65
        ) or 0.65),
        advantage_lcb_threshold_r=float(getattr(
            self, "curriculum_timing_advantage_lcb_r", 0.05
        ) or 0.0),
        uncertainty_z=float(getattr(
            self, "curriculum_timing_uncertainty_z", 1.28
        ) or 0.0),
    )
    details["curriculum_timing_veto"] = audit
    if final_action == proposed:
        return replace(trace, action_details=details)
    # Veto only: preserve the proposed action and its behavior probability in
    # telemetry, but emit HOLD and make the trace actor-ineligible.
    if output.size >= 7:
        output[1:7] = np.minimum(output[1:7], float(output[0]) - 8.0)
    details["curriculum_timing_proposed_action"] = proposed
    details["policy_output_action_index"] = HOLD_ACTION
    details["semantic_action"] = HOLD_ACTION
    details["policy_action"] = HOLD_ACTION
    details["direct_rnn_rl_policy_eligible"] = False
    return replace(
        trace, selected_action=output, candidate_actions=output.reshape(1, -1),
        action_details=details,
    )


def _v186_policy_act(
    self: ChuyenGiaPolicy,
    observation: np.ndarray,
    goal: np.ndarray | None = None,
) -> StepTrace:
    trace = _V186_PRIOR_ACT(self, observation, goal)
    _v186_policy_ensure(self)
    trace = _curriculum_apply_timing_veto(self, trace)
    if not bool(getattr(self, "tensor_rule_enabled", False)):
        return trace
    bank = _v186_install_bank(self)
    if not isinstance(bank, TensorRuleBankState):
        return trace
    permissions = _policy_curriculum_permissions(self)
    if permissions is not None:
        bank.authority = permissions.tensor_rule_authority
    timing = dict(getattr(trace, "timing_trace", {}) or {})
    sequence = np.asarray(timing.get("sequence_tensor", ()), dtype=float)
    valid_length = int(timing.get("sequence_valid_length", 0) or 0)
    input_contract = str(
        timing.get("tensor_rule_input_schema_fingerprint", bank.input_schema_fingerprint)
        or bank.input_schema_fingerprint
    )
    result = bank.forward(
        sequence, valid_length, training=False,
        input_schema_fingerprint=input_contract,
    )
    payload = result.payload()
    payload["timing_predictions"] = {
        str(action): {
            "enter_probability": float(1.0 / (1.0 + np.exp(-np.clip(
                result.auxiliary_logits[AUXILIARY_TARGET_NAMES.index(
                    f"action_{action}_enter_now_probability"
                )], -30.0, 30.0
            )))),
            "timing_advantage_r": float(np.clip(
                result.auxiliary_logits[AUXILIARY_TARGET_NAMES.index(
                    f"action_{action}_timing_advantage_r"
                )], -1.0, 1.0
            ) * 3.0),
        }
        for action in ENTRY_PREFERENCE_ACTIONS[1:]
    }
    payload["input_schema_fingerprint"] = input_contract
    payload["seed_fingerprint"] = str(bank.seed_fingerprint)
    payload["authority"] = str(bank.authority)
    payload["expert_owner"] = dict(getattr(self, "_context_expert_owner_metadata", {}) or {})
    self._tensor_rule_sequence_counter += 1
    if (
        bool(getattr(self, "_learning_enabled", True))
        and result.input_fingerprint not in {"", "invalid"}
        and result.input_fingerprint != str(getattr(self, "_tensor_rule_last_sequence_fingerprint", ""))
    ):
        bank.observe_regime_decision(
            sequence, valid_length, str(timing.get("current_regime", "UNKNOWN")),
            sequence_id=int(self._tensor_rule_sequence_counter),
        )
        self._tensor_rule_last_sequence_fingerprint = result.input_fingerprint
    output = np.asarray(getattr(trace, "selected_action", np.zeros(self.output_size)), dtype=float).copy()
    details = dict(getattr(trace, "action_details", {}) or {})
    management_only = bool(details.get("direct_rnn_management_control_only", False))
    authority = str(bank.authority)
    action_count = min(ACTION_COUNT, output.size)
    mask = _v186_rule_action_mask(trace, action_count)
    entry_mask = mask[:min(7, action_count)].copy()
    applied = False
    selected = int(np.argmax(output[:action_count])) if action_count else 0
    entry_lcb_gate_enabled = bool(getattr(self, "tensor_rule_entry_lcb_gate_enabled", False))
    exploration_sampled = bool(details.get("direct_rnn_rl_exploration_sampled", False))
    behavior_selected = int(details.get("direct_rnn_rl_policy_action_index", selected) or 0)
    exploration_entry = exploration_sampled and 1 <= behavior_selected <= 6
    gate_reason = "disabled"
    qualified_actions: list[int] = []
    if not management_only and entry_mask.size == 7 and np.any(entry_mask[1:]):
        base_entry = output[:7].copy()
        qualified_actions = [
            action_index
            for action_index, lcb_r in enumerate(result.action_lcb_r, start=1)
            if bool(entry_mask[action_index]) and float(lcb_r) > float(bank.trade_margin_r)
        ]
        if entry_lcb_gate_enabled and exploration_sampled:
            # Exploration is the only source of action-labelled evidence during
            # cold start. Preserve its chosen HOLD/entry and its behavior-policy
            # provenance instead of replacing it with the rule branch.
            selected = int(np.clip(behavior_selected, 0, action_count - 1))
            if action_count > 1:
                competitor = float(np.max(np.delete(output[:action_count], selected)))
                if float(output[selected]) <= competitor:
                    # The prior surface may be float32, where nextafter ties can
                    # disappear after later conversions. Reassert the sampled
                    # command on this float64 bridge vector.
                    output[selected] = float(np.nextafter(competitor, np.inf))
            gate_reason = "exploration_entry" if exploration_entry else "exploration_hold"
        elif entry_lcb_gate_enabled and result.unknown:
            # An UNKNOWN rule has no calibrated evidence with which to justify
            # a greedy entry. Force HOLD while leaving management actions alone.
            if selected <= 6:
                output[1:7] = np.minimum(output[1:7], float(output[0]) - 8.0)
                selected = 0
                applied = True
            gate_reason = "unknown_hold"
        elif authority == "residual" and not result.unknown:
            centered = result.action_lcb_r - float(np.mean(result.action_lcb_r))
            residual = np.clip(centered, -bank.actor_residual_clip, bank.actor_residual_clip)
            output[1:7] += residual
            if entry_lcb_gate_enabled:
                for action_index in range(1, 7):
                    if action_index not in qualified_actions:
                        output[action_index] = min(output[action_index], float(output[0]) - 8.0)
                gate_reason = "qualified_entry" if qualified_actions else "no_qualified_entry_hold"
            legal_scores = np.where(entry_mask, output[:7], -np.inf)
            selected = int(np.argmax(legal_scores))
            applied = True
            payload["actor_residual"] = [0.0, *[float(value) for value in residual.tolist()]]
        elif authority == "primary":
            if result.unknown or float(np.max(result.action_lcb_r)) <= bank.trade_margin_r:
                rule_scores = np.full(7, -8.0, dtype=float)
                rule_scores[0] = 0.0
                selected = 0
            else:
                residual = np.clip(base_entry[1:7], -bank.actor_residual_clip, bank.actor_residual_clip)
                rule_scores = np.concatenate(([0.0], result.action_lcb_r - bank.trade_margin_r + residual))
                rule_scores = np.where(entry_mask, rule_scores, -8.0)
                selected = int(np.argmax(rule_scores))
                payload["actor_residual"] = [0.0, *[float(value) for value in residual.tolist()]]
            output[:7] = rule_scores
            applied = True
            gate_reason = "primary_rule"
    payload["entry_lcb_gate_enabled"] = bool(entry_lcb_gate_enabled)
    payload["entry_lcb_gate_reason"] = str(gate_reason)
    payload["entry_lcb_gate_applied"] = bool(entry_lcb_gate_enabled and applied)
    payload["entry_lcb_qualified_actions"] = [int(value) for value in qualified_actions]
    payload["action_applied"] = bool(applied)
    payload["selected_action"] = int(selected)
    details["tensor_rule"] = payload
    details["tensor_rule_authority"] = authority
    details["tensor_rule_action_applied"] = bool(applied)
    details["tensor_rule_action_index"] = int(selected)
    details["tensor_rule_entry_lcb_gate_enabled"] = bool(entry_lcb_gate_enabled)
    details["tensor_rule_entry_lcb_gate_reason"] = str(gate_reason)
    details["tensor_rule_entry_lcb_gate_applied"] = bool(entry_lcb_gate_enabled and applied)
    details["tensor_rule_entry_lcb_qualified_actions"] = [int(value) for value in qualified_actions]
    if applied:
        details["policy_output_action_index"] = int(selected)
        details["semantic_action"] = int(selected)
        details["policy_action"] = int(selected)
        details["direct_rnn_rl_policy_action_index"] = int(selected)
        details["direct_rnn_rl_policy_eligible"] = bool(selected >= 7)
        probabilities = np.zeros(max(1, action_count), dtype=float)
        entry_scores = np.where(entry_mask, output[:7], -1e9)
        shifted = entry_scores - float(np.max(entry_scores))
        local = np.exp(np.clip(shifted, -60.0, 60.0))
        local /= max(float(np.sum(local)), 1e-12)
        probabilities[:7] = local
        details["direct_rnn_rl_action_probabilities"] = [float(value) for value in probabilities.tolist()]
        selected_log_prob = float(np.log(max(float(probabilities[selected]), 1e-12)))
    else:
        selected_log_prob = float(getattr(trace, "selected_action_log_prob", 0.0))
    writer = _live_observatory_writer(self)
    if writer is not None:
        writer.emit("tensor_rule_decision", {
            "trace_id": str(trace.trace_id), **payload,
            "bank_summary": bank.summary(),
        })
    result_trace = replace(
        trace,
        selected_action=output,
        candidate_actions=output.reshape(1, -1),
        selected_action_log_prob=selected_log_prob,
        action_details=details,
        tensor_rule_trace=payload,
    )
    return _curriculum_apply_timing_veto(self, result_trace)


def _v186_training_samples(
    bank: TensorRuleBankState,
    batch: Iterable[Mapping[str, object]],
    *,
    include_ready_regime: bool = True,
) -> list[tuple[np.ndarray, int, TensorRuleTargets]]:
    samples: list[tuple[np.ndarray, int, TensorRuleTargets]] = []
    for item in batch:
        if bool(item.get("tensor_rule_preaccumulated", False)):
            continue
        trace = item.get("trace")
        if not isinstance(trace, StepTrace):
            continue
        rule_trace = dict(getattr(trace, "tensor_rule_trace", {}) or {})
        if (
            int(rule_trace.get("schema_version", 0) or 0) < 1
            or str(rule_trace.get("input_schema_fingerprint", "") or "")
            != str(bank.input_schema_fingerprint)
            or str(rule_trace.get("seed_fingerprint", "") or "")
            != str(bank.seed_fingerprint)
        ):
            continue
        timing = dict(getattr(trace, "timing_trace", {}) or {})
        sequence = np.asarray(timing.get("sequence_tensor", ()), dtype=float)
        valid_length = int(timing.get("sequence_valid_length", 0) or 0)
        if sequence.shape != (bank.sequence_length, bank.input_size):
            continue
        target = TensorRuleTargets.from_item(item)
        if (
            target.entry_utilities is None
            and target.realized_r is None
            and not np.any(target.auxiliary_mask)
        ):
            continue
        samples.append((sequence.copy(), valid_length, target))
    if include_ready_regime:
        samples.extend(bank.pop_ready_regime(limit=16))
    return samples


def _v186_accumulate_preference_item(
    self: ChuyenGiaPolicy,
    item: dict[str, object],
) -> dict[str, object]:
    """Learn delayed preferences independently, but defer the AdamW write.

    Preference labels normally mature at the end of a tester run.  Requiring
    another lifecycle-balanced actor batch before TensorRule can even see them
    silently strands valid abstraction evidence.  This queue builds TensorRule
    gradients in 32-sample microbatches; only a later canonical lifecycle
    AdamW step may import the ready direction, preserving the sole-writer rule.
    """
    if not bool(getattr(self, "tensor_rule_enabled", False)):
        return {"accepted": False, "reason": "tensor_rule_disabled"}
    bank = _v186_install_bank(self)
    module = _v186_canonical_module(self)
    if not isinstance(bank, TensorRuleBankState) or module is None:
        return {"accepted": False, "reason": "bank_unavailable"}
    pending = getattr(self, "_tensor_rule_preference_pending_items", None)
    if not isinstance(pending, list):
        pending = []
    pending.append(item)
    microbatch_size = min(32, max(1, int(bank.effective_batch_size)))
    if len(pending) < microbatch_size:
        self._tensor_rule_preference_pending_items = pending[-microbatch_size:]
        return {"accepted": True, "accumulated": False, "pending": len(pending)}
    chunk = list(pending[:microbatch_size])
    self._tensor_rule_preference_pending_items = list(pending[microbatch_size:])
    samples = _v186_training_samples(bank, chunk, include_ready_regime=False)
    gradients, metrics = bank.batch_gradients(samples)
    sample_count = int(metrics.get("samples", 0) or 0)
    ready = bank.accumulate_gradients(gradients, sample_count=sample_count)
    if sample_count:
        for queued_item in chunk:
            queued_item["tensor_rule_preaccumulated"] = True
    if ready:
        directions = dict(getattr(module, "_tensor_rule_pending_directions", {}) or {})
        for key, value in ready.items():
            array = np.asarray(value, dtype=float)
            directions[key] = directions.get(key, np.zeros_like(array)) + array
        module._tensor_rule_pending_directions = directions
    result = {
        "accepted": bool(sample_count),
        "accumulated": bool(sample_count),
        "samples": sample_count,
        "effective_batch_pending": int(bank.gradient_sample_count),
        "optimizer_directions_ready": bool(ready),
        "optimizer_write_deferred_to_lifecycle": True,
        "ready_gradient_raw_norm": float(bank.last_ready_gradient_raw_norm) if ready else 0.0,
        "ready_gradient_clip_factor": float(bank.last_ready_gradient_clip_factor) if ready else 1.0,
        "ready_gradient_norm_budget": float(bank.ready_gradient_norm_budget),
    }
    event = {
        "round": int(getattr(self, "revision", 0)),
        "type": "tensor_rule_preference_accumulated",
        "metrics": result,
        "sole_writer": "full_lifecycle_rl_adamw",
    }
    self.growth_events.append(event)
    writer = _live_observatory_writer(self)
    if writer is not None:
        writer.emit("tensor_rule_preference_accumulated", event)
    return result


def _v186_apply_full_rl_batch(
    self: ChuyenGiaPolicy,
    batch: list[dict[str, object]],
    *args: object,
    **kwargs: object,
) -> int:
    bank = _v186_install_bank(self) if bool(getattr(self, "tensor_rule_enabled", False)) else None
    module = _v186_canonical_module(self)
    metrics: dict[str, object] = {}
    if isinstance(bank, TensorRuleBankState) and module is not None:
        samples = _v186_training_samples(bank, batch)
        gradients, local_metrics = bank.batch_gradients(samples)
        # A lifecycle-balanced batch may consume a delayed preference before
        # its independent 32-item microbatch fills.  Mark it here as well so
        # the later microbatch cannot train TensorRule on the same evidence a
        # second time (the actor queue itself remains unchanged).
        if int(local_metrics.get("samples", 0) or 0) > 0:
            for batch_item in batch:
                if bool(batch_item.get("entry_preference_only", False)):
                    batch_item["tensor_rule_preaccumulated"] = True
        ready = bank.accumulate_gradients(
            gradients, sample_count=int(local_metrics.get("samples", 0) or 0)
        )
        metrics = {
            **local_metrics,
            "effective_batch_pending": int(bank.gradient_sample_count),
            "optimizer_directions_ready": bool(ready),
            "ready_gradient_raw_norm": (
                float(bank.last_ready_gradient_raw_norm) if ready else 0.0
            ),
            "ready_gradient_clip_factor": (
                float(bank.last_ready_gradient_clip_factor) if ready else 1.0
            ),
            "ready_gradient_norm_budget": float(bank.ready_gradient_norm_budget),
        }
        if ready:
            pending = dict(getattr(module, "_tensor_rule_pending_directions", {}) or {})
            for key, value in ready.items():
                array = np.asarray(value, dtype=float)
                pending[key] = pending.get(key, np.zeros_like(array)) + array
            module._tensor_rule_pending_directions = pending
    updated = _V186_PRIOR_APPLY_FULL_RL_BATCH(self, batch, *args, **kwargs)
    if isinstance(bank, TensorRuleBankState):
        event = {
            "round": int(getattr(self, "revision", 0)),
            "type": "tensor_rule_full_rl_batch",
            "updated_modules": int(updated),
            "metrics": metrics,
            "bank": bank.summary(),
            "sole_writer": "full_lifecycle_rl_adamw",
        }
        self.growth_events.append(event)
        writer = _live_observatory_writer(self)
        if writer is not None:
            writer.emit("tensor_rule_batch", event)
    return int(updated)


def _v186_evolve_tensor_rules(
    self: ChuyenGiaPolicy,
    validation: Mapping[str, object],
    *,
    round_boundary: bool = False,
) -> dict[str, object]:
    bank = _v186_install_bank(self)
    module = _v186_canonical_module(self)
    if not isinstance(bank, TensorRuleBankState) or module is None:
        return {"changed": False, "reason": "tensor_rule_disabled"}
    result = bank.evolve_at_round_boundary(validation, round_boundary=round_boundary)
    if bool(result.get("changed", False)):
        for key in ("source", "target"):
            if key in result:
                bank.reset_slot_optimizer_state(
                    module.rnn_optimizer_m, module.rnn_optimizer_v, int(result[key])
                )
        self.artifact_version = max(int(self.artifact_version), TENSOR_RULE_ARTIFACT_VERSION)
        self.growth_events.append({
            "round": int(getattr(self, "revision", 0)),
            "type": "tensor_rule_topology_change",
            **dict(result),
        })
    return dict(result)


def _v186_set_tensor_rule_authority(
    self: ChuyenGiaPolicy,
    authority: str,
    *,
    evidence: Mapping[str, object] | None = None,
) -> dict[str, object]:
    target = str(authority or "telemetry").lower()
    if target not in TENSOR_RULE_AUTHORITIES:
        return {"changed": False, "reason": "invalid_authority"}
    bank = _v186_install_bank(self)
    if not isinstance(bank, TensorRuleBankState):
        return {"changed": False, "reason": "tensor_rule_disabled"}
    proof = dict(evidence or {})
    active = np.flatnonzero(bank.active_mask)
    residual_ready = bool(
        active.size >= 2
        and np.sum(bank.rule_support[active]) >= 90
        and np.count_nonzero(bank.rule_support[active] >= 30) >= 2
        and np.all(np.sum(bank.temporal_fold_support[active], axis=0) >= 20)
        and np.max(np.sum(bank.rule_action_support[active], axis=0), initial=0.0) >= 30
    )
    reasons: list[str] = []
    if target in {"residual", "primary"} and not residual_ready:
        reasons.append("rule_support_or_temporal_folds_not_ready")
    if target == "primary":
        if int(getattr(bank, "calibration_rounds", 0) or 0) < 1:
            reasons.append("uncertainty_not_calibrated_on_temporal_folds")
        required = {
            "real_tick_matrix_3x3": True,
            "source_hash_unchanged": True,
            "reconciled": True,
            "feature_parity": True,
            "policy_expectancy_lcb_non_negative": True,
            "paired_delta_lcb_at_least_0_01r": True,
            "min_30_policy_origin_trades_each_window": True,
            "all_promoted_scopes_support_30_lcb_non_negative": True,
            "first_half_lcb_non_negative": True,
            "second_half_lcb_non_negative": True,
            "drawdown_at_most_10pct": True,
            "zero_negative_critical_scopes": True,
            "rule_rank_no_sign_reversal": True,
            "same_rule_present_in_three_temporal_folds": True,
            "uncertainty_calibrated": True,
        }
        reasons.extend(name for name, expected in required.items() if bool(proof.get(name, False)) is not expected)
    if reasons:
        return {"changed": False, "reason": "promotion_gate_failed", "reasons": reasons}
    bank.authority = target
    self.tensor_rule_authority = target
    bank.bank_version += 1
    return {"changed": True, "authority": target, "bank_version": int(bank.bank_version)}


def _v186_tensor_rule_summary(self: ChuyenGiaPolicy) -> dict[str, object]:
    bank = _v186_install_bank(self)
    return bank.summary() if isinstance(bank, TensorRuleBankState) else {
        "schema_version": 1, "enabled": False, "authority": "telemetry",
    }


ChuyenGiaPolicy.ensure_compatible = _v186_policy_ensure
ChuyenGiaPolicy.configure_learning_integrity = _v186_policy_configure
ChuyenGiaPolicy.copy = _v186_policy_copy
ChuyenGiaPolicy.reset_runtime_state = _v186_policy_reset
ChuyenGiaPolicy.act = _v186_policy_act
ChuyenGiaPolicy._apply_direct_rnn_full_rl_batch = _v186_apply_full_rl_batch
ChuyenGiaPolicy.evolve_tensor_rules = _v186_evolve_tensor_rules
ChuyenGiaPolicy.set_tensor_rule_authority = _v186_set_tensor_rule_authority
ChuyenGiaPolicy.tensor_rule_summary = _v186_tensor_rule_summary
